globalThis.KENGURU_LEGACY = [[2001,"3–4 классы",[[816,96,"Кенгуру складывает двести сотен и один. Подскажите правильный ответ.",{"0":[33.8,64.9,31.4,26.3],"1":[181.0,64.9,31.4,26.3],"2":[350.2,64.9,32.6,26.3],"3":[500.2,64.9,32.7,26.3],"4":[650.3,64.9,31.7,26.3]},"D","Двести сотен",[["Считаем сотни","В одной сотне 100. Значит, двести сотен — это 200 × 100 = 20 000."],["Прибавляем один","20 000 + 1 = 20 001."]],""],[816,213,"",{},"B","Зеркальная пятёрка",[["Ищем правило","Каждый рисунок состоит из цифры и её отражения в вертикальном зеркале. Например, у двойки две наклонные черты сходятся внизу."],["Соединяем половины","У пятёрки совмещаем вертикальные штрихи. Верхние черты расходятся влево и вправо, а круглые части вместе образуют овал. Так устроен рисунок B."]],""],[816,97,"У Йозефа было 7 палочек. Он разломал одну из них пополам. Сколько теперь у него палочек?",{"0":[33.8,64.9,31.5,26.3],"1":[181.0,64.9,31.5,26.3],"2":[350.3,64.9,32.6,26.3],"3":[519.5,64.9,32.6,26.3],"4":[688.7,64.9,31.3,26.3]},"D","Сломанная палочка",[["Считаем целые","Шесть из семи палочек остались целыми."],["Считаем обломки","Сломанная палочка дала две новые. Всего стало 6 + 2 = 8 палочек."]],""],[816,116,"Катя написала фразу «Я люблю решать задачи», подсчитала количество букв в каждом слове и перемножила полученные числа. Какой результат должен был получиться?",{"0":[33.9,82.9,31.5,26.3],"1":[181.1,82.9,31.5,26.3],"2":[350.4,82.9,32.6,26.3],"3":[519.5,82.9,32.6,26.3],"4":[688.7,82.9,31.4,26.3]},"E","Буквы в словах",[["Считаем буквы","В слове «я» 1 буква, в слове «люблю» — 5, в слове «решать» — 6 и в слове «задачи» — 6."],["Перемножаем","1 × 5 × 6 × 6 = 5 × 36 = 180."]],""],[816,137,"родился, когда Ане исполнилось 3 года. Сколько лет будет Пете, когда Аня будет вдвое его старше?",{"0":[33.8,80.8,31.4,26.3],"1":[181.0,80.8,31.4,26.3],"2":[350.2,80.8,32.7,26.3],"3":[33.8,106.5,32.7,26.3],"4":[181.0,106.5,31.4,26.3]},"C","Два дня рождения",[["Замечаем разницу","У Пети и Ани день рождения в один день. Аня всегда на 3 года старше Пети."],["Сравниваем возрасты","Чтобы Аня была вдвое старше, разница в 3 года должна равняться возрасту Пети. Ему будет 3 года, а Ане — 6 лет."]],""],[816,173,"",{},"B","Фигуры на мордочке",[["Рассматриваем детали","Мордочка и глаза круглые, нос квадратный, а зубы образуют прямоугольник."],["Проверяем ушки","У каждого уха два прямых края и дуга со стороны головы. Треугольнику нужны три прямых стороны. Таких фигур на рисунке нет."]],""],[816,93,"С какой скоростью школьник Вова может идти из школы домой? м км м м км",{"0":[33.7,49.8,31.4,26.3],"1":[181.0,49.8,31.4,26.3],"2":[329.2,49.8,32.7,26.3],"3":[488.1,49.8,32.7,26.3],"4":[650.8,49.8,31.4,26.3]},"C","Скорость ходьбы",[["Переводим в километры в час","20 м/с — это 72 км/ч; 1 км/мин — 60 км/ч; 900 м/мин — 54 км/ч. В последнем варианте уже записано 45 км/ч."],["Выбираем скорость пешехода","4 000 м/ч — это 4 км/ч. Такая скорость подходит для обычной ходьбы."]],""],[816,109,"Во дворе школы играют 19 девочек и 12 мальчиков. Какое количество ребят должно к ним присоединиться, чтобы все они могли разбиться на 6 равных команд?",{},"E","Шесть команд",[["Считаем ребят","Во дворе 19 + 12 = 31 ребёнок."],["Собираем равные команды","Для шести команд по пять человек хватило бы 30 детей. Следующее подходящее число — 36, по шесть человек в команде. Нужно ещё 36 − 31 = 5 детей."]],""],[817,187,"Джимми купил в подарок своей маме шоколадное сердечко. Сколько весит эта шоколадка, если каждый квадратик весит 10 г?",{"0":[33.8,89.3,31.4,26.3],"1":[181.0,89.3,31.4,26.3],"2":[350.2,89.3,32.7,26.3],"3":[33.8,116.2,32.7,26.3],"4":[181.0,116.2,31.4,26.3]},"D","Шоколадное сердце",[["Считаем клетки по рядам","Соединяем половинки клеток попарно. В двух верхних рядах получаем 2 и 6 целых клеток. В двух средних рядах — по 8."],["Досчитываем массу","Нижние ряды дают 7 + 5 + 3 + 1 = 16 клеток. Всего 2 + 6 + 8 + 8 + 16 = 40 клеток, а шоколадка весит 40 × 10 = 400 г."]],""],[817,246,"В магазин обуви пришли 4 сороконожки в одинаковых башмачках (у каждой из них по 20 пар ног). У одной из сороконожек не хватало обуви на задней половине ног, у другой – на передней половине, у третьей обуты были только правые ножки, а у четвертой − только левые. Они купили в магазине обувь и ушли полностью обутые. Сколько пар обуви купили сороконожки в магазине?",{"0":[33.9,182.9,31.5,26.3],"1":[181.1,182.9,31.5,26.3],"2":[350.3,182.9,32.6,26.3],"3":[519.5,182.9,32.6,26.3],"4":[688.7,182.9,31.4,26.3]},"C","Обувь сороконожек",[["Считаем босые ножки","У каждой сороконожки 40 ног. У каждой обута половина, поэтому все вместе они купили 4 × 20 = 80 башмачков."],["Собираем пары","На каждую пару идут два башмачка. Всего купили 80 ÷ 2 = 40 пар."]],""],[817,264,"Вика завязала бантик над правым ухом и вертится пред зеркалом. Сколько из следующих изображений можно увидеть в зеркале?",{"0":[33.9,232.4,31.5,26.3],"1":[181.2,232.4,31.5,26.3],"2":[350.4,232.4,32.6,26.3],"3":[519.6,232.4,32.6,26.3],"4":[688.8,232.4,31.3,26.3]},"D","Бант в зеркале",[["Смотрим прямо","Бантик над правым ухом Вики. Когда она смотрит прямо в зеркало, бантик у отражения виден справа от нас, как на третьем рисунке."],["Проверяем повороты","На четвёртом рисунке виден бок с бантом, на втором — бок без банта. Со спины бант в отражении должен быть слева от нас, поэтому первый рисунок отпадает. Подходят три рисунка."]],""],[817,139,"Нескольким кенгуру раздали 50 яблок так, чтобы каждый кенгуру получил хотя бы по одному яблоку и ни у каких двух кенгуру не было поровну яблок. Какое наибольшее количество кенгуру могли получить яблоки?",{"0":[33.7,107.5,31.5,26.3],"1":[181.0,107.5,31.5,26.3],"2":[350.2,107.5,32.6,26.3],"3":[519.4,107.5,32.6,26.3],"4":[688.6,107.5,31.4,26.3]},"B","Яблоки для кенгуру",[["Берём самые маленькие числа","Чтобы накормить как можно больше кенгуру, начнём с 1 яблока и дадим каждому следующему на 1 больше. Для 10 кенгуру потребуется как минимум 1 + 2 + … + 10 = 55 яблок."],["Проверяем девятерых","Для девяти достаточно 1 + 2 + … + 9 = 45 яблок. Оставшиеся 5 отдадим тому, кто получил 9. У всех всё ещё разное количество. Максимум — 9 кенгуру."]],""],[817,166,"Бетти и Кетти путешествуют на суперпоезде. Бетти едет в сто семнадцатом вагоне с начала поезда, а Кетти – в сто тридцать четвертом с конца. Оказалось, что они едут в соседних вагонах. Сколько вагонов могло быть в поезде?",{},"D","Соседние вагоны",[["Выбираем соседей","Бетти едет в вагоне № 117 с начала. Соседний вагон Кетти может иметь номер 116 или 118."],["Считаем от обоих концов","Вместе с вагоном Кетти от начала до неё 116 или 118 вагонов, а от неё до конца — 134. Её вагон посчитан дважды. Получаем 116 + 134 − 1 = 249 или 118 + 134 − 1 = 251. Среди вариантов есть 249."]],""],[817,175,"",{},"E","Повороты фигур",[["Находим общий ряд","В каждой фигуре есть прямой ряд из четырёх кубиков и два выступающих кубика. Один выступ примыкает к концу ряда."],["Сравниваем второй выступ","Начнём счёт с конца, где прикреплён первый выступ. В A, B, C и D второй выступ прикреплён к третьему кубику ряда. В E — ко второму, поэтому поворотом её не совместить с остальными."]],""],[816,220,"Пятеро друзей выясняли, какой сегодня день недели. Андрей сказал: «Позавчера была пятница». Володя сказал: «Послезавтра будет вторник». Сережа сказал: «Вчера была суббота». Дима сказал: «Завтра будет понедельник». Егор сказал: «Сегодня четверг». Один их них ошибся. Кто?",{"0":[33.7,186.5,31.4,26.3],"1":[180.9,186.5,31.4,26.3],"2":[350.1,186.5,32.7,26.3],"3":[519.4,186.5,32.7,26.3],"4":[669.0,186.5,31.4,26.3]},"E","Какой сегодня день?",[["Устанавливаем день","Если вчера была суббота, сегодня воскресенье. Тогда позавчера и правда была пятница, завтра будет понедельник, а послезавтра — вторник."],["Находим ошибку","Четверо друзей назвали дни, которые подходят воскресенью. Только Егор сказал, что сегодня четверг."]],""],[816,97,"На столе лежат пятиугольники и шестиугольники. Всего у них ровно 37 вершин. Сколько пятиугольников на столе?",{"0":[33.8,64.9,31.5,26.3],"1":[181.1,64.9,31.5,26.3],"2":[350.3,64.9,32.6,26.3],"3":[519.5,64.9,32.6,26.3],"4":[688.7,64.9,31.3,26.3]},"E","Пять или шесть вершин",[["Считаем фигуры","У шести фигур было бы не больше 6 × 6 = 36 вершин, а у восьми — не меньше 8 × 5 = 40. Значит, фигур ровно семь."],["Заменяем шестиугольники","Если бы все семь фигур были шестиугольниками, у них было бы 42 вершины. Каждая замена шестиугольника пятиугольником убирает одну вершину. Чтобы получить 37, нужно пять пятиугольников."]],""],[816,123,"Четырехзначное число начинается с цифры 5. Эту цифру переставили в конец числа. Полученное число оказалось на 747 меньше исходного. Какова сумма цифр этого числа?",{"0":[33.8,89.1,31.5,26.3],"1":[181.1,89.1,31.5,26.3],"2":[350.3,89.1,32.6,26.3],"3":[519.5,89.1,32.6,26.3],"4":[688.6,89.1,31.4,26.3]},"D","Пятёрка переезжает",[["Выделяем три цифры","Назовём число из трёх последних цифр хвостом. Исходное число — это 5 000 плюс хвост. После перестановки цифры получаем хвост, умноженный на 10, плюс 5."],["Находим хвост","Разность 747 получается, если из 4 995 вычесть девять хвостов. Поэтому девять хвостов составляют 4 995 − 747 = 4 248, а хвост равен 472."],["Складываем цифры","Цифры числа — 5, 4, 7, 2. Их сумма равна 18."]],""],[816,170,"В ряд стоят три коробки, в каждой по 11 конфет. Я беру по одной конфете из каждой коробки в таком порядке: левая, центральная, правая, центральная, левая, центральная, и так далее до тех пор, пока в центральной коробке не закончатся конфеты. В одной из двух крайних коробок осталось больше конфет. Сколько?",{"0":[33.8,137.8,31.5,26.3],"1":[181.1,137.8,31.5,26.3],"2":[350.3,137.8,32.6,26.3],"3":[519.5,137.8,32.6,26.3],"4":[688.7,137.8,31.3,26.3]},"D","Конфеты в коробках",[["Замечаем чередование","После каждой конфеты из крайней коробки берут конфету из центральной. Поэтому к тому моменту, как из центра взяли все 11 конфет, из крайних взяли тоже 11."],["Считаем по сторонам","Из крайних коробок берут по очереди, начиная с левой. Взяли 6 слева и 5 справа. Справа осталось больше — 11 − 5 = 6 конфет."]],""],[816,147,"На игральном кубике общее число точек на любых двух противоположных гранях равно 7. Дженни склеила столбик из 6 таких кубиков и подсчитала общее число точек на всех наружных гранях. Какое самое большое число она могла получить?",{"0":[33.8,113.5,31.4,26.3],"1":[181.0,113.5,31.4,26.3],"2":[350.3,113.5,32.6,26.3],"3":[519.4,113.5,32.6,26.3],"4":[688.6,113.5,31.4,26.3]},"B","Кубики в столбике",[["Считаем боковые точки","На каждом кубике снаружи четыре боковые грани. Две пары противоположных граней дают 7 + 7 = 14 точек. У шести кубиков сбоку 84 точки."],["Выбираем верх и низ","Верхнюю и нижнюю наружные грани можно обе повернуть шестёркой наружу. Получаем максимум 84 + 6 + 6 = 96 точек."]],""],[816,99,"Сколько существует трехзначных чисел, у которых сумма цифр равна 4?",{"0":[33.7,64.9,31.5,26.3],"1":[181.0,64.9,31.5,26.3],"2":[350.3,64.9,32.6,26.3],"3":[519.4,64.9,32.6,26.3],"4":[688.6,64.9,31.3,26.3]},"A","Сумма цифр четыре",[["Выбираем сотни","В разряде сотен может стоять 1, 2, 3 или 4. Тогда на десятки и единицы остаётся соответственно 3, 2, 1 или 0."],["Перебираем пары","Сумму 3 дают четыре пары: 0 и 3, 1 и 2, 2 и 1, 3 и 0. Для суммы 2 есть три пары, для суммы 1 — две, для суммы 0 — одна. Всего 4 + 3 + 2 + 1 = 10 чисел."]],""],[816,193,"Задачи, оцениваемые в 5 баллов 21. Какое самое маленькое число спичек можно добавить к этой фигуре, чтобы получить точно 11 квадратов?",{"0":[33.7,132.0,31.5,26.3],"1":[211.7,132.0,31.5,26.3],"2":[395.1,132.0,32.6,26.3],"3":[33.7,159.1,32.6,26.3],"4":[211.6,159.1,31.4,26.3]},"A","Квадраты из спичек",[["Считаем готовые квадраты","На рисунке три квадрата со стороной 1 спичка, два со стороной 2 спички и три со стороной 3 спички. Всего восемь."],["Проверяем одну спичку","У квадратов со стороной 2 спички и больше либо все стороны уже есть, либо не хватает хотя бы двух спичек. Среди маленьких квадратов нет двух незаконченных с одной и той же недостающей спичкой. Значит, одной спичкой можно добавить самое большее один квадрат."],["Ставим две спички","В верхнем из двух квадратов со стороной 2 спички достраиваем крестик от верхней и левой сторон до его центра. Выйдут три новых маленьких квадрата. Теперь их вместе с прежними ровно 11."]],""],[816,147,"Есть 6 карточек с цифрами 1, 2, 3, 4, 5 и 6. Используя их, можно составить два трехзначных числа, например, 645 и 321. Вася составил эти числа так, что их разность оказалась самой маленькой из всех возможных. Эта разность равна",{"0":[33.7,113.5,31.4,26.3],"1":[181.0,113.5,31.4,26.3],"2":[350.2,113.5,32.6,26.3],"3":[519.4,113.5,32.6,26.3],"4":[688.5,113.5,31.4,26.3]},"D","Ближайшие числа",[["Сравниваем сотни","У большего числа цифра сотен выше хотя бы на 1. Разницу сотен не меньше 100 могут сильнее всего сблизить хвосты 12 у большего и 65 у меньшего."],["Строим подходящую пару","Цифры 1, 2, 6 и 5 уже заняты, поэтому берём для сотен соседние 3 и 4. Получаем 412 − 365 = 47. Меньше нельзя, ведь хвосты уже уменьшили разность на максимально возможные 65 − 12 = 53."]],""],[816,234,"Кубик лежит на листе бумаги в клетку, как показано на рисунке. Кубик перекатывают через ребра в направлениях, указанных стрелочками. Сколько точек окажется сверху, когда кубик попадет на клетку, отмеченную звездочкой?",{"0":[33.8,203.2,31.4,26.3],"1":[180.9,203.2,31.4,26.3],"2":[350.1,203.2,32.6,26.3],"3":[467.2,203.2,32.7,26.3],"4":[584.7,203.2,31.4,26.3]},"B","Кубик по стрелкам",[["Определяем грани","Сверху 3, спереди 1, справа 2. На противоположных гранях обычного игрального кубика в сумме 7, значит слева 5, сзади 6, снизу 4."],["Следим за первыми поворотами","После переката вправо сверху 5, справа 3, а спереди по-прежнему 1. При перекате от себя передняя грань 1 оказывается сверху, а нижняя грань 2 — спереди."],["Доходим до звезды","Ещё один перекат вправо оставляет 2 спереди. Последний перекат от себя поднимает эту грань наверх. Сверху две точки."]],""],[816,249,"Какие два из нарисованных восьмиугольников раскрашены одинаково?",{"0":[33.7,216.9,31.4,26.3],"1":[181.0,216.9,31.4,26.3],"2":[350.1,216.9,32.6,26.3],"3":[519.4,216.9,32.6,26.3],"4":[656.5,216.9,31.4,26.3]},"D","Узор на восьмиугольнике",[["Выбираем ориентир","У восьмиугольника 4 есть большой тёмный треугольник у верхней стороны и маленький тёмный треугольник у нижнего правого угла."],["Поворачиваем рисунок","При повороте по часовой стрелке на четверть оборота большой треугольник окажется справа, маленький — у нижнего левого угла. Если сравнить и остальные закрашенные части, узор совпадёт с восьмиугольником 6."]],""],[816,122,"Про число a известно, что его последняя цифра равна 1, и что оно делится ровно на десять различных чисел (включая 1 и a). На сколько различных чисел делится число 10a?",{},"C","Делители числа",[["Проверяем последнюю цифру","Число оканчивается на 1, поэтому среди его делителей нет чисел, кратных 2 или 5. Множитель 10 добавляет ровно одну двойку и одну пятёрку."],["Собираем все варианты","Любой делитель нового числа получается из делителя старого, к которому можно приписать множитель 1, 2, 5 или 10. Все варианты различны. Всего 10 × 4 = 40 делителей."]],""],[816,196,"Три черепахи – Анди, Банди и Канди – соревнуются в беге на дистанцию 30 м. Они стартовали одновременно. Когда Анди финишировала, Банди оставалось до финиша 10 м, а Канди была на 4 м впереди Банди. На каком расстоянии до финиша будет Банди, когда Канди закончит дистанцию, если каждая черепаха движется с постоянной скоростью?",{"0":[33.8,162.2,31.4,26.3],"1":[181.0,162.2,31.4,26.3],"2":[350.2,162.2,32.7,26.3],"3":[519.4,162.2,32.7,26.3],"4":[688.7,162.2,31.4,26.3]},"D","Черепаший забег",[["Сравниваем пути","Когда Анди финиширует, Банди пробежала 30 − 10 = 20 м, а Канди — 20 + 4 = 24 м."],["Считаем оставшуюся часть","За равное время Банди пробегает 5 м, а Канди — 6 м, потому что 20 и 24 делятся на 4. Канди осталось как раз 6 м. Банди за это время пробежит ещё 5 м, и ей останется 10 − 5 = 5 м."]],""]]],[2002,"3–4 классы",[[816,184,"Какой из следующих квадратиков вырезан из картинки, изображенной справа?",{"0":[45.2,125.1,28.2,23.6],"1":[145.0,125.1,28.2,23.6],"2":[245.0,125.1,29.3,23.6],"3":[344.9,125.1,29.4,23.6],"4":[444.9,125.1,28.2,23.6]},"B","Фрагмент рисунка",[["Ищем недостающий квадрат","Пустое место находится справа в среднем ряду. У фигурки одна линия приходит через левый край, другая — из клетки сверху."],["Совмещаем линии","В B диагональ подходит к нижнему левому углу, а короткая линия подходит к следу в верхней клетке. Оба контура продолжаются без разрыва."]],""],[816,70,"Число 2 + 2 − 2 + 2 − 2 + 2 − 2 + 2 − 2 + 2 равно",{"0":[33.8,37.7,28.2,23.6],"1":[195.0,37.7,28.2,23.6],"2":[361.6,37.7,29.3,23.6],"3":[528.2,37.7,29.3,23.6],"4":[694.6,37.7,28.2,23.6]},"C","Двойки со знаками",[["Собираем пары","Каждые соседние «−2 + 2» дают ноль. После первых двух двоек таких пар четыре."],["Складываем остаток","Остаётся 2 + 2 = 4."]],""],[816,141,"На одной чашке весов лежат 6 апельсинов, а на другой – 2 дыни. Если добавить одну такую же дыню к апельсинам, то весы будут уравновешены. Значит, дыня весит столько же, сколько",{"0":[33.8,86.4,28.2,23.6],"1":[261.8,86.4,28.2,23.6],"2":[511.5,86.4,29.3,23.6],"3":[33.8,109.5,29.3,23.6],"4":[261.8,109.5,28.2,23.6]},"E","Дыня на весах",[["Уравновешиваем чашки","Шесть апельсинов и одна дыня весят столько же, сколько две дыни."],["Убираем одинаковый груз","Уберём по дыне с обеих чашек. Весы останутся в равновесии. Одна дыня весит как шесть апельсинов."]],""],[816,94,"Джозеф живет на улице, дома на которой имеют номера с 1 по 24. Сколько раз при написании этих номеров используется цифра 2?",{"0":[33.8,62.0,28.2,23.6],"1":[195.1,62.0,28.2,23.6],"2":[361.6,62.0,29.3,23.6],"3":[528.3,62.0,29.3,23.6],"4":[694.6,62.0,28.2,23.6]},"C","Цифра на номерах домов",[["Считаем единицы","Двойка стоит в разряде единиц в номерах 2, 12 и 22. Это три двойки."],["Считаем десятки","Двойка стоит в разряде десятков в номерах от 20 до 24, ещё пять раз. В номере 22 учитываем обе двойки. Всего 3 + 5 = 8."]],""],[816,204,"Таня видит из окна флаг, который развевается на ветру. Флаг имеет форму прямоугольника. Какую из картинок Таня не могла увидеть?",{"0":[67.3,177.2,28.2,23.6],"1":[200.6,177.2,28.2,23.6],"2":[350.4,177.2,29.3,23.6],"3":[467.1,177.2,29.4,23.6],"4":[617.0,177.2,28.2,23.6]},"B","Флаг на флагштоке",[["Ищем неподвижную сторону","Левый край флага закреплён на древке. Ветер может согнуть свободную часть, но не меняет длину края, закреплённого на древке."],["Сравниваем рисунки","У B ткань закрывает более короткий отрезок древка, чем у исходного флага. Такой рисунок Таня видеть не могла."]],""],[816,93,"Прибавив 17 к самому маленькому двузначному числу и разделив эту сумму на самое большое однозначное число, мы получим",{"0":[33.8,62.0,28.2,23.6],"1":[180.9,62.0,28.2,23.6],"2":[350.2,62.0,29.3,23.6],"3":[519.4,62.0,29.3,23.6],"4":[688.6,62.0,28.2,23.6]},"A","Двузначное и однозначное",[["Выбираем числа","Наименьшее двузначное число — 10, наибольшее однозначное — 9."],["Выполняем действия","Сначала 10 + 17 = 27, затем 27 ÷ 9 = 3."]],""],[816,128,"В каком из этих ожерелий ровно две трети камушков темные?",{"0":[78.5,96.0,28.2,23.6],"1":[195.1,96.0,28.2,23.6],"2":[361.6,96.0,29.3,23.6],"3":[511.5,96.0,29.4,23.6],"4":[661.5,96.0,28.2,23.6]},"D","Две трети ожерелья",[["Проверяем долю","Две трети означают две тёмные бусинки на каждую светлую. Ищем ожерелье, в котором тёмных ровно вдвое больше, чем светлых."],["Считаем бусинки","У D четыре тёмных камушка и два светлых. Это 4 из 6, или две трети."]],""],[817,141,"Если в этом году на следующий день после своего дня рождения я скажу: «Послезавтра будет среда», то это будет правильно. В какой день недели у меня день рождения в этом году?",{"0":[33.8,86.4,28.2,23.6],"1":[265.6,86.4,28.2,23.6],"2":[604.0,86.4,29.3,23.6],"3":[33.8,109.5,29.3,23.6],"4":[265.6,109.5,28.2,23.6]},"E","День рождения",[["Отсчитываем от среды","Если послезавтра среда, то завтра вторник, а сегодня понедельник."],["Идём ещё на день назад","Эти слова произнесены на следующий день после дня рождения. Значит, день рождения пришёлся на воскресенье."]],""],[817,169,"В Месопотамии за 2500 лет до нашей эры единицы обозначали значком ∆, ▼. десятки – значком ◄, а число шестьдесят – значком Как записывалось число 124?",{"0":[33.9,105.9,28.2,23.6],"1":[298.1,105.9,28.2,23.6],"2":[561.0,105.9,29.3,23.6],"3":[33.9,136.8,29.3,23.6],"4":[298.1,136.8,28.2,23.6]},"E","Месопотамское число",[["Выделяем шестидесятки","В числе 124 содержатся два раза по 60 и остаётся 4. Поэтому нужны два знака ▼."],["Записываем остаток","Четыре единицы — это ∆∆∆∆. Вместе получается ▼▼∆∆∆∆."]],""],[817,140,"В 9-00 большой старый будильник поставили правильно. Но он отстает на 1 минуту в час. Тогда",{"0":[33.9,62.0,28.2,23.6],"1":[434.9,62.0,28.2,23.6],"2":[33.9,85.2,29.3,23.6],"3":[435.0,85.2,29.3,23.6],"4":[33.9,108.3,28.2,23.6]},"A","Отстающий будильник",[["Ждём один час","С 9:00 до 10:00 пройдёт ровно один час. За это время будильник отстанет на одну минуту."],["Читаем показание","Когда на точных часах будет 10:00, будильник покажет 9:59."]],""],[817,94,"Число x таково, что прибавить к нему 2 – то же самое, что умножить его на 3. Тогда умножить его на 6 – это то же самое, что прибавить к нему",{"0":[33.8,62.0,28.2,23.6],"1":[195.1,62.0,28.2,23.6],"2":[328.4,62.0,29.3,23.6],"3":[511.5,62.0,29.3,23.6],"4":[678.1,62.0,28.2,23.6]},"C","Число и его тройка",[["Сравниваем две записи","Утроенное число — это три одинаковых слагаемых. Из условия следует, что одно такое слагаемое и ещё 2 дают три слагаемых."],["Находим число","После вычитания одного слагаемого остаются два, которые вместе равны 2. Само число равно 1. Умножить его на 6 значит получить 6, то есть прибавить к нему 5."]],""],[817,213,"У каждого из четырех ребят живет какое-то одно любимое животное: кошка, собака, рыбка или канарейка (у всех разные). У Манон животное – с пушистой шерстью, у Фабиана – четвероногое, у Николя – пернатое. И Жюли, и Манон не любят кошек. Какое из следующих утверждений неверно?",{"0":[33.8,135.2,28.2,23.6],"1":[378.3,135.2,28.2,23.6],"2":[33.8,158.3,29.3,23.6],"3":[378.2,158.3,29.3,23.6],"4":[33.8,181.4,28.2,23.6]},"A","Четыре питомца",[["Находим хозяев","У Николя единственная птица — канарейка. У Манон пушистый питомец, но кошек она не любит. Значит, у неё собака."],["Распределяем остальных","У Фабиана четвероногое животное, поэтому у него кошка. Жюли остаётся рыбка. Утверждение «у Фабиана собака» неверно."]],""],[817,287,"На рисунке мы видим разломанные циферблаты часов. Часовых дел мастер подсчитал суммы чисел на всех обломках. Оказалось, что для одного из циферблатов эти суммы – четыре последовательных числа. Какой это циферблат?",{"0":[95.2,255.4,28.2,23.6],"1":[245.1,255.4,28.2,23.6],"2":[395.1,255.4,29.3,23.6],"3":[544.8,255.4,29.4,23.6],"4":[694.8,255.4,28.2,23.6]},"C","Разбитый циферблат",[["Узнаём нужные суммы","Сумма всех чисел на циферблате равна 78. Четыре последовательных числа с такой суммой — 18, 19, 20 и 21."],["Проверяем рисунок C","На обломках получаем 12 + 1 + 2 + 3 = 18, 9 + 10 = 19, 11 + 4 + 5 = 20 и 8 + 7 + 6 = 21."]],""],[816,167,"ABCD – квадрат со стороной 10 см, а AMTD – A M B прямоугольник. Его короткая сторона равна 3 см. На сколько периметр квадрата больше, чем периметр прямоугольника AMTD?",{"0":[33.7,110.8,28.1,23.6],"1":[181.0,110.8,28.2,23.6],"2":[350.2,110.8,29.3,23.6],"3":[33.8,133.9,29.3,23.6],"4":[181.0,133.9,28.2,23.6]},"A","Периметры фигур",[["Находим стороны","У квадрата четыре стороны по 10 см. У прямоугольника две стороны по 10 см и две по 3 см."],["Сравниваем периметры","Две стороны по 10 см есть в каждой фигуре. Две другие у квадрата на 10 − 3 = 7 см длиннее. Разность периметров равна 2 × 7 = 14 см."]],""],[816,94,"В букете 11 цветов, причем 5 из них – красные, а 6 – розы. Какое наибольшее число белых гвоздик может быть в букете?",{"0":[33.8,62.0,28.2,23.6],"1":[181.0,62.0,28.2,23.6],"2":[350.2,62.0,29.3,23.6],"3":[519.4,62.0,29.3,23.6],"4":[688.6,62.0,28.2,23.6]},"B","Белые гвоздики",[["Используем число роз","Из 11 цветов 6 — розы. Значит, гвоздик может быть не больше 11 − 6 = 5."],["Составляем букет","Пусть все 5 красных цветов будут розами, а шестая роза и 5 гвоздик — белыми. Значит, пять белых гвоздик возможны."]],""],[816,165,"Маша вышла из дома в 7 час 55 мин и пришла в школу в 8 час 32 мин. Ее подруга Даша пришла в школу только в 8 час 45 мин, хотя она живет ближе к школе и ей требуется на дорогу на 12 минут меньше, чем Маше. Когда Даша вышла из дома?",{"0":[33.7,110.8,28.2,23.6],"1":[265.5,110.8,28.2,23.6],"2":[519.3,110.8,29.3,23.6],"3":[33.7,133.9,29.3,23.6],"4":[265.5,133.9,28.2,23.6]},"B","Дорога в школу",[["Считаем время Маши","От 7:55 до 8:00 прошло 5 минут, а до 8:32 — ещё 32 минуты. Маша шла 37 минут."],["Отсчитываем время Даши","Даша шла на 12 минут меньше: 37 − 12 = 25 минут. От 8:45 отнимем 25 минут и получим 8:20."]],""],[816,167,"Сначала Роберт построил из всех своих одинаковых кубиков тоннель. Потом он разобрал тоннель и построил пирамиду. Сколько лишних кубиков осталось у Роберта?",{"0":[33.8,135.2,28.1,23.6],"1":[195.1,135.2,28.2,23.6],"2":[345.0,135.2,29.3,23.6],"3":[511.5,135.2,29.3,23.6],"4":[661.5,135.2,28.2,23.6]},"D","Тоннель и пирамида",[["Считаем кубики тоннеля","В каждом поперечном слое тоннеля квадрат 5 × 5 без серединки 3 × 3, то есть 25 − 9 = 16 кубиков. За первым слоем ещё три таких, всего 64 кубика."],["Считаем кубики пирамиды","Нижний слой даёт 5 × 5 = 25 кубиков. Над ним два слоя по 3 × 3, в верхней башенке три кубика. На пирамиду ушло 25 + 18 + 3 = 46 кубиков."],["Находим остаток","Роберт использовал 46 из 64 кубиков. Осталось 18."]],""],[816,118,"На доске в строчку написаны двадцать пятерок. Поставив между некоторыми из них знак «+», Вася обнаружил, что сумма равна 1000. Сколько плюсов поставил Вася?",{"0":[33.7,86.4,28.2,23.6],"1":[195.0,86.4,28.2,23.6],"2":[344.9,86.4,29.3,23.6],"3":[511.4,86.4,29.3,23.6],"4":[661.5,86.4,28.2,23.6]},"C","Двадцать пятёрок",[["Находим большие слагаемые","Число 5555 уже больше 1000. Если брать только 5 и 55, наибольшая сумма — десять чисел 55, то есть 550. Значит, есть число 555, но только одно, потому что два уже дают 1110."],["Составляем оставшуюся сумму","После 555 осталось 17 цифр и нужно набрать 445. Из отдельных пятёрок набирается 85. Каждое объединение двух пятёрок в 55 добавляет 45, поэтому нужны (445 − 85) ÷ 45 = 8 таких пар и одна отдельная пятёрка."],["Считаем знаки","Всего одно 555, восемь 55 и одна 5. Между десятью слагаемыми девять плюсов."]],""],[816,166,"В зоопарке Санкт-Петербурга жили 3 кенгуру: Лиззи, Дженни и Бином. А потом родился крошка Ру. Сейчас все это семейство съедает 28 кг морковки в неделю, причем Ру съедает ровно вдвое меньше, чем любой из старших кенгуру. Сколько морковки в неделю съедало это семейство до рождения Ру?",{"0":[33.8,135.2,28.1,23.6],"1":[195.1,135.2,28.2,23.6],"2":[345.0,135.2,29.3,23.6],"3":[511.5,135.2,29.3,23.6],"4":[661.5,135.2,28.2,23.6]},"D","Морковка на семью",[["Считаем порции","Возьмём за одну порцию недельный запас морковки Ру. Каждый взрослый съедает две такие порции, поэтому вместе они съедают 1 + 2 + 2 + 2 = 7 порций."],["Узнаём долю взрослых","Одна порция равна 28 ÷ 7 = 4 кг. До рождения Ру взрослые съедали шесть порций, то есть 24 кг в неделю."]],""],[816,200,"Лиса Алиса и кот Базилио пришли в харчевню «Трех пескарей», заказали обед и дали хозяину 10 золотых. Тот в качестве сдачи вернул им столько денег, сколько стоил обед. Лиса заметила, что хозяин дал им на 2 золотых меньше, чем нужно. Сколько денег он должен был вернуть им на самом деле?",{"0":[33.9,143.2,28.2,23.6],"1":[195.2,143.2,28.2,23.6],"2":[345.0,143.2,29.3,23.6],"3":[511.6,143.2,29.3,23.6],"4":[33.8,167.6,28.2,23.6]},"C","Сдача за обед",[["Уравниваем доли","Хозяин вернул столько, сколько стоил обед. Правильная сдача была бы на 2 золотых больше цены обеда."],["Делим деньги","Десять золотых — это цена обеда, ещё одна такая цена и 2 золотых. Поэтому обед стоил (10 − 2) ÷ 2 = 4 золотых, а сдача должна была быть 10 − 4 = 6 золотых."]],""],[816,167,"Трое ребят разделили между собой карточки с цифрами. Алексу достались цифры 7, 2 и 4, Марте – 6, 5 и 1, а Фреду – 8, 3 и 9. Каждый из них старается получить разные числа, используя свои карточки и знаки четырех арифметических действий. Кто из них не может получить число 20?",{"0":[33.9,135.2,28.2,23.6],"1":[161.8,135.2,28.2,23.6],"2":[295.0,135.2,29.3,23.6],"3":[418.4,135.2,29.3,23.6],"4":[628.2,135.2,28.2,23.6]},"B","Карточки и число 20",[["Находим два решения","Алекс получает 20 так: (7 − 2) × 4. Фред получает 20 так: 8 + 3 + 9."],["Проверяем цифры Марты","Со сложением и вычитанием число не превосходит 12. Если в последнем действии к произведению или частному прибавить оставшуюся цифру или вычесть её, получаются числа до 11 либо 29 и 31. Для умножения в последнем действии проверь три пары: из 1 и 6 нельзя получить 4, из 1 и 5 — 10/3, а из 5 и 6 — 20."],["Завершаем проверку","При делении на целую цифру 20 не получается: делитель 5 или 6 потребовал бы больше 30 в числителе, а деление на 1 оставляет результат действий с 5 и 6. Деление на 1/5 или 1/6 даёт 30; остальные результаты пары слишком велики в знаменателе. Даже склейка цифр в 15, 16, 51, 56, 61 или 65 не даёт 20 действием с оставшейся цифрой. Значит, Марта не может получить 20."]],""],[816,167,"В слове КЕНГУРУ каждая буква обозначает какую-то цифру (разные буквы обозначают разные цифры, а одинаковые буквы – одинаковые цифры). Какое самое большое количество нечетных цифр может оказаться в числе КЕНГУРУ+КЕНГУРУ?",{"0":[33.7,135.2,28.2,23.6],"1":[161.6,135.2,28.2,23.6],"2":[294.9,135.2,29.3,23.6],"3":[444.9,135.2,29.3,23.6],"4":[628.1,135.2,28.2,23.6]},"D","Двойное «Кенгуру»",[["Следим за переносом","При сложении одинаковых цифр их сумма чётная. Чтобы в разряде вышла нечётная цифра, нужно прибавить единицу, перенесённую из соседнего разряда справа. Перенос бывает, когда удваивается цифра от 5 до 9."],["Ограничиваем число нечётных цифр","Последняя цифра суммы всегда чётная. Если бы нечётных цифр было семь, понадобилась бы единица в восьмом разряде и перенос из каждого из семи разрядов. Тогда все шесть разных букв означали бы цифры от 5 до 9, а таких цифр только пять."],["Проверяем пример","Возьмём 1 567 898. Цифра 8 стоит на обоих местах буквы У, остальные буквы различны. Его двойное значение 3 135 796 содержит шесть нечётных цифр."]],""],[816,191,"Ваня играет в компьютерную игру. Сначала перед ним на экране 5 красных и 7 синих шариков. За один ход разрешается заменить какие-то три шарика одного цвета на два шарика другого цвета. Ваня хочет создать следующие картинки: 1 синий и 1 красный шарик, либо 9 красных и 1 синий, либо 9 синих и 1 красный, либо 2 синих. Сколько из этих картинок можно получить в такой игре?",{"0":[33.8,159.6,28.2,23.6],"1":[161.6,159.6,28.2,23.6],"2":[294.9,159.6,29.3,23.6],"3":[444.9,159.6,29.3,23.6],"4":[628.1,159.6,28.2,23.6]},"C","Красные и синие шарики",[["Смотрим на разность","В начале красных на 2 меньше, чем синих. Один ход меняет разность «красные минус синие» на 5 или на −5. Получить разности 0 и −8 нельзя, так как они отличаются от −2 не на целое число пятёрок."],["Получаем девять красных","Дважды заменим по три синих двумя красными. Из 5 красных и 7 синих получим 9 красных и 1 синий."],["Получаем два синих","Заменим три синих двумя красными, а потом три красных двумя синими. За эти два хода исчезает по одному шарику каждого цвета. Повторим пять раз: останется 0 красных и 2 синих. Подходят две картинки."]],""],[816,166,"В автомобильных гонках участвовали три машины. Они стартовали в таком порядке: Я, Ф, К, то есть сначала «Ягуар», потом «Феррари», потом «Кенгуру». На дистанции «Ягуар» обогнали 3 раза, «Феррари» – 5 раз, а «Кенгуру» – 8 раз. В каком порядке машины пришли к финишу?",{"0":[33.7,110.8,28.2,23.6],"1":[211.7,110.8,28.2,23.6],"2":[411.5,110.8,29.3,23.6],"3":[594.8,110.8,29.3,23.6],"4":[33.7,133.9,28.2,23.6]},"D","Порядок на финише",[["Следим за «Кенгуру»","«Кенгуру» стартовал последним. Чтобы одна из машин его обогнала, он должен сначала оказаться впереди неё. Значит, за восемь обгонов «Кенгуру» пришлось самому совершить хотя бы восемь обгонов."],["Используем все обгоны","«Ягуар» обогнали 3 раза, а «Феррари» — 5 раз. Все эти восемь обгонов совершил «Кенгуру», и после них он снова последний. Первые две машины не обгоняли друг друга. Порядок на финише — Я, Ф, К."]],""],[816,172,"Все числа от 1 до 7 вписывают по одному в кружки на рисунке так, чтобы суммы чисел в каждой тройке кружков, расположенных на прямой линии, были одинаковыми. Сколько существует способов заполнить центральный кружок?",{"0":[33.8,135.2,28.2,23.6],"1":[128.5,135.2,28.2,23.6],"2":[228.3,135.2,29.3,23.6],"3":[344.9,135.2,29.3,23.6],"4":[478.2,135.2,28.2,23.6]},"D","Число в центре",[["Убираем центр из сумм","Число из центра входит во все три линии, поэтому на противоположных концах линий должны получиться три равные суммы. Сумма чисел от 1 до 7 равна 28. Если вычесть число из центра, остаток должен делиться на 3."],["Проверяем три возможности","В центре возможны 1, 4 и 7. Для 1 пары 2 + 7, 3 + 6 и 4 + 5 дают по 9. Для 4 пары 1 + 7, 2 + 6 и 3 + 5 дают по 8. Для 7 пары 1 + 6, 2 + 5 и 3 + 4 дают по 7. Все три числа подходят."]],""],[816,190,"Алиса и Белый Кролик в полдень вместе вышли из домика Кролика и пошли на прием к Герцогине. Пройдя полпути, Кролик вспомнил, что забыл перчатки и веер, и вернулся за ними домой. В результате Алиса пришла к Герцогине за 5 минут до начала приема, а Кролик опоздал на 10 минут. Алиса и Кролик шли с постоянными и одинаковыми скоростями. На какое время был назначен прием у Герцогини?",{"0":[33.6,159.6,28.1,23.6],"1":[178.3,159.6,28.2,23.6],"2":[344.8,159.6,29.3,23.6],"3":[511.3,159.6,29.3,23.6],"4":[661.3,159.6,28.2,23.6]},"C","Алиса и Белый Кролик",[["Считаем лишний путь","Кролик шёл от середины домой и снова от дома до середины. Две такие половины составляют один полный путь от дома до Герцогини."],["Находим время дороги","Кролик пришёл на 10 минут позже начала, а Алиса — за 5 минут до начала. Разница между их приходами 15 минут. Столько времени занимает один полный путь."],["Находим время приёма","Алиса вышла в полдень и пришла в 12:15. Приём начался через 5 минут, в 12:20."]],""]]],[2003,"3–4 классы",[[839,133,"Софи рисует цветных кенгуру: сначала голубого, потом красного, потом черного, потом желтого, снова голубого, красного, черного, желтого и так далее. Какого цвета будет семнадцатый кенгуру?",{"0":[38.6,101.5,31.4,23.5],"1":[201.7,101.5,31.4,23.5],"2":[348.2,101.5,32.7,23.5],"3":[494.6,95.1,32.7,32.3],"4":[641.2,101.5,31.4,23.5]},"A","Цвета кенгуру",[["Замечаем повтор","Голубой, красный, чёрный и жёлтый образуют группу из четырёх цветов. Дальше порядок повторяется."],["Находим семнадцатого","Первые четыре группы дают 4 × 4 = 16 кенгуру. Семнадцатый начинает новую группу, поэтому он голубой."]],""],[839,86,"Число 0 + 1 + 2 + 3 + 4 – 3 – 2 – 1 – 0 равно",{"0":[38.6,54.5,31.4,23.5],"1":[201.8,54.5,31.4,23.5],"2":[348.2,54.5,32.7,23.5],"3":[494.6,48.0,32.6,32.3],"4":[641.3,54.5,31.4,23.5]},"C","Сумма и разность",[["Находим пары","Числа 0, 1, 2 и 3 сначала прибавляют, а потом вычитают по одному разу."],["Убираем пары","Каждая такая пара даёт ноль. Остаётся только 4."]],""],[839,200,"На какой картинке сердечки составляют ровно три четверти от общего числа фигурок?",{"0":[118.5,169.5,31.4,23.5],"1":[251.7,169.5,31.4,23.5],"2":[385.8,169.5,32.7,23.5],"3":[521.3,163.1,32.7,32.3],"4":[651.2,169.5,31.4,23.5]},"D","Три четверти сердечек",[["Проверяем нужную долю","Три четверти означают, что на каждые четыре фигурки должно приходиться три сердечка."],["Считаем на рисунке D","В D три ряда по три сердечка. Под ними ещё три фигурки других видов. Получается 9 сердечек из 12 фигурок, то есть три четверти."]],""],[839,113,"Если бы выходными днями в сентябре были все числа, в которых есть четные цифры, то в школу в сентябре пришлось бы ходить",{"0":[38.6,81.5,31.4,23.5],"1":[201.7,81.5,31.4,23.5],"2":[348.2,81.5,32.7,23.5],"3":[494.6,81.5,32.7,23.5],"4":[641.2,81.5,31.4,23.5]},"B","Нечётные цифры в датах",[["Выбираем рабочие дни","Чтобы день был учебным, в его номере должны быть только нечётные цифры. Подходят 1, 3, 5, 7 и 9."],["Проверяем двузначные даты","Также подходят 11, 13, 15, 17 и 19. В каждом числе от 20 до 29 есть чётная цифра 2, а в 30 — чётная цифра 0. Итого 5 + 5 = 10 учебных дней."]],""],[839,147,"Васиного отца зовут Иван Николаевич, а дедушку — Семен Петрович. Каково отчество Васиной мамы?",{"0":[38.6,81.5,31.4,23.5],"1":[280.1,81.5,31.4,23.5],"2":[512.6,81.5,32.7,23.5],"3":[38.6,115.5,32.7,23.5],"4":[280.1,115.5,31.4,23.5]},"C","Имя дедушки",[["Смотрим на отчество папы","Иван Николаевич — сын Николая. Значит, дедушку по папиной линии зовут Николай."],["Находим отчество мамы","Семён Петрович — дедушка с маминой стороны. Мама — дочь Семёна, поэтому её отчество Семёновна."]],""],[839,156,"Лист бумаги сложили и разрезали, как показано на рисунке. Сколько кусочков получилось?",{"0":[38.6,90.6,31.4,23.5],"1":[201.7,90.6,31.4,23.5],"2":[348.2,90.6,32.7,23.5],"3":[38.6,118.1,32.7,32.3],"4":[201.7,124.6,31.4,23.5]},"B","Разрез сложенного листа",[["Представляем разворот","Когда раскрываем сгиб, на котором заканчивается пунктир, две половины разреза соединяются в одну линию от края до края."],["Раскрываем второй сгиб","Другой сгиб даёт ещё одну такую линию. После полного разворота две линии разреза отделяют два крайних кусочка от середины. Всего три кусочка."]],""],[839,79,"Самое маленькое целое число, которое делится на 2, 3 и 4, равно",{"0":[38.6,47.5,31.4,23.5],"1":[201.7,47.5,31.4,23.5],"2":[348.2,47.5,32.7,23.5],"3":[494.6,41.0,32.6,32.3],"4":[641.2,47.5,31.4,23.5]},"D","Общее кратное",[["Проверяем числа","Ищем наименьшее положительное число. Если оно делится на 4, то делится и на 2. Первые положительные числа, кратные 4, — 4, 8 и 12."],["Проверяем делимость на 3","Ни 4, ни 8 не делятся на 3. Число 12 делится на 2, 3 и 4, значит, оно подходит первым."]],""],[824,159,"Пятачок посадил 8 желудей. Из всех желудей, кроме двух, выросли дубы. На всех дубах, кроме двух, растут желуди. Желуди со всех плодоносящих дубов, кроме одного, — невкусные. Значит, число дубов с невкусными желудями равно",{"0":[45.1,128.5,31.4,23.5],"1":[208.3,128.5,31.4,23.5],"2":[354.7,128.5,32.7,23.5],"3":[501.2,122.0,32.6,32.3],"4":[647.8,128.5,31.4,23.5]},"D","Жёлуди и дубы",[["Считаем деревья","Из 8 желудей два не проросли. Выросло 8 − 2 = 6 дубов."],["Считаем дубы с невкусными желудями","На двух дубах желудей нет, поэтому плодоносят 6 − 2 = 4 дерева. На одном из них жёлуди вкусные, а на остальных 4 − 1 = 3 — невкусные."]],""],[824,103,"В прямоугольнике 4×7, нарисованном на клетчатой бумаге, провели диагональ. Сколько клеточек она разрезала?",{"0":[45.1,74.7,31.4,23.5],"1":[208.3,74.7,31.4,23.5],"2":[354.7,74.7,32.7,23.5],"3":[501.2,68.2,32.6,32.3],"4":[647.8,74.7,31.4,23.5]},"C","Диагональ по клеткам",[["Считаем внутренние линии","Диагональ проходит через 6 внутренних вертикальных линий и 3 горизонтальные. На горизонтальных линиях она прошла по ширине 1¾, 3½ и 5¼ клетки, поэтому внутри прямоугольника нигде не попадает в узел сетки."],["Считаем разрезанные клетки","Диагональ начинает путь в одной клетке. После каждого из 6 + 3 = 9 пересечений она попадает в новую. Всего разрезано 1 + 9 = 10 клеток."]],""],[824,133,"Выписав 6 четных чисел, идущих подряд, Вася обнаружил, что самое большое из них вдвое больше самого маленького. Чему равно самое маленькое число?",{"0":[45.1,101.5,31.4,23.5],"1":[208.3,101.5,31.4,23.5],"2":[354.7,101.5,32.7,23.5],"3":[501.2,95.0,32.6,32.3],"4":[647.8,101.5,31.4,23.5]},"D","Шесть чётных чисел",[["Находим разность","Между первым и шестым числами пять переходов. На каждом число увеличивается на 2. Значит, шестое больше первого на 5 × 2 = 10."],["Сравниваем с удвоением","Шестое число вдвое больше первого. Разность между ними равна самому первому числу, то есть 10."]],""],[824,241,"Как-то в воскресенье, в 9 часов 30 минут утра, Аня присела поиграть в компьютерную игру, но заигралась, и мама прогнала ее от компьютера только днем, в 3 часа 15 минут. В следующее воскресенье ее брат Мартин ухитрился просидеть за компьютером еще на 1 час 50 минут дольше. Сколько времени провел у компьютера Мартин?",{"0":[45.1,182.5,31.4,23.5],"1":[286.7,182.5,31.4,23.5],"2":[519.1,182.5,32.7,23.5],"3":[45.1,203.1,32.7,32.3],"4":[286.7,209.6,31.4,23.5]},"C","Игра за компьютером",[["Считаем время Ани","С 9:30 до 15:30 прошло бы 6 часов. Аня закончила в 15:15, на 15 минут раньше. Она играла 5 часов 45 минут."],["Прибавляем время Мартина","5 часов 45 минут + 1 час 50 минут — это 6 часов 95 минут, или 7 часов 35 минут."]],""],[824,138,"Сколько треугольников на рисунке имеют такую же площадь, как и целая клетка?",{"0":[45.1,74.5,31.4,23.5],"1":[208.3,74.5,31.4,23.5],"2":[354.7,74.5,32.7,23.5],"3":[45.1,95.1,32.6,32.3],"4":[208.3,101.5,31.4,23.5]},"C","Треугольники на сетке",[["Узнаём нужный размер","Две половинки клетки дают площадь 1. Такой треугольник получается, если его основание занимает две клетки, а высота — одну."],["Считаем внутри ромба","Слева есть ромб. Его горизонтальная диагональ делит его на два подходящих треугольника. Вертикальная диагональ тоже делит на два. Это четыре треугольника."],["Считаем справа","Ещё два треугольника имеют длинные основания сверху и снизу рисунка, а один — вдоль правой границы. Всего 4 + 3 = 7."]],""],[824,132,"На заседании присутствуют 29 академиков, 12 из них имеют бороду, а 18 — усы. У трех академиков нет ни бороды, ни усов. Сколько академиков имеют и бороду, и усы?",{"0":[45.1,101.5,31.4,23.5],"1":[208.3,101.5,31.4,23.5],"2":[354.7,101.5,32.7,23.5],"3":[501.2,95.1,32.7,32.3],"4":[647.8,95.1,31.3,32.3]},"A","Борода и усы",[["Выделяем нужных людей","Из 29 академиков у трёх нет ни усов, ни бороды. Значит, 26 имеют хотя бы одно из двух."],["Замечаем двойной счёт","В сумме 12 + 18 = 30 каждый с усами и бородой посчитан дважды, а каждый с чем-то одним — один раз. Двойных подсчётов 30 − 26 = 4."]],""],[824,187,"Штрих-код образован 17 черными и белыми полосками (крайние полоски — черные). Черные полоски бывают двух типов: узкие и широкие. Число белых полосок на 3 больше, чем число широких черных. Чему равно число узких черных полосок?",{"0":[45.1,155.5,31.4,23.5],"1":[208.3,155.5,31.4,23.5],"2":[354.7,155.5,32.7,23.5],"3":[501.2,149.0,32.6,32.3],"4":[647.8,155.5,31.4,23.5]},"D","Полоски штрихкода",[["Считаем цвета","Чёрные и белые полоски чередуются. По краям стоят чёрные, поэтому их на одну больше. В 17 полосках есть 8 белых и 9 чёрных."],["Разделяем чёрные полоски","Широких чёрных на 3 меньше, чем белых: 8 − 3 = 5. Узких чёрных полосок 9 − 5 = 4."]],""],[845,149,"Кенгуру купил конфеты трех видов: большие, маленькие и средние. Каждая большая конфета стоит 4 монеты, средняя — 2 монеты и маленькая — 1 монету. За 10 конфет Кенгуру заплатил 16 монет. Сколько больших конфет он купил?",{"0":[45.1,117.7,31.4,23.5],"1":[208.3,117.7,31.4,23.5],"2":[354.7,117.7,32.7,23.5],"3":[501.2,111.2,32.6,32.3],"4":[647.8,117.7,31.4,23.5]},"E","Большие конфеты",[["Сравниваем с маленькими","Если бы все десять конфет были маленькими, они стоили бы 10 монет. За среднюю конфету нужно добавить 1 монету, за большую — 3. Всего доплатили 16 − 10 = 6 монет."],["Оставляем место средней конфете","Две большие конфеты израсходовали бы всю доплату. Но среди купленных есть все три вида, значит, нужно заплатить ещё и за среднюю. Большая конфета только одна. Остальные — три средние и шесть маленьких."]],""],[845,150,"Чему равна площадь буквы N, если площадь клетки равна 1?",{"0":[45.1,69.1,31.4,23.5],"1":[208.3,69.1,31.4,23.5],"2":[354.7,69.1,32.7,23.5],"3":[45.1,94.0,32.6,32.3],"4":[208.3,100.5,31.4,23.5]},"E","Площадь буквы N",[["Считаем боковые полосы","В каждой вертикальной полосе буквы 6 клеток. Две полосы дают 12."],["Измеряем наклонную полосу","В каждом горизонтальном ряду из клеток серая наклонная полоса имеет ширину в одну клетку. Срезанный с одной стороны кусочек дополняет такой же ряд с другой стороны до целой клетки. Наклонная часть занимает 6 клеток, а вся буква — 18."]],""],[845,125,"Сережа любит подсчитывать сумму цифр на табло электронных часов. Например, если часы показывают 21:17, он получает сумму 11. Какую наибольшую сумму он может получить?",{"0":[45.1,93.3,31.4,23.5],"1":[208.3,93.3,31.4,23.5],"2":[354.7,93.3,32.7,23.5],"3":[501.2,86.9,32.6,32.3],"4":[647.8,93.3,31.4,23.5]},"C","Цифры на часах",[["Выбираем минуты","Больше всего дают минуты 59: сумма цифр 5 + 9 = 14."],["Выбираем часы","Среди часов от 00 до 23 наибольшую сумму даёт 19: 1 + 9 = 10. В 19:59 получится 10 + 14 = 24."]],""],[845,100,"Сколько страниц в книжке, если для того, чтобы их пронумеровать, понадобилось всего 35 цифр?",{"0":[45.1,69.0,31.4,23.5],"1":[208.3,69.0,31.4,23.5],"2":[354.7,69.0,32.7,23.5],"3":[501.2,62.6,32.6,32.3],"4":[647.8,69.0,31.4,23.5]},"C","Номера страниц",[["Считаем первые страницы","На номера страниц с 1 по 9 ушло 9 цифр. Осталось 35 − 9 = 26 цифр."],["Считаем двузначные номера","Каждый следующий номер состоит из двух цифр. Таких номеров 26 ÷ 2 = 13. Всего в книге 9 + 13 = 22 страницы."]],""],[845,157,"Какое наибольшее число веревочек можно разрезать на этой сетке, чтобы она не распалась на куски? (Разрезать по узелкам сетки нельзя!)",{"0":[45.1,87.0,31.3,32.3],"1":[159.8,93.5,31.4,23.5],"2":[265.5,93.5,32.7,23.5],"3":[371.2,87.0,32.6,32.3],"4":[519.1,93.5,31.4,23.5]},"C","Верёвочки сетки",[["Считаем узелки и связи","В сетке 4 × 4 = 16 узелков и 12 горизонтальных плюс 12 вертикальных верёвочек. Чтобы соединить 16 узелков, нужно хотя бы 15 верёвочек: из отдельных узелков каждая добавленная верёвочка может соединить не больше двух групп в одну."],["Строим связную сетку","Сохраним 12 вертикальных верёвочек и 3 горизонтальные в верхнем ряду. Тогда каждый узел соединён с верхним рядом и вся сетка держится вместе. Можно разрезать 24 − 15 = 9 верёвочек."]],""],[845,145,"Во сколько раз увеличится трехзначное число, если написать его два раза подряд?",{"0":[45.1,56.2,31.4,23.5],"1":[180.9,56.2,31.4,23.5],"2":[307.8,56.2,32.7,23.5],"3":[455.8,49.7,32.6,32.3],"4":[603.7,56.2,31.4,23.5]},"E","Число два раза подряд",[["Сдвигаем разряды","Если приписать к трёхзначному числу три нуля, оно увеличится в 1000 раз. Так располагается первая копия в новом числе."],["Добавляем вторую копию","Три последних разряда занимают цифры второй копии. Значит, новое число — 1000 старых чисел плюс ещё одно, то есть в 1001 раз больше."]],""],[845,301,"Брусок собран из трех деталей. Каждая деталь состоит из четырех кубиков и окрашена в свой цвет. Как выглядит белая деталь?",{"0":[75.2,270.8,31.4,23.5],"1":[244.4,270.8,31.4,23.5],"2":[371.2,270.8,32.7,23.5],"3":[501.2,264.3,32.7,32.3],"4":[647.8,270.8,31.4,23.5]},"D","Белая деталь бруска",[["Считаем видимые кубики","Видны два белых кубика: верхний средний в заднем ряду и нижний справа в заднем ряду. Светло-серых и тёмно-серых кубиков видно по четыре, поэтому спрятанные белые кубики нужно искать сзади внизу."],["Собираем задний ряд","В заднем нижнем ряду белые все три кубика. Ещё один стоит на среднем. Получается деталь D."]],""],[824,194,"Маша старше Миши ровно на один месяц (дни их рождения приходятся на одно и то же число в двух соседних месяцах), а Даша старше Миши на столько же дней, на сколько Маша старше Даши. В каком месяце не могла родиться Даша?",{"0":[45.1,128.5,31.4,23.5],"1":[286.7,128.5,31.4,23.5],"2":[540.3,128.5,32.7,23.5],"3":[45.1,156.1,32.7,32.3],"4":[286.7,162.5,31.4,23.5]},"D","Даты рождения",[["Смотрим на середину","Между днями рождения Маши и Миши столько суток, сколько дней в том месяце, с которого начинается этот промежуток. День рождения Даши делит промежуток пополам. Для этого число суток должно быть чётным."],["Проверяем август","Чтобы середина пришлась на август, два дня рождения должны быть в июле и августе или в августе и сентябре. И в июле, и в августе 31 день. Такой промежуток не делится на два целых числа дней."],["Проверяем остальные варианты","Можно взять промежутки в 30 суток с 1 апреля по 1 мая, с 30 апреля по 30 мая, с 30 июня по 30 июля или с 30 ноября по 30 декабря. Их середины попадают соответственно в апрель, май, июль и декабрь."]],""],[824,133,"В десятичной записи числа 79865 использованы 5 последовательных цифр. Чему равна третья цифра следующего пятизначного числа, обладающего таким же свойством?",{"0":[45.1,101.5,31.4,23.5],"1":[159.8,101.5,31.4,23.5],"2":[286.7,101.5,32.7,23.5],"3":[413.5,95.1,32.7,32.3],"4":[561.5,95.1,31.3,32.3]},"B","Пять последовательных цифр",[["Проверяем числа на семёрку","Если новое число начинается с 7, то для числа больше 79 865 вторая цифра тоже должна быть 9. Тогда набор цифр — 5, 6, 7, 8, 9. Остаток 865 уже составлен в убывающем порядке и даёт наибольший возможный хвост."],["Строим следующее число","Начинаем с 8. Самая маленькая цифра, которая может идти с ней в наборе из пяти последовательных цифр, — 4. Остальные ставим по возрастанию. Получаем 84 567, третья цифра — 5."]],""],[824,262,"После того, как из мозаики вынули две фигурки, составленные из ее элементов, образовалась «дырка» (см. рисунок). Какие фигурки вынули?",{"0":[45.1,230.7,31.4,23.5],"1":[208.3,230.7,31.4,23.5],"2":[354.7,230.7,32.7,23.5],"3":[501.2,224.2,32.7,32.3],"4":[647.8,230.7,31.4,23.5]},"D","Дырка в мозаике",[["Считаем элементы","В дырке 17 кружков. Фигурки 1, 2, 3 и 4 занимают 10, 9, 7 и 8 кружков. Подходят по числу кружков пары 1 и 3 либо 2 и 4."],["Проверяем фигурку 4","Фигурку 4 можно вложить как на рисунке, начав у левого края дырки во втором ряду сверху, или перевернуть и начать там же на ряд ниже. В обоих случаях среди оставшихся кружков есть один оторванный от остальных, поэтому единая фигурка 2 туда не встанет."],["Заполняем пустоту","Повернём фигурку 3 на четверть оборота по часовой стрелке и закроем ею верх дырки. В оставшееся место точно входит фигурка 1 после половины оборота."]],""],[824,214,"Вася изменяет число, написанное на доске, по следующему правилу: если это число делится на 3, то Вася вычитает из него 1; если число дает остаток 2 при делении на 3, то Вася вычитает из него 2; а если число дает остаток 1, то Вася прибавляет к нему 2. Он начинает с числа 10000. Какое число получит Вася после 2003 таких операций?",{"0":[45.1,182.5,31.4,23.5],"1":[208.3,182.5,31.4,23.5],"2":[354.8,182.5,32.7,23.5],"3":[501.2,176.1,32.6,32.3],"4":[647.8,182.5,31.4,23.5]},"D","Число на доске",[["Делаем первый ход","10 000 даёт остаток 1 при делении на 3. Прибавляем 2 и получаем 10 002. Оно делится на 3."],["Замечаем цикл","У числа, кратного 3, сначала вычитаем 1 и получаем остаток 2. Потом вычитаем 2 и снова получаем число, кратное 3. За каждые два хода число уменьшается на 3."],["Считаем оставшиеся ходы","После первого хода осталось 2002 хода, то есть 1001 пара. Получаем 10 002 − 1001 × 3 = 6999."]],""],[824,160,"Четыре девочки поют песни, аккомпанируя друг другу по очереди: каждый раз одна из них играет, остальные три поют. Оказалось, что Анна спела больше всех песен – восемь, а Дороти спела меньше всех – пять. Сколько всего песен спели девочки?",{"0":[45.1,128.5,31.4,23.5],"1":[164.9,128.5,31.4,23.5],"2":[258.2,128.5,32.7,23.5],"3":[371.2,122.0,32.6,32.3],"4":[464.7,128.5,31.4,23.5]},"D","Песни четырёх девочек",[["Считаем участия в пении","Анна спела 8 песен, Дороти — 5. Каждая из двух остальных спела больше 5 и меньше 8 песен, то есть 6 или 7."],["Считаем песни","Общее число участий от 8 + 5 + 6 + 6 = 25 до 8 + 5 + 7 + 7 = 27. Каждую песню поют три девочки, поэтому это число должно делиться на 3. Подходит 27, и песен было 27 ÷ 3 = 9."]],""]]],[2004,"3–4 классы",[[824,248,"У Гарри Поттера есть волшебные очки, в которых он видит все красное — белым, а все белое — красным. Гарри посмотрел через свои волшебные очки на прямоугольник, изображенный справа. Что он увидел?",{"0":[84.3,216.7,31.3,23.5],"1":[227.9,216.7,31.3,23.5],"2":[367.9,216.7,32.6,23.5],"3":[507.7,216.7,32.6,23.5],"4":[647.7,216.7,31.3,23.5]},"B","Волшебные очки",[["Поменяй цвета","Верхняя строка исходного рисунка слева направо белая, красная, белая, красная. В очках порядок цветов будет обратным."],["Проверь остальные клетки","Во второй строке красной станет только правая клетка, а в третьей — только вторая слева. Все три строки совпадают с рисунком B."]],""],[824,100,"Чему равна сумма двух чисел, если она на 3 больше одного из этих чисел и на 4 больше другого?",{"0":[45.1,68.1,31.3,23.5],"1":[208.3,68.1,31.3,23.5],"2":[354.8,68.1,32.6,23.5],"3":[501.1,68.1,32.6,23.5],"4":[647.7,68.1,31.3,23.5]},"D","Два слагаемых",[["Восстанови числа","Сумма получается, когда к первому числу прибавляют второе. Если сумма на 3 больше первого числа, второе равно 3."],["Вычисли сумму","По тому же правилу первое число равно 4. Вместе получаем 3 + 4 = 7."]],""],[824,181,"На участке дороги идет ремонт. Водителям приходится объезжать этот участок по запасному пути, отмеченному на плане пунктиром. На сколько километров увеличивает путь этот объезд?",{"0":[45.1,149.1,31.3,23.5],"1":[155.0,149.1,31.3,23.5],"2":[258.3,149.1,32.7,23.5],"3":[364.7,149.1,32.7,23.5],"4":[478.1,149.1,31.3,23.5]},"C","Дорога в объезд",[["Сравни горизонтальные отрезки","Объезд идёт по трём сторонам прямоугольника. Нижний горизонтальный отрезок такой же длины, как закрытый участок сверху."],["Сложи добавленные отрезки","К прежней длине добавились спуск и подъём по 3 км. Получается 3 + 3 = 6 км."]],""],[824,153,"Сережа шел по лестнице, шагая через ступеньку (первую ступеньку он пропустил). При этом он считал шаги: «Один, два, три…». После того, как он сказал «пять», оказалось, что осталась одна ступенька. Сколько всего ступенек на лестнице?",{"0":[45.1,122.2,31.3,23.5],"1":[208.3,122.2,31.3,23.5],"2":[354.8,122.2,32.6,23.5],"3":[501.2,122.2,32.6,23.5],"4":[647.8,122.2,31.3,23.5]},"D","Шаги по лестнице",[["Посчитай пройденные ступеньки","Первый шаг привёл Серёжу на вторую ступеньку. Дальше он наступал на ступеньки 4, 6, 8 и 10."],["Учти последнюю","После пятого шага осталась ещё одна ступенька. Всего их 10 + 1 = 11."]],""],[824,213,"Какие числа расположены одновременно в прямоугольнике и в круге, но не в треугольнике?",{"0":[45.1,109.5,31.3,23.5],"1":[208.3,109.5,31.3,23.5],"2":[354.8,109.5,32.6,23.5],"3":[45.1,143.5,32.6,23.5],"4":[208.2,143.5,31.3,23.5]},"B","Пересечение фигур",[["Найди общую область","Внутри круга и прямоугольника одновременно находятся 1, 10 и 13."],["Проверь треугольник","Число 13 лежит также внутри треугольника. Снаружи треугольника остаются 1 и 10."]],""],[824,70,"Какое число пропущено: 2004 – 1389 = … – 1489?",{"0":[45.1,41.1,31.3,23.5],"1":[208.3,41.1,31.3,23.5],"2":[354.8,41.1,32.6,23.5],"3":[501.2,41.1,32.6,23.5],"4":[647.8,41.1,31.3,23.5]},"C","Равные разности",[["Сравни вычитаемые","Число 1489 больше числа 1389 на 100. Если вычитать на 100 больше из того же числа, ответ уменьшится на 100."],["Сохрани разность","Увеличь первое число тоже на 100. Получится 2004 + 100 = 2104."]],""],[845,188,"Миша хочет обвести каждую из фигур А – Е фломастером, не отрывая фломастер от листа бумаги и не проводя по одной линии дважды. Какую фигуру он не сможет так обвести?",{"0":[77.8,156.5,31.4,23.5],"1":[194.9,156.5,31.4,23.5],"2":[311.5,156.5,32.7,23.5],"3":[431.4,156.5,32.7,23.5],"4":[594.5,156.5,31.4,23.5]},"C","Рисунок одним штрихом",[["Проверь угол","Когда фломастер приходит в угол по одной линии и уходит по другой, он использует сразу две линии. Угол с нечётным числом линий должен стать началом или концом пути."],["Сосчитай нечётные вершины","У фигуры C из каждого из четырёх углов выходят по три линии. Для четырёх таких углов двух концов пути не хватит."]],""],[845,123,"Разглядывая семейный альбом, Ванечка нашел там фотографии своих двух бабушек и двух дедушек. А сколько бабушек и дедушек имели его бабушки и дедушки все вместе?",{"0":[45.1,91.1,31.3,23.5],"1":[208.3,91.1,31.3,23.5],"2":[354.8,91.1,32.6,23.5],"3":[501.2,91.1,32.6,23.5],"4":[647.8,91.1,31.3,23.5]},"D","Бабушки и дедушки",[["Сосчитай людей на фотографиях","У Ванечки две бабушки и два дедушки. Всего таких родственников четверо."],["Посчитай их бабушек и дедушек","У каждого из них тоже две бабушки и два дедушки. Получается 4 × 4 = 16."]],""],[845,186,"Какие фигурки надо взять, чтобы из них можно было составить круг? 1 2 3 4",{"0":[45.1,154.4,31.3,23.5],"1":[208.3,154.4,31.3,23.5],"2":[354.8,154.4,32.6,23.5],"3":[501.2,154.4,32.6,23.5],"4":[647.8,154.4,31.3,23.5]},"D","Круг из кусочков",[["Найди округлые края","У деталей 1 и 4 есть закруглённые внешние края. Поверни детали так, чтобы эти края образовали внешнюю границу круга, а выемки смотрели внутрь."],["Заполни середину","Деталь 2 входит между ними. Её изогнутая выемка прилегает к округлому выступу детали 1. Нужны детали 1, 2 и 4."]],""],[845,123,"В коридоре детского сада стояли двухколесные и трехколесные велосипеды. Катя подсчитала, что колес – 18, а рулей всего 7. Сколько было двухколесных велосипедов?",{"0":[45.1,91.2,31.3,23.5],"1":[208.3,91.2,31.3,23.5],"2":[354.8,91.2,32.6,23.5],"3":[501.2,91.2,32.6,23.5],"4":[647.8,91.2,31.3,23.5]},"B","Велосипеды и колёса",[["Начни с двух колёс на руль","Семь рулей означают семь велосипедов. Если дать каждому по два колеса, потребуется 7 × 2 = 14 колёс."],["Распредели оставшиеся колёса","Ещё 18 − 14 = 4 колеса достаются четырём трёхколёсным велосипедам. Двухколёсных было 7 − 4 = 3."]],""],[845,149,"Весь класс, в котором учатся Маша и Даша, выстроился в колонну по одному. Позади Маши стоит 16 человек, включая Дашу, а впереди Даши стоит 14 человек. Сколько ребят в классе, если между Машей и Дашей стоит 7 человек?",{"0":[45.1,116.8,31.3,23.5],"1":[208.3,116.8,31.3,23.5],"2":[354.8,116.8,32.6,23.5],"3":[501.3,116.8,32.6,23.5],"4":[647.9,116.8,31.3,23.5]},"C","Школьная колонна",[["Раздели колонну на части","Впереди Даши стоят Маша, семь человек между девочками и те, кто впереди Маши. Значит, перед Машей стоят 14 − 1 − 7 = 6 человек."],["Собери всю колонну","Шесть человек стоят впереди Маши, за ней — шестнадцать. Вместе с самой Машей в классе 6 + 1 + 16 = 23 человека."]],""],[845,311,"Часовщик смотрит на 4 будильника. Только один из этих будильников показывает верное время. Из оставшихся один спешит на 20 минут, другой отстает на 20 минут, а третий вовсе стоит. Какое время показывает правильно идущий будильник?",{"0":[45.1,257.2,31.3,23.5],"1":[286.9,257.2,31.3,23.5],"2":[519.4,257.2,32.6,23.5],"3":[45.1,282.9,32.6,23.5],"4":[286.8,282.9,31.3,23.5]},"B","Четыре будильника",[["Найди показания с равным шагом","Верное время должно быть ровно на 20 минут позже одного показания и на 20 минут раньше другого. На циферблатах такой ряд образуют 4:45, 5:05, 5:25."],["Выбери середину","Между 4:45 и 5:25 находится 5:05. Его показывает правильно идущий будильник."]],""],[824,92,"В некотором месяце 3 воскресенья приходятся на четные числа. На какой день недели приходится 25-е число этого месяца?",{"0":[45.1,60.7,31.3,23.5],"1":[208.4,60.7,31.3,23.5],"2":[354.9,60.7,32.6,23.5],"3":[501.2,60.7,32.6,23.5],"4":[647.9,60.7,31.3,23.5]},"A","Воскресенья в календаре",[["Найди первое воскресенье","Между воскресеньями по семь дней, поэтому чётные и нечётные даты чередуются. Для трёх чётных воскресений всего должно быть пять воскресений, а первое должно быть чётным."],["Перейди к 25-му числу","Первое воскресенье может быть только 2-го числа. Если взять 4-е или позже, пятое воскресенье попадёт на 32-е или позже. Воскресенья идут 2, 9, 16, 23 и 30-го, поэтому 25-е — вторник."]],""],[824,117,"Карина нашла старую книгу, в которой не хватало нескольких страниц. Последняя страница перед потерянной частью имеет номер 24, а первая после нее – 45. Сколько листков выпало из книги?",{"0":[45.1,86.3,31.3,23.5],"1":[208.3,86.3,31.3,23.5],"2":[354.8,86.3,32.6,23.5],"3":[501.2,86.3,32.6,23.5],"4":[647.8,86.3,31.3,23.5]},"B","Выпавшие листы",[["Посчитай страницы","Выпали страницы с 25-й по 44-ю включительно. Их 44 − 25 + 1 = 20."],["Посчитай листы","На каждом листе две страницы. Значит, выпало 20 : 2 = 10 листов."]],""],[824,148,"В каждую клеточку квадрата 2х2 вписано какое-то число. Сумма чисел в верхней строчке равна 3, а в нижней – 8. Чему равна сумма в правом столбике, если сумма чисел левого столбика равна 4?",{"0":[45.1,116.7,31.3,23.5],"1":[164.9,116.7,31.3,23.5],"2":[284.9,116.7,32.6,23.5],"3":[404.6,116.7,32.6,23.5],"4":[524.5,116.7,31.3,23.5]},"C","Суммы в квадрате",[["Сложи суммы строк","Сумма всех четырёх чисел равна 3 + 8 = 11."],["Вычти левый столбец","На левый столбец приходится 4. Значит, в правом столбце сумма равна 11 − 4 = 7."]],""],[824,153,"Во сколько раз миллион миллиардов отличается от миллиарда миллионов?",{"0":[45.1,65.5,31.3,23.5],"1":[354.8,65.5,31.3,23.5],"2":[45.1,93.4,32.6,23.5],"3":[354.8,93.4,32.6,23.5],"4":[45.1,121.4,31.3,23.5]},"D","Миллион миллиардов",[["Запиши два произведения","Миллион миллиардов — это миллион, умноженный на миллиард. Миллиард миллионов — это миллиард, умноженный на миллион."],["Поменяй множители местами","При перестановке множителей произведение остаётся тем же. Оба числа равны."]],""],[824,97,"У Эдварда 2004 фантика. Половина из них синие, четверть – красные, третья часть остальных – зеленые. Сколько у него зеленых фантиков?",{"0":[45.1,65.4,31.3,23.5],"1":[208.3,65.4,31.3,23.5],"2":[354.8,65.4,32.6,23.5],"3":[501.2,65.4,32.6,23.5],"4":[647.8,65.4,31.3,23.5]},"B","Зелёные фантики",[["Найди оставшуюся четверть","Половина — это две четверти. Вместе с красной четвертью это три четверти всех фантиков. Остаётся одна четверть, то есть 2004 : 4 = 501."],["Возьми треть остатка","Зелёных фантиков 501 : 3 = 167."]],""],[824,237,"На каждой грани бумажного кубика написана цифра 1, 2 или 3, причем цифры на противоположных гранях одинаковы. Какая из фигурок может получиться, если этот кубик разрезать по некоторым ребрам и развернуть?",{"0":[77.8,205.4,31.4,23.5],"1":[237.9,205.4,31.4,23.5],"2":[394.5,205.4,32.7,23.5],"3":[557.8,205.4,32.7,23.5],"4":[704.4,205.4,31.4,23.5]},"E","Противоположные грани",[["Сверни полоску в пояс","Четыре квадрата в ряд образуют боковые грани куба. При этом первая грань окажется напротив третьей, а вторая — напротив четвёртой."],["Сверь три пары","В E в ряду стоят 1, 2, 1, 2. Оставшиеся грани с тройками закрывают пояс сверху и снизу. Все три противоположные пары совпадают."]],""],[824,174,"В полдень на детскую площадку пришел Вася, через два часа после него – Маша, а через полтора часа после нее – Никита. Вася играл четыре часа, Маша – три, а Никита – два часа. Как долго Маша и Никита были на площадке вдвоем?",{"0":[45.1,116.8,31.3,23.5],"1":[286.9,116.8,31.3,23.5],"2":[519.3,116.8,32.6,23.5],"3":[45.1,142.5,32.6,23.5],"4":[286.8,142.5,31.3,23.5]},"B","На площадке вдвоём",[["Запиши время прихода и ухода","Вася был на площадке с 12:00 до 16:00, Маша — с 14:00 до 17:00, Никита — с 15:30 до 17:30."],["Найди время без Васи","Маша и Никита остались вдвоём после ухода Васи в 16:00 и до ухода Маши в 17:00. Прошёл один час."]],""],[824,118,"Два ковша воды – это половина ведерка, а три чашки – это половина ковша. Тогда два ведерка – это",{"0":[45.1,65.5,31.3,23.5],"1":[286.9,65.5,31.3,23.5],"2":[519.4,65.5,32.6,23.5],"3":[45.1,91.1,32.6,23.5],"4":[286.9,91.1,31.3,23.5]},"B","Ведёрки, ковши и чашки",[["Переведи в ковши","В половине ведёрка 2 ковша, значит, в целом 4 ковша, а в двух ведёрках — 8."],["Переведи в чашки","В половине ковша 3 чашки, значит, в целом ковше их 6. Восемь ковшей — это 8 × 6 = 48 чашек."]],""],[845,141,"В трех играх чемпионата по футболу команда забила 3 гола и пропустила в свои ворота 1 гол. За каждую победу команда получает 3 очка, за ничью – 1 очко, а за поражение — 0 очков. Сколько очков не могла набрать команда за эти 3 игры?",{"0":[45.1,109.0,31.3,23.5],"1":[208.3,109.0,31.3,23.5],"2":[354.8,109.0,32.6,23.5],"3":[501.2,109.0,32.6,23.5],"4":[647.8,109.0,31.3,23.5]},"E","Очки за три матча",[["Проверь три очка","Для трёх очков нужны либо три ничьи, либо победа и два поражения. При трёх ничьих команда забила бы столько же голов, сколько пропустила. При двух поражениях она пропустила бы хотя бы два."],["Приведи примеры остальных итогов","Четыре очка дают счета 3:0, 0:0, 0:1. Пять дают 2:0, 1:1, 0:0. Шесть дают 2:0, 1:0, 0:1. Семь дают 1:0, 1:0, 1:1. Только три очка получить нельзя."]],""],[845,213,"В верхнюю строчку и первый столбец квадратной таблицы (кроме угловой клетки) записали какието числа, и для этих чисел составили таблицу умножения. Потом некоторые числа стерли, а некоторые заменили буквами. Какие две буквы заменяют одно и то же число?",{"0":[45.1,157.6,31.3,23.5],"1":[208.3,157.6,31.3,23.5],"2":[354.8,157.6,32.6,23.5],"3":[45.1,181.9,32.6,23.5],"4":[208.3,181.9,31.3,23.5]},"E","Таблица умножения",[["Восстанови заголовки строк","Число слева от 36 и 8 должно делить оба числа, а число слева от 27 и 6 — делить эти два. В столбце с 8 и 6 заголовок делит и 8, и 6. Это 1 или 2. При 1 заголовок строки был бы 8, но 36 на 8 не делится."],["Сравни буквы","Заголовок столбца равен 2. Тогда заголовок строки с 8 равен 4, и Г = 4 × (18 : 6) = 12. В том же столбце, где стоит 8, буква А равна 6 × 2 = 12."]],""],[845,165,"Длинную нитку сложили вдвое, еще раз вдвое и еще раз вдвое. Получившуюся толстую «нитку» разрезали на две части и разобрали обратно на тонкие ниточки. Оказалось, что две из этих ниточек имеют длины 4 см и 9 см. Какова наименьшая возможная длина исходной нитки?",{"0":[45.1,133.3,31.3,23.5],"1":[208.3,133.3,31.3,23.5],"2":[354.8,133.3,32.6,23.5],"3":[501.1,133.3,32.6,23.5],"4":[647.7,133.3,31.3,23.5]},"B","Сложенная нитка",[["Посмотри на один слой","После трёх сгибов получилось восемь слоёв. Разрез делит каждый слой на части длиной x и y. Если x взять со стороны свободных концов, короткие части у этих концов имеют длину x, а части со сгибом — 2x или 2y."],["Выбери длину слоя","Числа 4 и 9 не могут одновременно быть x и 2x, поэтому одно из них относится к x, а другое к y. Чтобы слой был как можно короче, возьмём два отрезка со сгибами, длиной 2x и 2y. Тогда x + y = 4 : 2 + 9 : 2 = 6,5 см. Вся нитка имеет длину 8 × 6,5 = 52 см."]],""],[845,267,"Каждая из фигурок А – D состоит из 7 кубиков. Какую из них нельзя составить из деталей, изображенных справа?",{"0":[58.2,215.7,31.4,23.5],"1":[168.3,215.7,31.4,23.5],"2":[311.5,215.7,32.7,23.5],"3":[444.8,215.7,32.7,23.5],"4":[544.6,215.7,31.4,23.5]},"E","Фигуры из кубиков",[["Раздели A и B","Для A возьми самую высокую колонку и нижний кубик соседней колонки. Для B возьми весь нижний ряд и средний по высоте кубик крайней колонки. В обоих случаях получается длинный уголок из четырёх кубиков и малый уголок из трёх."],["Раздели C и D","У C малый уголок образуют два верхних кубика слева сзади и самый верхний справа сзади. Остаётся объёмная деталь из четырёх кубиков. У D два верхних кубика высокой колонки и два кубика справа образуют деталь-ступеньку. Оставшиеся три — малый уголок. Значит, собрать можно все четыре фигуры."]],""],[845,167,"В треугольнике отмечены вершины и, кроме того, по одной точке на каждой из сторон. Сколько треугольников с вершинами в отмеченных точках можно построить?",{"0":[45.1,109.0,31.3,23.5],"1":[208.3,109.0,31.3,23.5],"2":[354.8,109.0,32.6,23.5],"3":[45.1,135.7,32.6,23.5],"4":[208.3,135.7,31.3,23.5]},"C","Треугольники из точек",[["Выбери три точки","Из шести точек можно составить 6 × 5 × 4 = 120 списков из трёх различных точек. Один и тот же набор записывается шестью способами, поэтому наборов 120 : 6 = 20."],["Убери наборы на прямой","На каждой стороне большого треугольника есть ровно три отмеченные точки. Из них треугольник не получается. Остаётся 20 − 3 = 17."]],""],[845,116,"Разность двух четырехзначных чисел равна 7. Для каждого из этих чисел Вася вычислил сумму цифр, а потом из большей суммы вычел меньшую. Какой результат он не мог получить?",{"0":[45.1,84.7,31.3,23.5],"1":[208.3,84.7,31.3,23.5],"2":[354.8,84.7,32.6,23.5],"3":[501.2,84.7,32.6,23.5],"4":[647.8,84.7,31.3,23.5]},"D","Суммы цифр",[["Проследи за переносами","От меньшего числа к большему можно перейти прибавлением 7. Без переносов сумма цифр выросла бы на 7. Каждый перенос заменяет десять единиц в одном разряде одной единицей в следующем и уменьшает сумму цифр на 9."],["Перебери число переносов","Возможны 0, 1, 2 или 3 переноса, поскольку оба числа четырёхзначные. Изменения суммы равны 7, −2, −11, −20. После вычитания меньшей суммы из большей получаются 7, 2, 11 и 20. Число 13 получить нельзя."]],""]]],[2005,"3–4 классы",[[824,99,"В этом году ежегодный конкурс «Кенгуру» проводится в России уже в 12-й раз. В каком году был первый конкурс?",{},"B","Первый конкурс",[["Посчитай промежутки","От первого конкурса до двенадцатого проходит 11 лет. Первый конкурс уже входит в число двенадцати."],["Отсчитай годы назад","Вычти 11 из 2005. Первый конкурс прошёл в 1994 году."]],""],[824,97,"Общий вес троих детей 72 кг. Маша весит столько же, сколько два ее младших брата вместе. Сколько весит Маша?",{"0":[51.7,65.9,31.3,23.5],"1":[208.4,65.9,31.3,23.5],"2":[355.0,65.9,32.6,23.5],"3":[501.4,65.9,32.6,23.5],"4":[648.1,65.9,31.3,23.5]},"D","Вес Маши",[["Раздели общий вес","Троих детей можно разделить на две группы одинакового веса. В одной Маша, в другой — два брата."],["Найди вес одной группы","Маша весит половину общего веса, то есть 72 : 2 = 36 кг."]],""],[824,273,"Каждый из восьми кенгуру может перепрыгнуть на любую клетку квадратной таблицы 4×4. Им надо расположиться так, чтобы в каждой строчке и каждом столбце этой таблицы оказалось ровно по 2 кенгуру. Наименьшее число кенгуру, которым придется для этого прыгнуть, равно",{"0":[51.7,210.2,31.3,23.5],"1":[211.6,210.2,31.3,23.5],"2":[371.5,210.2,32.6,23.5],"3":[51.7,241.9,32.6,23.5],"4":[211.6,241.9,31.3,23.5]},"D","Прыжок одного кенгуру",[["Найди избыток и нехватку","Во второй строке три кенгуру, а в четвёртой — один. В третьем столбце три кенгуру, а во втором — один."],["Сделай один прыжок","Кенгуру из второй строки третьего столбца прыгает в четвёртую строку второго столбца. Теперь в каждой строке и каждом столбце по два. Без прыжка условие не выполнялось."]],""],[824,188,"В магазин привезли 4 одинаковые полные коробки: в одной – апельсины, в другой – яблоки, в третьей – мандарины, в четвертой – вишни. В какой коробке наибольшее число плодов?",{"0":[51.7,92.8,31.3,23.5],"1":[51.7,124.6,31.3,23.5],"2":[51.7,156.3,32.6,23.5],"3":[444.9,92.8,32.6,23.5],"4":[444.9,124.6,31.3,23.5]},"D","Четыре коробки",[["Сравни размеры плодов","Коробки одинаковые по размеру и заполнены. Из перечисленных плодов вишни самые мелкие."],["Выбери коробку","Мелкие плоды занимают меньше места по одному. Поэтому больше всего плодов в коробке с вишнями."]],""],[824,144,"Бабочка села на записанное в тетради верное равенство. Какое число она закрыла?",{"0":[51.7,112.0,31.3,23.5],"1":[208.4,112.0,31.3,23.5],"2":[354.9,112.0,32.6,23.5],"3":[501.4,112.0,32.6,23.5],"4":[648.0,112.0,31.3,23.5]},"C","Число под бабочкой",[["Вычисли левую часть","На рисунке слева записано 2005 − 205. Это 1800."],["Восстанови второе слагаемое","Справа к 1300 прибавили скрытое число и тоже получили 1800. Под бабочкой 1800 − 1300 = 500."]],""],[824,126,"Какое из чисел обладает такими свойствами: оно четное, все его цифры различны, а число сотен в два раза больше числа единиц?",{"0":[51.7,95.2,31.3,23.5],"1":[208.4,95.2,31.3,23.5],"2":[355.0,95.2,32.6,23.5],"3":[501.4,95.2,32.6,23.5],"4":[648.1,95.2,31.3,23.5]},"E","Число с тремя условиями",[["Проверь чётность и цифры","Число 4683 нечётное. В числе 4874 повторяется цифра 4. Для следующей проверки остаются 1236, 3478 и 8462."],["Сравни сотни и единицы","В 1236 цифра сотен 2, а цифра единиц 6. В 3478 это 4 и 8. В обоих случаях сотен меньше. Лишь у 8462 цифра сотен 4 вдвое больше цифры единиц 2."]],""],[845,229,"Квадрат разрезали на 3 кусочка. Два из них изображены на рисунке справа. Укажите третий кусочек.",{"0":[84.4,197.1,31.4,23.5],"1":[221.4,197.1,31.4,23.5],"2":[344.9,197.1,32.6,23.5],"3":[514.4,197.1,32.6,23.5],"4":[680.6,197.1,31.4,23.5]},"B","Третий кусочек квадрата",[["Соедини скошенные края","Сдвинь правую деталь вниз и влево, чтобы её наклонная сторона прилегла к наклонной стороне левой детали."],["Посмотри на пустой угол","Правая деталь образует нижний край большого квадрата. Для завершения верхнего правого угла не хватает маленького квадрата B."]],""],[845,127,"В летнем лагере «Кенгуру» Алеша решал по 4 задачи в день, а Андрей – по 2 задачи. Алеша решил все задачи за 5 дней. За сколько дней решил эти же задачи Андрей?",{"0":[51.7,95.2,31.3,23.5],"1":[208.3,95.2,31.3,23.5],"2":[354.9,95.2,32.6,23.5],"3":[501.4,95.2,32.6,23.5],"4":[647.9,95.2,31.3,23.5]},"E","Задачи в лагере",[["Найди общее число задач","Алёша решал по четыре задачи пять дней. Это 4 × 5 = 20 задач."],["Раздели по дням Андрея","Андрей решал по две задачи в день. Ему понадобилось 20 : 2 = 10 дней."]],""],[845,127,"Никита живет в своем доме вместе с папой, мамой и братом. А еще с ними живут собака, две кошки, два попугая и четыре золотые рыбки. Сколько всего ног у обитателей этого дома?",{"0":[51.7,95.2,31.3,23.5],"1":[208.4,95.2,31.3,23.5],"2":[355.0,95.2,32.6,23.5],"3":[501.4,95.2,32.6,23.5],"4":[648.0,95.2,31.3,23.5]},"B","Ноги обитателей дома",[["Посчитай людей и четвероногих","У четверых людей 4 × 2 = 8 ног. У собаки и двух кошек 3 × 4 = 12 лап."],["Добавь птиц","У двух попугаев ещё 2 × 2 = 4 ноги. У рыбок ног нет. Всего 8 + 12 + 4 = 24."]],""],[845,163,"Если одно из чисел увеличить в 20 раз, а другое уменьшить в 10 раз, то произведение этих чисел",{"0":[51.7,68.2,31.4,23.5],"1":[51.7,99.9,31.4,23.5],"2":[51.7,131.6,32.7,23.5],"3":[419.7,68.2,32.0,23.5],"4":[420.6,99.9,31.0,23.5]},"A","Что стало с произведением",[["Проследи за двумя действиями","Увеличение одного множителя в 20 раз увеличивает произведение в 20 раз. Уменьшение другого в 10 раз делит результат на 10."],["Объедини изменения","Умножить на 20 и разделить на 10 — то же самое, что умножить на 2. Произведение удвоится."]],""],[845,151,"На столе лежала коробка с конфетами. Саша взял оттуда половину конфет, потом половину оставшихся конфет взял Коля. Затем Света взяла из коробки половину того, что там было. После этого осталось 3 конфеты. Сколько конфет было в коробке сначала?",{"0":[51.7,119.8,31.3,23.5],"1":[208.3,119.8,31.3,23.5],"2":[354.9,119.8,32.6,23.5],"3":[501.4,119.8,32.6,23.5],"4":[648.0,119.8,31.3,23.5]},"D","Конфеты в коробке",[["Верни конфеты Светы и Коли","После Светы осталось три конфеты, то есть половина того, что было перед её ходом. До Светы было 6, а до Коли — вдвое больше, 12."],["Верни конфеты Саши","После Саши осталось 12 конфет, значит, до его хода в коробке было 12 × 2 = 24."]],""],[845,267,"За один ход Петер поворачивает квадрат с закрашенным треугольником вокруг точки P, как показано на рисунке. В каком положении будет треугольник после 17 ходов?",{"0":[78.4,236.3,31.4,23.5],"1":[225.0,236.3,31.4,23.5],"2":[371.6,236.3,32.7,23.5],"3":[518.1,236.3,32.7,23.5],"4":[664.7,236.3,31.4,23.5]},"A","Семнадцать поворотов",[["Найди полный круг","За первый ход треугольник перемещается сверху вправо, а за второй — вниз. Каждый ход поворачивает квадрат на четверть оборота. После четырёх ходов он вернётся в начальное положение."],["Оставь лишний ход","В 17 ходах четыре полных оборота и один ход. Треугольник окажется справа, как на рисунке A."]],""],[824,123,"У Даши было 9 кусочков бумаги. Некоторые из них она разрезала на три части. Всего получилось 15 кусочков. Сколько кусочков разрезала Даша?",{"0":[51.7,92.8,31.3,23.5],"1":[208.3,92.8,31.3,23.5],"2":[354.9,92.8,32.6,23.5],"3":[501.3,92.8,32.6,23.5],"4":[647.9,92.8,31.3,23.5]},"C","Разрезанные кусочки",[["Посчитай прибавку от разрезания","Когда один кусочек разрезают на три, вместо одного получаются три. Общее число увеличивается на два."],["Раздели общую прибавку","Было 9 кусочков, стало 15. Прибавилось 15 − 9 = 6, значит, разрезали 6 : 2 = 3 кусочка."]],""],[824,181,"Пять карточек с цифрами лежат на столе в таком порядке: 5, 1, 4, 3, 2. За один ход разрешается поменять местами любые две карточки. За какое наименьшее число ходов можно расположить их в порядке 1, 2, 3, 4, 5?",{"0":[51.7,149.2,31.3,23.5],"1":[161.7,149.2,31.3,23.5],"2":[271.6,149.2,32.6,23.5],"3":[381.5,149.2,32.6,23.5],"4":[491.3,149.2,31.3,23.5]},"B","Карточки по порядку",[["Получится ли за два хода","Сначала все пять карточек лежат на чужих местах. За один обмен можно поставить на места не более двух карточек. За два обмена нельзя исправить все пять."],["Выполни три обмена","Поменяй карточки 5 и 1, затем 5 и 2, затем 4 и 3. Получится 1, 2, 3, 4, 5. Значит, минимум — три хода."]],""],[824,167,"Царь Кащей подобрел и решил потратить 50 золотых монет на подарки детям. В сундуке у него хранится 5 ларцов, в каждом ларце по 3 шкатулки, а в каждой шкатулке по 10 золотых монет. Сундук, ларцы и шкатулки заперты на замки. Какое наименьшее число замков потребуется открыть Кащею, чтобы достать 50 монет?",{"0":[51.7,135.6,31.3,23.5],"1":[211.6,135.6,31.3,23.5],"2":[358.1,135.6,32.6,23.5],"3":[504.7,135.6,32.6,23.5],"4":[651.2,135.6,31.3,23.5]},"D","Замки Кащея",[["Посчитай шкатулки и ларцы","Для 50 монет нужно открыть 50 : 10 = 5 шкатулок. В одном ларце их только три, поэтому надо открыть хотя бы два ларца."],["Прибавь замок сундука","Можно взять три шкатулки из одного ларца и две из другого. Вместе с сундуком получаем 5 + 2 + 1 = 8 замков."]],""],[824,154,"Из 6 спичек можно сложить только один прямоугольник (он изображен на рисунке). Сколько различных прямоугольников можно сложить, используя каждый раз 14 спичек?",{"0":[51.7,122.2,31.3,23.5],"1":[208.3,122.2,31.3,23.5],"2":[354.9,122.2,32.6,23.5],"3":[501.3,122.2,32.6,23.5],"4":[647.9,122.2,31.3,23.5]},"C","Прямоугольники из спичек",[["Найди сумму соседних сторон","На противоположных сторонах число спичек одинаково. На две соседние стороны приходится 14 : 2 = 7 спичек."],["Перебери размеры","Пары длин равны 1 и 6, 2 и 5, 3 и 4. Переставить длины — значит повернуть тот же прямоугольник. Всего три варианта."]],""],[824,290,"Во дворе живут два кота и две собаки. Кот Малыш боится обеих собак, а кот Тоша боится Шарика и дружит с Бобиком. Какое из утверждений неверно?",{"0":[51.7,95.2,31.3,23.5],"1":[51.7,129.3,31.3,23.5],"2":[51.7,163.3,32.6,23.5],"3":[51.7,197.4,32.6,23.5],"4":[51.7,231.5,31.4,23.5]},"D","Коты и собаки",[["Сравни, кого боятся коты","Оба кота боятся Шарика. Малыш боится и Бобика, а Тоша с Бобиком дружит."],["Проверь утверждение D","Шарика боятся двое, Бобика — один. Значит, обеих собак кто-то боится. Утверждение D неверно."]],""],[824,278,"у какого-то из котов. 18. Какой из кубиков можно склеить из заготовки, изображенной справа?",{"0":[71.7,253.6,31.4,23.5],"1":[178.4,253.6,31.4,23.5],"2":[285.0,253.6,32.7,23.5],"3":[391.6,253.6,32.7,23.5],"4":[498.1,253.6,31.4,23.5]},"E","Кубик из заготовки",[["Сложи шестую грань","Полностью серая клетка станет одной гранью, четыре соседние белые клетки — стенками. Четыре маленьких квадрата сомкнутся напротив серой грани."],["Сравни видимые грани","На составной грани серые четвертинки лежат по диагонали. У куба видна хотя бы одна из двух противоположных окрашенных граней, а вместе их увидеть нельзя. Этим условиям отвечает E."]],""],[845,131,"Две девочки и три мальчика вместе съели 16 порций мороженого. Каждый мальчик съел в 2 раза больше порций, чем каждая девочка. Сколько порций съедят 3 девочки и 2 мальчика с такими же аппетитами?",{"0":[51.7,100.2,31.3,23.5],"1":[208.4,100.2,31.3,23.5],"2":[354.9,100.2,32.6,23.5],"3":[501.4,100.2,32.6,23.5],"4":[648.0,100.2,31.3,23.5]},"C","Порции мороженого",[["Вырази порции через одну девочку","Каждый мальчик съедает столько же, сколько две девочки. Значит, две девочки и три мальчика съедают столько же, сколько восемь девочек. На каждую девочку приходится 16 : 8 = 2 порции, на мальчика — 4."],["Сложи порции новой группы","Три девочки и два мальчика съедят 3 × 2 + 2 × 4 = 14 порций."]],""],[845,164,"Вокруг прямоугольного сквера проложена дорожка, которая на всем своем протяжении имеет одинаковую ширину. Наружная граница дорожки на 8 м длиннее внутренней. Чему равна ширина дорожки?",{"0":[51.7,133.2,31.4,23.5],"1":[171.7,133.2,31.4,23.5],"2":[271.6,133.2,32.6,23.5],"3":[364.8,133.2,32.6,23.5],"4":[464.9,133.2,31.4,23.5]},"B","Ширина дорожки",[["Сравни стороны прямоугольников","Каждая сторона внешнего прямоугольника длиннее соответствующей внутренней на две ширины дорожки, по одной с каждого конца."],["Сравни периметры","У четырёх сторон разница в сумме составляет восемь ширин. Это 8 м, поэтому ширина равна 8 : 8 = 1 м."]],""],[845,110,"У каждого двузначного числа нашли произведение цифр, потом у каждого такого произведения подсчитали сумму цифр. Какая сумма самая большая?",{"0":[51.7,78.7,31.3,23.5],"1":[165.0,78.7,31.3,23.5],"2":[278.2,78.7,32.6,23.5],"3":[391.5,78.7,32.6,23.5],"4":[504.8,78.7,31.3,23.5]},"C","Сумма цифр произведения",[["Найди большую сумму","Можно взять число 77. Произведение его цифр 7 × 7 = 49, а сумма цифр произведения равна 4 + 9 = 13."],["Проверь большие суммы","Произведение не больше 9 × 9 = 81. До 81 сумму цифр больше 13 имеют только 59, 68, 69, 77, 78 и 79."],["Проверь множители","59 и 79 — простые. В остальных числах есть множитель больше 9: 68 = 4 × 17, 69 = 3 × 23, 77 = 7 × 11, 78 = 6 × 13. Ни одно не получается из двух цифр. Наибольшая сумма — 13."]],""],[845,162,"",{},"B","Треугольники и квадраты",[["Посчитай треугольники по размеру","У каждого треугольника наклонная сторона лежит на большой наклонной стороне рисунка. Треугольников с катетом в одну клетку 5, с катетом в две — 4, далее 3, 2 и 1. Итого 15."],["Посчитай квадраты","Квадратов в одну клетку по рядам 4, 3, 2 и 1, всего 10. Квадратов со стороной в две клетки 3. Более крупный квадрат не помещается."],["Сравни результаты","Треугольников на 15 − 13 = 2 больше."]],""],[845,115,"В семье четверо детей, им 5, 8, 13 и 15 лет, а зовут их Таня, Юра, Света и Лена. Одна девочка ходит в детский сад, Таня старше Юры, а сумма лет Тани и Светы делится на три. Сколько лет Лене?",{"0":[51.7,84.6,31.3,23.5],"1":[151.7,84.6,31.3,23.5],"2":[242.1,84.6,32.6,23.5],"3":[351.6,84.6,32.6,23.5],"4":[451.4,84.6,31.3,23.5]},"D","Возраст детей",[["Выбери пару с подходящей суммой","Из данных возрастов только пары 5 и 13, а также 8 и 13 дают сумму, кратную трём. Это возможные возрасты Тани и Светы."],["Учти, кто ходит в детский сад","Пятилетний ребёнок — девочка. Если бы Тане и Свете было 8 и 13, Юре пришлось бы быть пятилетним, иначе он был бы старше Тани."],["Определи возраст Лены","Значит, Свете 5, Тане 13, Юре 8. Лене остаётся 15 лет."]],""],[845,164,"Австралийский ленивец Бумми почти всю жизнь проводит на дереве. Однако, если месяц начинается и кончается одним и тем же днем недели, то он слезает с дерева и отправляется путешествовать на весь этот месяц. Сколько месяцев с начала 2005 года по конец 2015 года Бумми проведет в путешествиях?",{"0":[51.7,133.2,31.3,23.5],"1":[208.3,133.2,31.3,23.5],"2":[354.9,133.2,32.6,23.5],"3":[501.4,133.2,32.6,23.5],"4":[648.0,133.2,31.3,23.5]},"B","Путешествия Бумми",[["Найди длину месяца","От первого до последнего числа месяца проходит на один день меньше, чем дней в месяце. Чтобы дни недели совпали, это число должно делиться на 7. Для месяцев длиной 28, 29, 30 или 31 день подходит только 29."],["Посчитай високосные февралѝ","С 2005 по 2015 год 29 дней было только в феврале 2008 и в феврале 2012 года. Значит, Бумми путешествовал два месяца."]],""],[845,140,"На белой доске 5×5 Петя закрасил какие-то клетки синим цветом, а какие-то – красным (каждым цветом закрашена хотя бы одна клетка). Никакие две клетки красного и синего цвета не имеют общей стороны. Какое наибольшее число клеток могло быть закрашено?",{"0":[51.7,109.0,31.3,23.5],"1":[208.4,109.0,31.3,23.5],"2":[355.0,109.0,32.6,23.5],"3":[501.5,109.0,32.6,23.5],"4":[648.1,109.0,31.3,23.5]},"B","Закраска доски",[["Докажи, что нужна хотя бы пара белых клеток","Если оставить белой лишь одну клетку, в каждой из остальных строк и столбцов можно свободно пройти по закрашенным клеткам. Даже из строки с белой клеткой можно выйти по целому столбцу. Значит, любую закрашенную клетку можно соединить с любой другой по общим сторонам."],["Сохрани два цвета","На пути от красной к синей клетке где-то встретились бы соседи разных цветов. Поэтому одной белой клетки мало. Оставь белыми две клетки, соседние с угловой. Угол закрась красным, остальные — синим. Получится 25 − 2 = 23 закрашенные клетки."]],""],[845,142,"В числовом ребусе различные значки обозначают различные цифры, а одинаковые значки – одинаковые цифры. Какую наименьшую цифру может обозначать?",{"0":[45.1,111.4,31.3,23.5],"1":[171.7,111.4,31.3,23.5],"2":[291.5,111.4,32.6,23.5],"3":[411.5,111.4,32.6,23.5],"4":[531.4,111.4,31.3,23.5]},"B","Треугольник в ребусе",[["Сравни десятки и сотни","До учёта переносов в десятках и в сотнях складываются одни и те же три цифры. В сотнях вместе с переносом должно выйти 20. Перенос из десятков не больше 2, поэтому сумма трёх цифр без переноса не меньше 18."],["Вычисли сумму единиц","В десятках сумма с переносом оканчивается нулём. Она не меньше 18 и не больше 9 + 8 + 7 + 2 = 26, поэтому равна 20. В сотни переносят 2, сумма трёх разных цифр равна 18. Из единиц тоже перенесли 2, ведь в десятках с переносом получилось 20."],["Найди наименьший треугольник","В единицах квадрат и два треугольника дают 25. Если треугольник равен 7 или меньше, квадрат пришлось бы сделать не меньше 11. При треугольнике 8 квадрат равен 9, сердце — 1. Проверка: 999 + 118 + 888 = 2005."]],""]]],[2006,"3–4 классы",[[822,131,"Вася поет слово КЕНГУРУ. Он тянет каждый гласный звук 5 секунд, а на каждый согласный тратит ровно 1 секунду. Сколько времени он поет это слово?",{"0":[53.7,95.9,31.3,27.2],"1":[211.6,95.9,31.3,27.2],"2":[358.2,95.9,32.7,27.2],"3":[504.8,95.9,32.6,27.2],"4":[651.3,95.9,31.3,27.2]},"C","Вася поёт",[["Посчитай звуки","В слове КЕНГУРУ три гласных — Е, У, У, и четыре согласных — К, Н, Г, Р."],["Сложи секунды","На гласные уйдёт 3 × 5 = 15 секунд, на согласные — 4 × 1 = 4 секунды. Вместе 15 + 4 = 19 секунд."]],""],[822,124,"",{"0":[53.7,41.9,31.3,27.2],"1":[211.6,41.9,31.3,27.2],"2":[358.1,41.9,32.7,27.2],"3":[53.7,76.0,32.6,27.2],"4":[211.6,76.0,31.3,27.2]},"D","Сколько кубиков вынули",[["Посчитай слои","Сначала в каждом слое было по 3 × 3 = 9 кубиков. Нижний слой остался целым."],["Посмотри на верхний слой","Сверху оставили два угловых кубика. Вынули 9 − 2 = 7 кубиков."]],""],[822,104,"В кошельке у Сергея три монеты: 5 рублей, 2 рубля и 1 рубль. Какую сумму он не сможет заплатить без сдачи?",{"0":[53.7,68.9,31.3,27.2],"1":[191.7,68.9,31.3,27.2],"2":[331.6,68.9,32.7,27.2],"3":[484.8,68.9,32.6,27.2],"4":[638.1,68.9,31.3,27.2]},"B","Монеты без сдачи",[["Отложи пятирублёвую монету","С ней получится заплатить не меньше 5 рублей, поэтому для 4 рублей она не годится."],["Сложи мелкие монеты","Вместе монеты в 1 и 2 рубля дают только 3 рубля. Четыре рубля заплатить нельзя. Остальные суммы из вариантов можно собрать как 2 + 1, 5 + 1, 5 + 2 и 5 + 2 + 1."]],""],[822,200,"Кенгуру прошел через лабиринт, в котором один вход и пять выходов. Его маршрут проходил только по треугольным комнатам. Где он вышел?",{"0":[53.7,123.0,31.3,27.2],"1":[211.6,123.0,31.3,27.2],"2":[358.2,123.0,32.7,27.2],"3":[53.7,152.3,32.6,27.2],"4":[211.6,152.3,31.3,27.2]},"E","Треугольный лабиринт",[["Выбери первый проход","Из комнаты у входа бери верхний проход. Нижний ведёт в комнату с пятью сторонами. Через следующий верхний проход поднимись к треугольникам вдоль верхней границы."],["Иди по треугольникам","Следуй вправо через два треугольника у верхней границы, между ними проходя через маленький треугольник под ней. Затем спускайся через треугольники справа от середины схемы."],["Найди выход","Из большого треугольника внизу справа перейди в узкий треугольник у правой стенки. Его внешний проход ведёт к выходу 5."]],""],[822,138,"У Кати вчера был день рождения. Завтра будет пятница. В какой день недели был день рождения Кати?",{"0":[53.7,68.9,31.3,27.2],"1":[311.6,68.9,31.4,27.2],"2":[558.0,68.9,32.7,27.2],"3":[53.7,103.0,32.7,27.2],"4":[311.6,103.0,31.4,27.2]},"B","День рождения Кати",[["Определи сегодняшний день","Завтра пятница, значит, сегодня четверг."],["Отсчитай один день назад","Вчера была среда. На среду пришёлся день рождения Кати."]],""],[822,184,"Шесть городов соединены автобусными маршрутами. Стоимость проезда между этими городами указана на схеме. За какую наименьшую сумму можно проехать из города А в город В?",{"0":[53.7,150.0,31.3,27.2],"1":[158.4,150.0,31.3,27.2],"2":[265.0,150.0,32.6,27.2],"3":[371.6,150.0,32.6,27.2],"4":[478.1,150.0,31.3,27.2]},"C","Самый дешёвый маршрут",[["Найди первые пересадки","За 20 от А можно попасть в ближайший верхний город, а ещё за 10 — в следующий верхний. Оттуда до нижнего левого города ещё 30. Это 60 от А, дешевле прямого переезда за 80."],["Дойди до В","По низу остаётся заплатить 20 и 10. Весь путь стоит 20 + 10 + 30 + 20 + 10 = 90."],["Проверь другие подъезды","Последний переезд в В стоит 70 сверху или 10 снизу. До верхнего города нужно хотя бы 30, значит, сверху вышло бы не меньше 100. До нижнего правого города можно доехать за 60 + 20 = 80 через нижний левый или как минимум за 30 + 60 = 90 сверху."]],""],[843,137,"Если уменьшаемое уменьшить на 1, а из вычитаемого вычесть 1, то разность",{"0":[53.8,68.9,31.3,27.2],"1":[298.2,68.9,31.3,27.2],"2":[544.8,68.9,32.7,27.2],"3":[53.8,103.0,32.7,27.2],"4":[298.2,103.0,31.3,27.2]},"A","Оба числа уменьшились",[["Представь числа на линейке","Разность показывает, на сколько одно число больше другого. Сдвинь обе отметки на один шаг влево."],["Сравни расстояние","Обе отметки сдвинулись одинаково, поэтому расстояние между ними не изменилось. Разность осталась прежней."]],""],[843,212,"Коля играет на компьютере каждый день по 40 минут, а Вася – по 5 часов в неделю (больше родители не разрешают). Кому из мальчиков за неделю удается больше времени поиграть на компьютере и на сколько?",{"0":[53.8,118.2,31.3,27.2],"1":[411.5,118.2,31.4,27.2],"2":[53.7,147.5,32.7,27.2],"3":[411.5,147.5,32.7,27.2],"4":[53.7,176.9,31.4,27.2]},"B","Время за компьютером",[["Переведи всё в минуты","За семь дней Коля играет 7 × 40 = 280 минут. Вася играет 5 × 60 = 300 минут."],["Сравни результаты","300 − 280 = 20. Вася играет на 20 минут больше."]],""],[843,203,"На каком из квадратиков закрашена ровно одна треть клеточек?",{"0":[53.7,168.9,31.3,27.2],"1":[204.9,168.9,31.4,27.2],"2":[358.2,168.9,32.6,27.2],"3":[504.8,168.9,32.7,27.2],"4":[657.9,168.9,31.4,27.2]},"C","Треть квадрата",[["Найди одну треть","В каждом квадратике 3 × 3 = 9 клеток. Одна треть — это 9 : 3 = 3 клетки."],["Посчитай закрашенные клетки","В C закрашены две левые клетки сверху и одна правая снизу. В остальных квадратиках закрашенных клеток больше трёх."]],""],[843,101,"Петя прибавляет различные однозначные числа к числу 96. Сколько раз он получит трехзначное число?",{"0":[53.7,66.5,31.3,27.2],"1":[211.6,66.5,31.3,27.2],"2":[358.2,66.5,32.7,27.2],"3":[504.8,66.5,32.6,27.2],"4":[651.3,66.5,31.3,27.2]},"D","От 96 до 100",[["Найди первое трёхзначное число","Наименьшее трёхзначное число — 100. До него от 96 не хватает 4."],["Перебери подходящие слагаемые","Подходят однозначные числа 4, 5, 6, 7, 8 и 9. Это шесть разных случаев."]],""],[843,131,"На левой стороне улицы находятся дома с нечетными номерами от 1 до 19, а на правой стороне – дома с четными номерами от 2 до 14. Сколько домов на этой улице?",{"0":[53.7,95.9,31.3,27.2],"1":[211.6,95.9,31.3,27.2],"2":[358.2,95.9,32.6,27.2],"3":[504.8,95.9,32.6,27.2],"4":[651.3,95.9,31.3,27.2]},"B","Дома по обе стороны",[["Сосчитай нечётные номера","Слева номера идут от 1 до 19 через один. Номера 1, 3, 5, …, 19 дают десять домов."],["Сосчитай чётные номера","Справа идут 2, 4, 6, …, 14. Это семь домов. Всего 10 + 7 = 17."]],""],[843,157,"За квадратный столик могут сесть одновременно 4 гнома, по одному с каждой стороны. Для вечеринки 7 таких столиков составили в ряд (вплотную один к другому). Сколько гномов могут сесть за получившийся длинный стол?",{"0":[53.7,122.9,31.3,27.2],"1":[211.6,122.9,31.3,27.2],"2":[358.2,122.9,32.6,27.2],"3":[504.8,122.9,32.6,27.2],"4":[651.3,122.9,31.3,27.2]},"B","Длинный стол гномов",[["Посчитай места по длинным сторонам","Семь квадратных столиков в ряд образуют длинный прямоугольник. На каждой длинной стороне помещаются семь гномов."],["Добавь два торца","На каждом торце остаётся по одному месту, а у внутренних стыков мест нет. Всего 7 + 7 + 1 + 1 = 16."]],""],[843,157,"Самое маленькое число, которое можно получить, выкладывая в ряд карточки, изображенные справа, равно",{},"D","Наименьшее число из карточек",[["Выбери начало","Самое маленькое число должно начинаться с самой маленькой доступной цифры. Сначала клади карточку 2, затем 309. Теперь наименьшая первая цифра среди оставшихся — 4 на карточке 41."],["Продолжи тем же способом","Дальше идут карточки 5, 68 и 7. Цифры внутри каждой карточки идут вместе, поэтому получается 2 309 415 687."]],""],[822,130,"На стеклянной двери написано: «КЕНГУРУ ПРИГЛАШАЕТ ДРУЗЕЙ». Сколько из этих 23 букв выглядят одинаково с той и с другой стороны двери?",{"0":[53.7,96.0,31.3,27.2],"1":[211.6,96.0,31.3,27.2],"2":[358.2,96.0,32.6,27.2],"3":[504.8,96.0,32.6,27.2],"4":[651.2,96.0,31.3,27.2]},"C","Буквы на стекле",[["Представь зеркальное отражение","С другой стороны двери левое и правое в каждой букве поменяются местами. Одинаково выглядят буквы, у которых левая и правая половины зеркально совпадают."],["Посчитай симметричные буквы","В надписи это Н в слове КЕНГУРУ, П, Л, А, Ш, А, Т в слове ПРИГЛАШАЕТ и Д в слове ДРУЗЕЙ. Всего 1 + 6 + 1 = 8."]],""],[822,158,"Вороны Дана, Нана, Лана и Зана сидят на заборе. Дана сидит посредине между Наной и Ланой. Расстояние между Наной и Даной такое же, как между Ланой и Заной. Между Даной и Заной расстояние 4 метра. Какое расстояние между Наной и Заной?",{"0":[53.7,122.9,31.3,27.2],"1":[211.6,122.9,31.3,27.2],"2":[358.1,122.9,32.7,27.2],"3":[504.8,122.9,32.6,27.2],"4":[651.3,122.9,31.3,27.2]},"B","Вороны на заборе",[["Найди три равных промежутка","От Наны до Даны столько же, сколько от Даны до Ланы. От Ланы до Заны — ещё один такой же промежуток. Зана сидит по другую сторону от Ланы, чем Дана, иначе она оказалась бы на месте Даны."],["Восстанови длину одного промежутка","Между Даной и Заной два промежутка общей длиной 4 м. Один равен 2 м, а между Наной и Заной три таких промежутка, всего 6 м."]],""],[822,157,"Ваня стреляет в тире. Он заплатил за 10 выстрелов. За каждое попадание в мишень Ваня получает право на два дополнительных выстрела. Ему удалось сделать 20 выстрелов. Сколько раз Ваня попал в мишень?",{"0":[53.7,123.0,31.3,27.2],"1":[211.6,123.0,31.3,27.2],"2":[358.1,123.0,32.7,27.2],"3":[504.8,123.0,32.6,27.2],"4":[651.3,123.0,31.3,27.2]},"D","Попадания в тире",[["Найди число дополнительных выстрелов","Из двадцати выстрелов десять были оплачены. За попадания Ваня получил ещё 20 − 10 = 10 выстрелов."],["Раздели на пары","За каждое попадание дают два выстрела. Значит, попаданий было 10 : 2 = 5."]],""],[822,76,"Сколько получится, если 2 десятка умножить на 5 десятков?",{"0":[53.7,41.9,31.3,27.2],"1":[158.3,41.9,31.3,27.2],"2":[265.0,41.9,32.7,27.2],"3":[478.1,41.9,32.6,27.2],"4":[631.3,41.9,31.3,27.2]},"E","Произведение десятков",[["Запиши числа","Два десятка — это 20, а пять десятков — 50."],["Выполни умножение","20 × 50 = 1000. В тысяче десять сотен."]],""],[822,267,"У Глаши есть набор фигурок, белых с одной стороны и цветных – с другой. Глаша сложила из своих фигурок прямоугольник так, как изображено на рисунке. Какая из фигурок",{},"C","Фигурка со стороны цвета",[["Найди четыре детали","A после поворота лежит слева от центра, B — сверху ближе к середине и ещё раз справа от центра. D — крест в середине, а E после полуоборота находится вдоль левого края ниже середины."],["Проверь оставшийся силуэт","Слева внизу есть ступенька из пяти клеток, похожая на C. Все повороты C дают ступеньку другой формы. Чтобы она совпала, её пришлось бы перевернуть на цветную сторону. Среди белых деталей C нет."]],""],[822,138,"Если в некотором месяце 5 суббот, то в этом месяце не может быть",{"0":[53.7,68.9,31.3,27.2],"1":[311.6,68.9,31.3,27.2],"2":[558.0,68.9,32.7,27.2],"3":[53.7,103.0,32.6,27.2],"4":[311.6,103.0,31.3,27.2]},"A","Пять суббот",[["Отдели четыре недели","В каждом месяце есть четыре полные недели, то есть 28 дней. Остаётся не больше трёх дней подряд. Только дни недели из этого остатка встречаются пять раз."],["Сравни субботу со вторником","Суббота и вторник не помещаются в отрезок из трёх дней подряд. Даже если начать с субботы, вторник будет четвёртым днём. Поэтому пяти вторников быть не может."]],""],[822,130,"Электронные часы показывают часы и минуты (от 00:00 до 23:59). Сколько раз за сутки в наборе цифр на табло этих часов участвуют только цифры 2 и 5 (или одна из этих цифр)?",{"0":[53.7,96.0,31.3,27.2],"1":[211.6,96.0,31.3,27.2],"2":[358.2,96.0,32.7,27.2],"3":[504.8,96.0,32.6,27.2],"4":[651.3,96.0,31.3,27.2]},"C","Цифры на электронных часах",[["Выбери часы","На табло часы от 00 до 23. Из двоек и пятёрок можно записать только 22 в этих пределах."],["Выбери минуты","В первом и втором разрядах минут можно независимо поставить 2 или 5. Получаются 22:22, 22:25, 22:52 и 22:55. Всего четыре раза."]],""],[843,197,"Антон и Миша считают деревья, растущие вокруг пруда. Они двигаются в одном направлении, но начинают счет с разных деревьев. То дерево, которое Миша назвал двадцатым, для Антона оказалось четвертым, а дерево, которое Миша назвал десятым, для Антона оказалось сорок шестым. Сколько деревьев растет вокруг пруда?",{"0":[53.7,163.0,31.3,27.2],"1":[211.6,163.0,31.3,27.2],"2":[358.2,163.0,32.7,27.2],"3":[504.8,163.0,32.6,27.2],"4":[651.3,163.0,31.3,27.2]},"B","Деревья вокруг пруда",[["Сравни два отмеченных дерева","Миша от десятого дерева до двадцатого насчитал 10 шагов между деревьями. Для Антона это путь от 46-го дерева до 4-го через начало круга."],["Замкни круг","От первого дерева Антона до 4-го три шага. От 46-го дерева до первого остаётся 10 − 3 = 7 шагов. От первого до 46-го — 45 шагов. Во всём круге 45 + 7 = 52 дерева."]],""],[843,209,"На каждой из 7 карточек на верхнем рисунке написано по две буквы. На нижнем рисунке – те же карточки, но в другом порядке. Какое «слово» могло получиться внизу?",{"0":[53.7,145.2,31.3,27.2],"1":[278.2,145.2,31.4,27.2],"2":[53.7,174.6,32.7,27.2],"3":[278.2,174.6,32.7,27.2],"4":[544.7,174.6,31.3,27.2]},"D","Буквы на карточках",[["Сохрани пары","У каждой карточки при перестановке сохраняются обе буквы. Для верхней К снизу может стоять К или У, для О — Е, Г или Р, для Л — Н или У."],["Собери нижнюю строку","Для нижней надписи из D бери по порядку пары Л–У, О–Г, К–У, О–Р, Л–Н, О–Е и К–К. Все семь исходных карточек использованы по одному разу. Читается УГУРНЕК."]],""],[843,219,"Если лягушонок зеленый, то он веселый. Если лягушонок не веселый, то он сидит на берегу. Все лягушата либо зеленые, либо пестренькие. Если лягушонок пестренький, то он плавает в воде. Тогда обязательно",{"0":[53.7,120.6,31.4,27.2],"1":[431.5,120.6,31.4,27.2],"2":[53.7,152.3,32.7,27.2],"3":[431.5,152.3,32.7,27.2],"4":[53.7,184.0,31.4,27.2]},"C","Весёлые лягушата",[["Проверь зелёных","По условию любой зелёный лягушонок весёлый."],["Проверь пёстрых","Пёстрый лягушонок плавает в воде. Если бы он был невесёлым, то сидел бы на берегу. Значит, пёстрый тоже весёлый, а вместе это все лягушата."]],""],[843,191,"Кенгуру Попрыгун проснулся под пальмой и стал радостно скакать по дорожке, иногда меняя направление прыжков. Длина каждого его прыжка либо 2 метра, либо 4 метра, либо 7 метров. На каком расстоянии от пальмы он не мог оказаться после 10 прыжков?",{},"E","Десять прыжков",[["Получи 3 м и 49 м","Для 3 м сделай прыжок на 7 м от пальмы и на 4 м обратно, а ещё четыре пары прыжков по 2 м туда и обратно. Для 49 м прыгни семь раз по 7 м, затем на 2 м, ещё на 2 м и на 4 м обратно."],["Получи 61 м и 62 м","Девять прыжков по 7 м вперёд и один на 2 м назад дадут 61 м. Восемь прыжков по 7 м, один на 4 м и один на 2 м вперёд дадут 62 м. Для каждого расстояния получилось ровно 10 прыжков."]],""],[843,156,"",{},"C","Треугольники в треугольнике",[["Начни с крупных фигур","Есть один самый большой треугольник. Он разделён на четыре треугольника вдвое меньшего размера: три в углах и один перевёрнутый посередине."],["Посчитай следующие размеры","Каждый из трёх угловых треугольников разделён ещё на четыре, это 12 треугольников. Самый верхний из них снова разделён на четыре маленьких."],["Сложи результаты","По размерам получилось 1, 4, 12 и 4. Всего 1 + 4 + 12 + 4 = 21 треугольник."]],""],[843,128,"В ребусе КЕН × Г = УРУ одинаковыми буквами зашифрованы одинаковые цифры, а разными – разные. Если К равно 2, то У равно",{"0":[53.7,93.8,31.3,27.2],"1":[211.6,93.8,31.3,27.2],"2":[358.1,93.8,32.7,27.2],"3":[504.8,93.8,32.6,27.2],"4":[651.3,93.8,31.3,27.2]},"D","КЕН умножить на Г",[["Ограничь множитель","КЕН лежит между 200 и 299. При множителе 5 или больше ответ был бы четырёхзначным. Множитель 0 не годится, 1 дал бы У = К, а 2 уже занята буквой К. Остаются 3 и 4."],["Проверь умножение на 3","При множителе 3 первая и последняя цифры ответа могут быть 6, 7 или 8. При У = 6 последняя цифра КЕН — 2, уже занятая буквой К. При У = 7 кандидаты 239, 249 и 259 дают 717, 747 и 777, в каждом случае разные буквы получают одинаковую цифру. При У = 8 так же отпадают 276, 286 и 296 с ответами 828, 858 и 888."],["Проверь умножение на 4","Произведение трёхзначное и не меньше 800. Оно чётное, поэтому из 8 и 9 для У подходит только 8. Ребус действительно складывается: 217 × 4 = 868."]],""]]],[2007,"3–4 классы",[[825,72,"Сколько общих букв у слов КЕНГУРУ и МАТЕМАТИКА?",{"0":[47.2,41.1,31.3,23.5],"1":[198.4,41.1,31.3,23.5],"2":[351.6,41.1,32.6,23.5],"3":[504.9,41.1,32.6,23.5],"4":[651.3,41.1,31.3,23.5]},"B","Общие буквы",[["Сравни буквы","В слове «КЕНГУРУ» есть буквы К, Е, Н, Г, У и Р. Найди каждую из них в слове «МАТЕМАТИКА»."],["Посчитай совпадения","В обоих словах встречаются К и Е. Всего 2 общие буквы."]],""],[825,177,"Какая фигурка содержит больше всего клеточек?",{"0":[47.2,41.1,31.3,23.5],"1":[188.5,41.1,31.3,23.5],"2":[338.3,41.1,32.6,23.5],"3":[488.1,41.1,32.6,23.5],"4":[638.0,41.1,31.3,23.5]},"C","Фигурки из клеток",[["Считай по рядам","У всех фигурок по 6 горизонтальных рядов. Например, у C сверху вниз 1, 4, 1, 2, 3 и 4 клетки. В сумме это 15."],["Сравни итоги","У A 13 клеток, у B, D и E по 14. Значит, больше всего клеток у C."]],""],[825,97,"На календаре 2007 год. Сумма цифр этого числа равна 9. Через сколько лет повторится такая же сумма цифр?",{"0":[47.2,65.8,31.4,23.5],"1":[198.4,65.8,31.4,23.5],"2":[351.6,65.8,32.7,23.5],"3":[504.9,65.8,32.7,23.5],"4":[651.4,65.8,31.4,23.5]},"D","Цифры на календаре",[["Проверь конец десятилетия","В 2008 и 2009 суммы цифр равны 10 и 11."],["Найди первый подходящий год","У 2010 сумма цифр равна 3, затем она растёт на 1 каждый год. В 2016 она равна 2 + 0 + 1 + 6 = 9. С 2007 прошло 9 лет."]],""],[825,210,"Какие две маски одинаковые?",{"0":[47.2,178.6,31.4,23.5],"1":[198.4,178.6,31.4,23.5],"2":[351.6,178.6,32.7,23.5],"3":[504.9,178.6,32.7,23.5],"4":[651.4,178.6,31.4,23.5]},"E","Две одинаковые маски",[["Сравни рты","Маски 2 и 4 хмурятся, а маски 1, 3 и 5 улыбаются."],["Сравни щёки","У 2 и 4 чёрточки на щеках выгнуты по-разному. У 3 чёрточки выгнуты в другую сторону, чем у 1 и 5. Маски 1 и 5 совпадают целиком."]],""],[825,186,"",{"0":[47.2,36.4,31.4,23.5],"1":[47.2,65.8,31.3,23.5],"2":[47.2,95.2,32.7,23.5],"3":[47.2,124.6,32.7,23.5],"4":[47.2,153.9,31.3,23.5]},"D","Что отличается от пяти",[["Посчитай буквы","Слово «ПЯТЬ» состоит из букв П, Я, Т и Ь. Их четыре."],["Проверь остальные ответы","Лучшая оценка, два собачьих носа и три кошачьих, номер задачи и половина от 10 дают по 5."]],""],[825,137,"Цифры 0, 3 и 7 написаны на трех карточках. Сколько различных трехзначных чисел можно составить из этих карточек?",{"0":[47.2,105.3,31.3,23.5],"1":[198.4,105.3,31.3,23.5],"2":[351.6,105.3,32.6,23.5],"3":[504.9,105.3,32.6,23.5],"4":[651.3,105.3,31.3,23.5]},"C","Трёхзначные числа из карточек",[["Выбери первую цифру","Ноль нельзя поставить первым. Число может начинаться с 3 или с 7."],["Переставь оставшиеся карточки","С тройки начинаются 307 и 370, с семёрки — 703 и 730. Получается 4 числа."]],""],[857,73,"",{"0":[53.7,41.3,31.3,23.5],"1":[204.9,41.3,31.3,23.5],"2":[358.0,41.3,32.7,23.5],"3":[511.4,41.3,32.7,23.5],"4":[657.9,41.3,31.3,23.5]},"B","Сначала умножение",[["Выполни умножения","В начале и в конце записи стоит 2 × 2. Каждое произведение равно 4."],["Сложи результаты","Между произведениями стоят четыре двойки. Получаем 4 + 2 + 2 + 2 + 2 + 4 = 16."]],""],[857,215,"Справа нарисована фигурка, состоящая из клеточек. Что нельзя вырезать из этой фигурки?",{"0":[66.8,183.3,31.3,23.5],"1":[191.0,183.3,31.3,23.5],"2":[304.7,183.3,32.7,23.5],"3":[424.7,183.3,32.7,23.5],"4":[537.9,183.3,31.3,23.5]},"A","Вырезание фигурок",[["Примерь четыре фигурки","У B и E верхний ряд из трёх клеток ложится на второй ряд исходной фигуры. C начинается в её втором ряду и идёт вниз по столбику. Для D годятся верхний и нижний ряды целиком и соединяющий их столбик."],["Проверь крест в A","Перекрестие A можно поместить только на среднюю клетку второго ряда. Его длинная ножка из двух клеток помещается лишь вниз. Там у конца ножки нет соседней клетки сбоку, нужной для A."]],""],[857,72,"Сколько нулей в записи числа миллион плюс тысяча плюс один?",{"0":[53.7,41.2,31.3,23.5],"1":[204.9,41.2,31.3,23.5],"2":[371.5,41.2,32.6,23.5],"3":[511.4,41.2,32.6,23.5],"4":[644.6,41.2,31.3,23.5]},"C","Нули в большом числе",[["Запиши слагаемые","Миллион — это 1 000 000, тысяча — 1 000, а единица — 1."],["Сложи и проверь запись","Получаем 1 001 001. В нём две пары нулей, всего 4 нуля."]],""],[857,178,"Вес Васи – 21 кг. Когда он встал на весы, взяв на руки кота Тошу, весы показали 29 кг 500 г. С котенком Малышом на руках Вася весит 22 кг. Что покажут весы, если на них усадить Тошу и Малыша вместе?",{"0":[53.7,117.4,31.4,23.5],"1":[284.9,117.4,31.4,23.5],"2":[511.4,117.4,32.7,23.5],"3":[53.7,146.8,32.7,23.5],"4":[284.9,146.8,31.4,23.5]},"D","Два кота на весах",[["Убери вес Васи","Тоша весит 29 кг 500 г − 21 кг = 8 кг 500 г. Малыш весит 22 кг − 21 кг = 1 кг."],["Сложи веса котов","Вместе коты весят 9 кг 500 г."]],""],[857,206,"В каждую клетку квадрата 3 × 3 надо вписать одну из цифр 1, 2 или 3. Каждая цифра должна встречаться в каждой строчке и в каждом столбце. Три клетки уже заполнены. Какую цифру можно поставить вместо вопросительного знака?",{"0":[53.7,145.1,31.3,23.5],"1":[271.4,145.1,31.3,23.5],"2":[484.5,145.1,32.7,23.5],"3":[53.7,174.5,32.7,23.5],"4":[271.5,174.5,31.4,23.5]},"C","Квадрат с тремя цифрами",[["Заполни первый столбец","В первом столбце уже есть 1 и 2, поэтому в нижней строке там стоит 3."],["Заполни второй столбец","В нижней клетке второго столбца не может быть 3, потому что она уже есть в нижней строке. Не может быть и 1, которая уже есть в столбце. Значит, внизу стоит 2, а вместо вопросительного знака — 3."]],""],[857,153,"Ваня старше Пети на 3 года и 1 день. Ваня родился 1 января 1997 года. Когда родился Петя?",{"0":[53.7,63.4,31.4,23.5],"1":[444.8,63.4,31.4,23.5],"2":[53.7,92.8,32.7,23.5],"3":[444.7,92.8,32.7,23.5],"4":[53.7,122.2,31.4,23.5]},"A","День рождения Пети",[["Отложи три года","Петя младше Вани, поэтому Петя родился позже. Через 3 года после 1 января 1997 года наступило 1 января 2000 года."],["Прибавь день","Прибавляем ещё один день. Получаем 2 января 2000 года."]],""],[857,124,"Вера разрезала квадратный листок бумаги со стороной 5 см на два прямоугольника. Периметр одного из этих прямоугольников равен 16 см. Чему равен периметр другого?",{"0":[53.7,92.8,31.3,23.5],"1":[204.9,92.8,31.3,23.5],"2":[358.2,92.8,32.7,23.5],"3":[511.5,92.8,32.7,23.5],"4":[657.9,92.8,31.3,23.5]},"D","Два прямоугольника",[["Найди ширину первого","У обоих прямоугольников одна сторона равна 5 см. Половина периметра первого равна 16 ÷ 2 = 8 см, значит, его вторая сторона равна 8 − 5 = 3 см."],["Вычисли второй периметр","У второго прямоугольника вторая сторона равна 5 − 3 = 2 см. Его периметр равен 2 × (5 + 2) = 14 см."]],""],[836,98,"На ферме у Яна живут куры и свиньи, причем тех и других поровну. Сколько ног может быть у всех этих животных вместе?",{"0":[53.7,65.8,31.3,23.5],"1":[204.9,65.8,31.3,23.5],"2":[358.0,65.8,32.7,23.5],"3":[511.4,65.8,32.7,23.5],"4":[657.8,65.8,31.3,23.5]},"D","Курицы и свиньи",[["Составь пары","Кур и свиней поровну, поэтому их можно объединить в пары из одной курицы и одной свиньи. В каждой паре 2 + 4 = 6 ног."],["Найди подходящее число","Общее число ног делится на 6. Из предложенных чисел подходит только 48 = 8 × 6."]],""],[836,152,"Муравьишка ехал верхом на Гусенице 24 минуты, а потом пересел на Жука и проехал на нем в 4 раза больший путь. Сколько минут он ехал на Жуке, если Жук передвигается в 8 раз быстрее Гусеницы?",{"0":[53.7,119.9,31.3,23.5],"1":[204.9,119.9,31.3,23.5],"2":[358.1,119.9,32.6,23.5],"3":[511.4,119.9,32.6,23.5],"4":[657.8,119.9,31.3,23.5]},"C","Муравей меняет транспорт",[["Сравни пути за минуту","За минуту жук проходит столько же, сколько гусеница за 8 минут. Значит, путь гусеницы за 24 минуты жук проехал бы за 24 ÷ 8 = 3 минуты."],["Увеличь путь в четыре раза","На жуке муравей проехал путь в 4 раза длиннее. На это ушло 3 × 4 = 12 минут."]],""],[836,127,"Степа учится в школе. Если цифры в его возрасте поменять местами, то получится возраст его дедушки, которому больше 60 лет, но меньше 70. На сколько лет Степа моложе дедушки?",{"0":[53.7,95.1,31.3,23.5],"1":[204.9,95.1,31.3,23.5],"2":[358.0,95.1,32.7,23.5],"3":[511.4,95.1,32.7,23.5],"4":[657.8,95.1,31.3,23.5]},"D","Возраст Стёпы и дедушки",[["Восстанови переставленные цифры","У дедушки в разряде десятков стоит 6, значит, возраст Стёпы заканчивается на 6. Стёпа ходит в школу, а его возраст двузначный, поэтому ему 16 лет."],["Найди разность","Дедушке 61 год. Стёпа моложе на 61 − 16 = 45 лет."]],""],[836,129,"Две квадратные салфетки 9 см × 9 см лежат на столе так, что получается прямоугольник 9 см × 13 см. Какая площадь покрыта в два слоя?",{"0":[53.7,97.1,31.4,23.5],"1":[204.9,97.1,31.4,23.5],"2":[358.2,97.1,32.7,23.5],"3":[511.5,97.1,32.7,23.5],"4":[658.0,97.1,31.4,23.5]},"B","Салфетки внахлёст",[["Найди ширину нахлёста","Две салфетки в ряд без нахлёста дали бы длину 9 + 9 = 18 см. Получилось 13 см, значит, салфетки перекрываются на 18 − 13 = 5 см."],["Найди площадь","Полоса перекрытия имеет размеры 5 см на 9 см. Её площадь 5 × 9 = 45 см²."]],""],[836,153,"Роман, Федя, Лиза, Катя и Андрей пришли на занятие кружка. Роман пришел позже Лизы, Федя раньше Романа и сразу за Катей. Катя пришла раньше Лизы, но не была первой. Кто из ребят пришел на занятие третьим?",{"0":[53.7,122.2,31.3,23.5],"1":[204.8,122.2,31.3,23.5],"2":[357.9,122.2,32.7,23.5],"3":[511.3,122.2,32.7,23.5],"4":[657.8,122.2,31.3,23.5]},"E","Кто пришёл третьим",[["Расставь Катю и Федю","Катя пришла раньше Лизы, а Роман — после Лизы. Федя пришёл сразу после Кати, поэтому он тоже пришёл раньше Лизы."],["Найди первое и третье места","Катя пришла раньше всех, кроме Андрея. Она не первая, значит, Андрей первый, Катя вторая, а Федя третий."]],""],[836,299,"Квадратный лист бумаги сложили пополам, затем еще раз пополам и от полученного квадратика отрезали маленький уголок. Затем лист бумаги развернули. Что не могло получиться?",{"0":[53.7,238.5,31.3,23.5],"1":[251.5,238.5,31.3,23.5],"2":[418.1,238.5,32.6,23.5],"3":[584.6,238.5,32.6,23.5],"4":[53.7,267.8,31.3,23.5]},"B","Срезанный угол",[["Разверни три вида срезов","У сложенного квадратика есть угол без сгибов, два угла на одном сгибе и угол на пересечении сгибов. Они дают соответственно четыре срезанных угла, две выемки на противоположных сторонах или отверстие в центре."],["Проверь рисунок B","На B одновременно срезаны внешние углы и сделаны выемки по краям. Один срез сложенного уголка такого рисунка не даст."]],""],[836,145,"В 1-а классе учится 36 ребят. Половина из них − мальчики. Ровно треть учеников этого класса еще не научилась выговаривать букву Р. Известно, что ровно 14 девочек уже говорят эту букву правильно. Сколько мальчиков выговаривают Р правильно?",{"0":[53.7,119.9,31.3,23.5],"1":[204.9,119.9,31.3,23.5],"2":[358.1,119.9,32.6,23.5],"3":[511.4,119.9,32.6,23.5],"4":[657.8,119.9,31.3,23.5]},"C","Буква Р",[["Посчитай тех, кто говорит Р","Треть класса составляет 36 ÷ 3 = 12 учеников. Значит, Р выговаривают 36 − 12 = 24 ученика."],["Вычти девочек","Среди этих 24 учеников 14 девочек. Мальчиков 24 − 14 = 10."]],""],[852,123,"Маша разделила восемь чисел 1, 2, 3, 4, 5, 6, 7, 8 на две четверки с равными суммами. При этом числа 1 и 3 оказались в одной четверке. Тогда в ней же оказалось и число",{"0":[53.7,92.1,31.3,23.5],"1":[204.9,92.1,31.3,23.5],"2":[358.1,92.1,32.6,23.5],"3":[511.4,92.1,32.6,23.5],"4":[657.8,92.1,31.3,23.5]},"D","Четвёрка с числами 1 и 3",[["Найди сумму четвёрки","Сумма чисел от 1 до 8 равна 36. У каждой четвёрки сумма 18."],["Подбери ещё два числа","Числа 1 и 3 дают 4, значит, два остальных дают 14. Подходит только пара различных чисел 6 и 8. Из предложенных ответов есть 6."]],""],[852,100,"В любом месяце есть 4 субботы, но в некоторых месяцах суббот больше. Какое наибольшее число таких месяцев может быть в году?",{"0":[53.7,68.1,31.3,23.5],"1":[204.9,68.1,31.3,23.5],"2":[358.1,68.1,32.6,23.5],"3":[518.0,68.1,32.6,23.5],"4":[657.9,68.1,31.3,23.5]},"E","Месяцы с пятью субботами",[["Отдели первые четыре субботы","В каждом из 12 месяцев по меньшей мере 4 субботы. Это 12 × 4 = 48 суббот. В месяце бывает не больше пяти суббот, потому что от первой до шестой прошло бы 35 дней."],["Найди максимум за год","В году 52 полные недели и ещё день или два. Если год начинается в субботу, её можно встретить 53 раза. Тогда пятая суббота будет в 53 − 48 = 5 месяцах."]],""],[852,239,"Общее количество точек на противоположных гранях игрального кубика равно 7. Четыре одинаковых игральных кубика сложили вместе и закрасили некоторые грани. Сколько точек было на грани, отмеченной знаком ∗, если кубики приложены друг к другу по одинаковым граням?",{"0":[53.7,208.0,31.3,23.5],"1":[164.9,208.0,31.3,23.5],"2":[278.1,208.0,32.6,23.5],"3":[391.4,208.0,32.6,23.5],"4":[498.0,208.0,31.3,23.5]},"A","Четыре игральных кубика",[["Определи заднюю грань переднего левого кубика","На его передней грани 1 точка, значит, на задней 6. Кубики соприкасаются одинаковыми гранями, поэтому у заднего левого кубика впереди 6 точек."],["Восстанови положение по правой грани","На внешней правой грани заднего правого кубика 4 точки, поэтому на его левой грани 3. Значит, и у кубика со звёздочкой справа 3. Посмотри на передний правый кубик. У него 3 справа, 6 сверху и 5 сзади. Поверни его так, чтобы справа осталась 3, а 6 оказалась спереди. Тогда 5 оказывается сверху, на месте звёздочки."]],""],[852,185,"Три сестры Анна, Ева и Лиза одинаково быстро и хорошо умеют навести порядок в квартире. Если любые две из этих девочек будут работать вместе, то справятся с уборкой за час. Сколько времени они потратят на уборку, если будут работать все трое вместе?",{"0":[53.7,122.2,31.3,23.5],"1":[284.9,122.2,31.3,23.5],"2":[511.4,122.2,32.7,23.5],"3":[53.7,154.0,32.7,23.5],"4":[284.9,154.0,31.3,23.5]},"C","Сёстры убирают квартиру",[["Найди долю каждой сестры","Две сестры за 60 минут убирают всю квартиру. Значит, каждая за час убирает половину квартиры."],["Раздели работу на троих","Одной сестре на всю квартиру нужно 120 минут. Если три сестры делают одинаковые части, каждая уберёт свою часть за 120 ÷ 3 = 40 минут."]],""],[852,127,"В примере на умножение КЕН × ГА = 7 632 использованы все цифры от 1 до 9, каждая по одному разу. Какую цифру заменяет буква Г?",{"0":[53.7,95.4,30.5,23.5],"1":[204.9,95.4,31.3,23.5],"2":[358.1,95.4,32.6,23.5],"3":[511.4,95.4,32.6,23.5],"4":[657.9,95.4,31.3,23.5]},"B","Цифры в произведении",[["Оставь возможные множители","Для КЕН и ГА остаются только цифры 1, 4, 5, 8 и 9. Чтобы произведение оканчивалось на 2, последние цифры множителей должны быть 4 и 8 или 8 и 9 в любом порядке."],["Проверь делимость","Число 7 632 раскладывается как 2 × 2 × 2 × 2 × 3 × 3 × 53. Его двузначные делители с трёхзначным частным — 12, 16, 18, 24, 36, 48, 53 и 72. Из них только 18 и 48 составлены из оставшихся цифр."],["Проверь все цифры","7 632 ÷ 18 = 424, а в нём повторяется 4. Зато 159 × 48 = 7 632 использует все девять цифр по одному разу. Буква Г стоит на месте десятков числа 48, так что Г = 4."]],""],[852,158,"Электронные часы показывают часы и минуты, от 00:00 до 23:59. Сколько времени в течение суток на табло этих часов присутствует хотя бы одна цифра 2?",{"0":[53.7,95.2,31.4,23.5],"1":[311.5,95.2,31.4,23.5],"2":[544.7,95.2,32.7,23.5],"3":[53.7,126.9,32.7,23.5],"4":[311.5,126.9,31.3,23.5]},"D","Двойка на часах",[["Посчитай целые часы","В записях 02, 12, 20, 21, 22 и 23 уже есть двойка. Это 6 целых часов."],["Посчитай минуты в остальных часах","В каждом из 18 остальных часов двойка есть в 10 минутах с 20-й по 29-ю и ещё в минутах 02, 12, 32, 42, 52. Итого 18 × 15 = 270 минут, или 4 часа 30 минут."],["Сложи результаты","6 часов и 4 часа 30 минут дают 10 часов 30 минут."]],""]]],[2008,"3–4 классы",[[817,76,"Сколько различных букв в словах УРА КЕНГУРУ?",{"0":[47.2,41.1,31.3,26.9],"1":[198.4,41.1,31.1,26.9],"2":[351.6,41.1,31.3,26.9],"3":[505.0,41.1,28.4,26.9],"4":[651.5,41.1,31.6,26.9]},"A","Буквы в двух словах",[["Выпиши буквы по одному разу","Из слова «УРА» берём У, Р и А. В «КЕНГУРУ» есть те же У и Р, а новыми будут К, Е, Н и Г."],["Посчитай разные буквы","Всего 3 + 4 = 7 разных букв."]],""],[817,103,"На листе бумаги поставили точку и провели через нее четыре прямые. На сколько частей эти прямые разделили лист бумаги?",{"0":[47.2,68.1,31.3,26.9],"1":[198.4,68.1,31.1,26.9],"2":[351.6,68.1,31.3,26.9],"3":[505.0,68.1,28.4,26.9],"4":[651.5,68.1,31.6,26.9]},"C","Прямые через общую точку",[["Начни с одной прямой","Первая прямая делит лист на две части. Все остальные пересекают её в одной и той же точке."],["Добавляй по две части","Каждая новая прямая делит ещё по одной части с каждой стороны от точки. Четыре прямые дают 2 + 2 + 2 + 2 = 8 частей."]],""],[817,102,"Через шесть с половиной часов наступит полночь. А сейчас который час?",{"0":[47.2,68.1,31.3,26.9],"1":[198.4,68.1,31.1,26.9],"2":[351.6,68.1,31.3,26.9],"3":[505.0,68.1,28.4,26.9],"4":[651.5,68.1,31.6,26.9]},"D","До полуночи",[["Отсчитай целые часы","Полночь можно записать как 24:00 в конце дня. На 6 часов раньше было 18:00."],["Отсчитай полчаса","Ещё на полчаса раньше было 17:30."]],""],[817,218,"Сколько веревочек на рисунке?",{"0":[47.2,49.3,31.3,26.9],"1":[198.4,49.3,31.1,26.9],"2":[351.6,49.3,31.3,26.9],"3":[47.2,83.4,28.4,26.9],"4":[198.4,83.4,31.6,26.9]},"D","Перепутанные верёвочки",[["Найди концы","Конец каждой верёвочки отмечен точкой. На пересечении двух верёвочек точек нет, а одна верёвочка просто проходит над другой."],["Собери концы в пары","На рисунке восемь точек. У каждой верёвочки по два конца, значит, верёвочек 8 ÷ 2 = 4."]],""],[817,102,"Сколько месяцев имеют в названии ровно 4 буквы?",{"0":[47.2,68.1,31.3,26.9],"1":[198.4,68.1,31.1,26.9],"2":[351.6,68.1,31.3,26.9],"3":[505.0,68.1,28.4,26.9],"4":[651.5,68.1,31.6,26.9]},"B","Короткие названия месяцев",[["Прочитай названия","Нужны месяцы, у которых в названии ровно четыре буквы. Март даёт М-А-Р-Т, июнь — И-Ю-Н-Ь, июль — И-Ю-Л-Ь."],["Проверь остальные месяцы","В слове «май» три буквы. В остальных названиях больше четырёх букв. Итого подходят три месяца."]],""],[817,130,"В первом аквариуме на 12 рыбок больше, чем во втором. Сколько рыбок надо переселить из первого аквариума во второй, чтобы рыбок в них стало поровну?",{"0":[47.2,95.1,31.3,26.9],"1":[198.4,95.1,31.1,26.9],"2":[351.6,95.1,31.3,26.9],"3":[505.0,95.1,28.4,26.9],"4":[651.5,95.1,31.6,26.9]},"C","Рыбки в двух аквариумах",[["Пересели одну рыбку","Рыбок в первом аквариуме станет на одну меньше, а во втором на одну больше. Разница сократится на две рыбки."],["Убери разницу полностью","Изначально разница равна 12 рыбкам, так что надо переселить 12 ÷ 2 = 6 рыбок."]],""],[817,211,"Дорожка выложена из 14 квадратных плит со стороной 1 м. Антон отметил центр каждой плиты и соединил эти точки линией. Какую длину имеет эта линия?",{"0":[47.2,176.2,31.3,26.9],"1":[198.4,176.2,31.1,26.9],"2":[351.6,176.2,31.3,26.9],"3":[505.0,176.2,28.4,26.9],"4":[651.5,176.2,31.6,26.9]},"B","Линия между центрами плит",[["Измерь один отрезок","Соседние плиты на рисунке соприкасаются сторонами. От центра одной до центра следующей 1 м, даже после поворота дорожки."],["Посчитай переходы","Между 14 центрами подряд ровно 13 переходов. Линия имеет длину 13 м."]],""],[845,110,"Какое из этих чисел не равно остальным?",{"0":[53.7,41.2,31.3,26.9],"1":[331.6,41.2,31.1,26.9],"2":[558.0,41.2,31.3,26.9],"3":[53.7,75.2,28.4,26.9],"4":[331.6,75.2,31.6,26.9]},"E","Одно непохожее число",[["Запиши числа цифрами","Сто раз по двадцать, двадцать сотен, двести десятков и две тысячи дают одно число — 2 000."],["Проверь последний вариант","Сто раз по двести — это 100 × 200 = 20 000. Этот вариант отличается."]],""],[845,260,"Никита кладет на лист бумаги два одинаковых треугольника (нарисованных справа) и обводит контур полученной фигуры. Какую фигуру он не сможет получить?",{"0":[73.3,225.1,31.3,26.9],"1":[231.1,225.1,31.1,26.9],"2":[390.8,225.1,31.3,26.9],"3":[563.8,225.1,28.4,26.9],"4":[710.2,225.1,31.6,26.9]},"E","Контур из двух треугольников",[["Рассмотри угол прямоугольника","У данных треугольников все углы равны 60°. Чтобы получить прямой угол контура, две перпендикулярные стороны у угла должны идти от разных треугольников."],["Посчитай нужные вершины","В каждом углу прямоугольника тогда должна быть вершина каждого треугольника. У прямоугольника четыре угла, а у треугольника три вершины. Значит, фигуру Д получить нельзя."]],""],[845,109,"Какую цифру или знак арифметического действия нужно поставить вместо *, чтобы равенство 1+1 * 1 – 2 = 100 стало верным?",{"0":[53.7,74.8,31.3,26.9],"1":[204.9,74.8,31.1,26.9],"2":[358.2,74.8,31.3,26.9],"3":[511.5,74.8,28.4,26.9],"4":[658.0,74.8,31.6,26.9]},"D","Знак или цифра",[["Проверь знаки","Если поставить знак действия, то между соседними единицами останется знак и будут только маленькие числа. Такой результат не достигнет 100."],["Проверь цифры","Ноль дал бы 1 + 101 − 2 = 100. Единица дала бы 1 + 111 − 2 = 110. Значит, вместо звёздочки нужен 0."]],""],[845,102,"Гоша выше Бориса, но ниже Антона. Витя выше Димы, но ниже Гоши. Кто из мальчиков самый высокий?",{"0":[53.7,68.1,31.3,26.9],"1":[204.9,68.1,31.1,26.9],"2":[358.2,68.1,31.3,26.9],"3":[511.5,68.1,28.4,26.9],"4":[658.0,68.1,31.6,26.9]},"A","Кто выше всех",[["Сравни Гошу и остальных","Гоша выше Бориса и Вити, а Витя выше Димы. Поэтому Гоша выше и Димы."],["Найди самого высокого","Антон выше Гоши, значит, он выше всех пятерых ребят."]],""],[845,129,"Вася любит умножать на 3, Маша – прибавлять 2, а Петя – вычитать 1. В каком порядке детей надо вызвать к доске выполнить любимое действие, чтобы из 1 получить 4?",{"0":[53.7,95.2,31.3,26.9],"1":[204.9,95.2,31.1,26.9],"2":[358.2,95.2,31.3,26.9],"3":[511.5,95.2,28.4,26.9],"4":[658.0,95.2,31.6,26.9]},"E","Порядок действий",[["Начни с Васи","Вася умножает 1 на 3 и получает 3. Маша прибавляет 2 и получает 5."],["Закончи действием Пети","Петя вычитает 1 из 5, получается 4. Подходит порядок В, М, П."]],""],[845,341,"Фигура составлена из 6 спичек. Сережа переложил две спички. Какая из фигур",{},"E","Две переложенные спички",[["Получаем А и Б","Для А передвинь левую вертикальную спичку на одну клетку вверх, чтобы замкнуть квадрат. Верхнюю правую горизонтальную спичку переставь вправо от нижнего конца длинной ножки. Для Б две спички нижнего левого уголка поставь вертикально — одну над длинной ножкой, другую под ней."],["Получаем В и Г","Для В убери верхнюю правую горизонталь и нижнюю правую вертикаль. Ими продли правый столбик вверх и сделай горизонталь под левой вертикалью. Для Г те же две спички положи горизонтально, одну вправо от середины правого столбика, другую вправо от нижнего конца левой вертикали. Все четыре фигуры получаются."]],""],[824,164,"У Даши 20 кубиков, у Маши 12 кубиков, у Глаши 8 кубиков, а у Наташи – 6 кубиков. Кто из девочек может построить куб из всех своих кубиков?",{"0":[53.7,95.2,31.3,26.9],"1":[318.2,95.2,31.1,26.9],"2":[584.7,95.2,31.3,26.9],"3":[53.7,129.2,28.4,26.9],"4":[318.2,129.2,31.6,26.9]},"C","Куб из маленьких кубиков",[["Посчитай кубики по слоям","Самый маленький куб из нескольких кубиков имеет по 2 кубика вдоль ребра. Он состоит из двух слоёв по 2 × 2 = 4 кубика, всего из 8."],["Сравни с большим кубом","Если вдоль ребра 3 кубика, всего понадобится 3 × 3 × 3 = 27 кубиков. Столько ни у кого нет. Куб из всех своих кубиков построит Глаша, у неё 8."]],""],[824,156,"В некоторой гостинице к приему гостей готово 5 трехместных номеров и один двухместный номер. Сколько еще двухместных номеров надо подготовить, чтобы разместить группу из 25 туристов?",{"0":[53.7,122.2,31.3,26.9],"1":[204.9,122.2,31.1,26.9],"2":[358.1,122.2,31.3,26.9],"3":[511.5,122.2,28.4,26.9],"4":[658.0,122.2,31.6,26.9]},"B","Номера для туристов",[["Посчитай готовые места","Пять трёхместных номеров дают 5 × 3 = 15 мест. Двухместный добавляет ещё 2, всего получается 17 мест."],["Размести оставшихся","Для 25 туристов не хватает 25 − 17 = 8 мест. Нужно подготовить 8 ÷ 2 = 4 двухместных номера."]],""],[824,190,"Квадратный участок земли разбит на 4 части: газон Г, цветник Ц, огород О и сад С. Сад и цветник – квадраты. Периметр сада – 80 м, а цветника – 20 м. Чему равен периметр газона?",{"0":[53.7,122.2,31.3,26.9],"1":[251.6,122.2,31.1,26.9],"2":[451.4,122.2,31.3,26.9],"3":[53.7,156.3,28.4,26.9],"4":[251.6,156.3,31.6,26.9]},"D","Периметр газона",[["Найди стороны двух квадратов","Сторона сада равна 80 ÷ 4 = 20 м. Сторона цветника равна 20 ÷ 4 = 5 м."],["Перенеси размеры на газон","На рисунке ширина газона равна стороне сада, а высота — стороне цветника. Периметр газона равен 2 × (20 + 5) = 50 м."]],""],[824,156,"В память о своем боевом прошлом старый пират отчеканил по одной монете достоинством 1000 дукатов, 3000 дукатов, 4000 дукатов, 6000 дукатов и 7000 дукатов. Сколькими способами он может набрать из них сумму в 14000 дукатов?",{"0":[53.7,122.2,31.3,26.9],"1":[204.9,122.2,31.1,26.9],"2":[358.1,122.2,31.3,26.9],"3":[511.5,122.2,28.4,26.9],"4":[658.0,122.2,31.6,26.9]},"C","Пиратские монеты",[["Посчитай способы с самой большой монетой","Вместе с монетой в 7 000 дукатов нужно взять ещё 7 000. Из оставшихся монет подходят пары 1 000 и 6 000 либо 3 000 и 4 000. Три самые маленькие монеты уже дают 8 000."],["Проверь способ без неё","Без монеты в 7 000 все четыре монеты вместе дают ровно 14 000. Их надо взять все. Всего три способа."]],""],[824,102,"Сколько существует двузначных чисел, у которых цифра десятков меньше, чем цифра единиц?",{"0":[53.7,68.2,31.3,26.9],"1":[204.9,68.2,31.1,26.9],"2":[358.2,68.2,31.3,26.9],"3":[511.5,68.2,28.4,26.9],"4":[658.0,68.2,31.6,26.9]},"C","Десятки меньше единиц",[["Выбирай число десятков","Если десятков 1, цифрой единиц может быть любая из 2–9. Это восемь вариантов. Если десятков 2, вариантов семь, и так далее до 8 десятков, когда единицы могут быть только 9."],["Сложи варианты","С девятью десятками вариантов нет. Сумма 8 + 7 + 6 + 5 + 4 + 3 + 2 + 1 равна 36."]],""],[824,156,"Конкурс «Кенгуру», в котором ты сегодня участвуешь, проходит в России уже в 15-ый раз (всегда в марте). Первый раз Аня участвовала в 11-ом конкурсе, когда ей только что исполнилось 10 лет. В каком году она родилась?",{"0":[53.7,122.2,31.3,26.9],"1":[204.9,122.2,31.1,26.9],"2":[358.2,122.2,31.3,26.9],"3":[511.5,122.2,28.4,26.9],"4":[658.0,122.2,31.6,26.9]},"D","Первый конкурс Ани",[["Найди год первого участия","В 2008 году прошёл 15-й конкурс. Одиннадцатый проходил на 15 − 11 = 4 года раньше, в 2004-м."],["Вычти возраст","Тогда Ане только что исполнилось 10 лет. Она родилась в 2004 − 10 = 1994 году."]],""],[824,156,"Три юных кенгуренка Кенг, Гур и Ру сидят на весах. Если с весов спрыгнет Кенг, то весы покажут 3 кг. Если спрыгнет Гур, то весы покажут 4 кг, а если спрыгнет Ру, то весы покажут 5 кг. Сколько весят все кенгурята вместе?",{"0":[53.7,122.2,31.3,26.9],"1":[204.9,122.2,31.1,26.9],"2":[358.1,122.2,31.3,26.9],"3":[511.5,122.2,28.4,26.9],"4":[658.0,122.2,31.6,26.9]},"E","Кенгурята на весах",[["Сложи веса пар","Три показания 3, 4 и 5 кг дают в сумме 12 кг. В каждом взвешивании на весах по два кенгурёнка."],["Убери двойной счёт","Каждый кенгурёнок вошёл в сумму ровно два раза. Все вместе они весят 12 ÷ 2 = 6 кг."]],""],[845,123,"У Тани и ее родителей общий день рождения – 1 января. В январе 2007 года Таня была в 6 раз младше своей мамы, а в январе 2008 – в 6 раз младше папы. На сколько лет папа старше мамы?",{"0":[53.7,88.7,31.3,26.9],"1":[204.9,88.7,31.1,26.9],"2":[358.1,88.7,31.3,26.9],"3":[511.5,88.7,28.4,26.9],"4":[658.0,88.7,31.6,26.9]},"C","Дни рождения Тани и родителей",[["Проследи один год","В январе 2007 года возраст мамы был равен шести возрастам Тани. К январю 2008 года Таня стала на год старше, поэтому шесть её возрастов выросли на 6 лет."],["Сравни родителей в 2008 году","Возраст папы тогда равен шести новым возрастам Тани. Мама за то же время стала старше только на 1 год. Папа старше мамы на 6 − 1 = 5 лет."]],""],[845,156,"Точки А, B, C и D отмечены на прямой в некотором порядке. Известны расстояния: от А до B – 13 см, от B до C – 11 см, от C до D – 14 см и от D до А – 12 см. Чему равно расстояние между наиболее удаленными точками?",{"0":[53.7,120.9,31.3,26.9],"1":[204.9,120.9,31.1,26.9],"2":[358.2,120.9,31.3,26.9],"3":[511.5,120.9,28.4,26.9],"4":[658.0,120.9,31.6,26.9]},"B","Четыре точки на прямой",[["Поставь A и B","Положи A на отметку 0, а B — на 13. Точка C в 11 см от B, так что она может быть на отметке 2 или 24. Точка D в 12 см от A, значит, она может быть на 12 или −12."],["Подбери C и D","Разница ровно 14 см получается только между 2 и −12. Порядок слева направо D, A, C, B. Между крайними точками D и B расстояние 12 + 13 = 25 см."]],""],[845,203,"Один странный мальчик по четвергам и пятницам говорит только правду, по вторникам всегда лжет, а в остальные дни недели он может и солгать, и сказать правду. Семь дней подряд мальчика спрашивали, как его зовут. Первые шесть ответов, по порядку, были таковы: Женя, Боря, Вася, Боря, Петя, Боря. Как он ответил на седьмой день?",{"0":[53.7,140.1,31.3,26.9],"1":[318.2,140.1,31.1,26.9],"2":[584.7,140.1,31.3,26.9],"3":[53.7,168.1,28.4,26.9],"4":[318.2,168.1,31.6,26.9]},"A","Мальчик и его имя",[["Найди четверг и пятницу","В четверг и пятницу мальчик называет одно и то же настоящее имя. Среди первых шести ответов никакие два соседних не совпадают. Значит, четверг и пятница — дни 6 и 7 либо дни 7 и 1, если пятница была в начале опроса."],["Проверь вторник","Если четверг был в день 6, мальчика зовут Боря. Но тогда во вторник, в день 4, он тоже назвался Борей, хотя обязан был соврать."],["Назови имя","Значит, пятница была в день 1, когда прозвучало «Женя». День 7 — четверг, когда мальчик тоже сказал «Женя»."]],""],[845,197,"Фонтан на площади старинного города связан с часами на башне: он работает, когда хотя бы одна из стрелок часов находится между цифрами 3 и 4 или между цифрами 8 и 9. Сколько времени в течение суток этот фонтан работает?",{"0":[53.7,137.7,31.3,26.9],"1":[251.6,137.7,31.1,26.9],"2":[451.4,137.7,31.3,26.9],"3":[53.7,163.4,28.4,26.9],"4":[251.6,163.4,31.6,26.9]},"C","Часы и фонтан",[["Посчитай время каждой стрелки","Минутная стрелка проходит каждый из двух нужных секторов за 5 минут. За сутки она даёт 24 × 10 = 240 минут. Часовая стрелка в каждом секторе проводит по часу и за сутки проходит каждый сектор дважды, что тоже даёт 240 минут."],["Вычти время, посчитанное дважды","В каждый из четырёх часов, когда часовая стрелка в нужном секторе, минутная тоже попадает в нужные секторы на 10 минут. Убираем повторные 4 × 10 = 40 минут. Получаем 240 + 240 − 40 = 440 минут, или 7 ч 20 мин."]],""],[845,241,"",{},"D","Кубики из развёрток",[["Совмести две грани","Мысленно сложи каждый кубик так, чтобы звёздочка была спереди, а чёрный квадрат сверху. Тогда пустой квадрат окажется сзади, а пустой кружок снизу."],["Проверь ромб","У развёрток А, Б, В и Д ромб будет слева, а чёрный кружок справа. У развёртки Г эти две грани меняются местами. Г даёт другой кубик."]],""],[845,151,"В первый понедельник каждого из трех летних месяцев Маша записывала число, на которое пришелся этот понедельник, а в конце лета сложила три записанных числа. Какая наименьшая сумма могла получиться?",{"0":[53.7,116.8,31.3,26.9],"1":[205.0,116.8,31.1,26.9],"2":[358.2,116.8,31.3,26.9],"3":[511.5,116.8,28.4,26.9],"4":[658.0,116.8,31.6,26.9]},"C","Первые понедельники лета",[["Найди сдвиги между месяцами","В июне 30 дней, это 4 недели и 2 дня, а в июле 31 день, это 4 недели и 3 дня. Поэтому первый понедельник в июле приходится на число на 2 меньше июньского, а в августе на число на 3 меньше июльского. Если номер меньше 1, прибавляем 7."],["Перебери июньские даты","Для июньских чисел от 1 до 7 тройки такие: 1, 6, 3, затем 2, 7, 4, затем 3, 1, 5, затем 4, 2, 6, затем 5, 3, 7, затем 6, 4, 1 и затем 7, 5, 2."],["Выбери наименьшую сумму","Суммы по порядку равны 10, 13, 9, 12, 15, 11 и 14. Самая маленькая — 9, когда первые понедельники приходятся на 3 июня, 1 июля и 5 августа."]],""]]],[2009,"3–4 классы",[[834,229,"Сколько треугольников на рисунке?",{},"D","Треугольники на рисунке",[["Рассмотри голову","Два уха и мордочка — это три треугольника."],["Рассмотри остальные части","Ещё два треугольника — маленькая лапка у туловища и длинный хвост. Шея, туловище и две нижние детали имеют по четыре стороны. Всего 5 треугольников."]],""],[834,108,"",{},"C","Умножение и сложение",[["Начни с произведения","200 × 9 = 1 800."],["Прибавь остальные числа","1 800 + 200 = 2 000, а 2 000 + 9 = 2 009."]],""],[834,72,"Сколько всего вершин у четырех кубиков?",{"0":[47.2,40.5,31.3,24.1],"1":[198.4,40.5,31.1,24.1],"2":[351.6,40.5,31.3,24.1],"3":[505.0,40.5,28.4,24.1],"4":[651.5,40.5,31.6,24.1]},"A","Вершины кубиков",[["Посчитай вершины одного кубика","У кубика по четыре вершины на верхней и нижней гранях, всего восемь."],["Умножь на число кубиков","Каждый из четырёх кубиков даёт восемь вершин. Всего 4 × 8 = 32."]],""],[834,208,"",{"0":[47.2,40.5,31.3,24.1],"1":[47.2,74.6,31.1,24.1],"2":[47.2,108.7,31.3,24.1],"3":[47.2,142.8,28.4,24.1],"4":[47.2,176.8,31.6,24.1]},"B","Где находится кенгуру",[["Проверь круг и квадрат","Кенгуру нарисован внутри контура круга и внутри контура квадрата."],["Проверь треугольник","Кенгуру лежит ниже нижней стороны треугольника и потому за его пределами. Подходит ответ Б."]],""],[834,99,"В пятиэтажном доме в каждом подъезде на каждом этаже расположено по 4 квартиры. На каком этаже находится квартира с номером 71?",{"0":[47.2,67.6,31.3,24.1],"1":[198.4,67.6,31.1,24.1],"2":[351.6,67.6,31.3,24.1],"3":[505.0,67.6,28.4,24.1],"4":[651.4,67.6,31.6,24.1]},"C","Квартира номер 71",[["Найди подъезд","В каждом подъезде 5 × 4 = 20 квартир. После трёх подъездов проходят номера от 1 до 60. Квартира 71 — в четвёртом подъезде."],["Распредели номера по этажам","На первом этаже квартиры 61–64, на втором — 65–68, на третьем — 69–72. Квартира 71 находится на третьем этаже."]],""],[834,182,"На клетчатой бумаге нарисовано число 930 (см. рисунок). Сколько маленьких квадратиков должно поменять цвет, чтобы получилось число 806?",{"0":[47.2,103.9,31.3,24.1],"1":[198.4,103.9,31.1,24.1],"2":[351.6,103.9,31.3,24.1],"3":[47.2,138.0,28.4,24.1],"4":[198.4,138.0,31.6,24.1]},"B","Из 930 в 806",[["Сравни цифры попарно","Для 9 → 8 надо закрасить одну клетку слева под серединой. Для 3 → 0 надо закрасить две недостающие клетки слева и убрать среднюю клетку в центральном ряду. Это три изменения."],["Посчитай последнее изменение","Для 0 → 6 нужно убрать клетку справа над серединой и закрасить центральную клетку. Итого 1 + 3 + 2 = 6 изменений."]],""],[834,104,"Вася подсчитал число дней в двух идущих подряд месяцах. Какое число он не мог получить?",{"0":[47.2,72.4,31.3,24.1],"1":[198.4,72.4,31.1,24.1],"2":[351.6,72.4,31.3,24.1],"3":[505.0,72.4,28.4,24.1],"4":[651.5,72.4,31.6,24.1]},"C","Дни в соседних месяцах",[["Найди самый короткий месяц","Самый короткий месяц — февраль, в нём 28 или 29 дней. С обеих сторон от него месяцы по 31 дню. Даже с коротким февралём получается не меньше 28 + 31 = 59 дней."],["Проверь остальные пары","Два других соседних месяца дают по меньшей мере 60 дней. 58 дней получить нельзя."]],""],[862,180,"Шоколадная плитка состоит из одинаковых долек. Маленький Владик разделил ее «по-честному»: сначала он отломал полоску из 5 долек для бабушки, а затем полоску из 7 долек для дедушки (см. рисунок). Сколько долек у него осталось?",{"0":[53.7,148.6,31.3,24.1],"1":[204.9,148.6,31.1,24.1],"2":[358.1,148.6,31.3,24.1],"3":[511.5,148.6,28.4,24.1],"4":[658.0,148.6,31.6,24.1]},"B","Две полоски шоколада",[["Найди размеры плитки","Первая полоска идёт сверху вниз на всю высоту и содержит 5 долек. После неё в нижней горизонтальной полоске остаётся 7 долек, значит, оставшаяся часть плитки имеет ширину 7 долек."],["Вычти нижний ряд","После второй полоски остаются 5 − 1 = 4 ряда по 7 долек. Всего 4 × 7 = 28 долек."]],""],[862,72,"Произведение цифр двузначного числа не может равняться",{"0":[53.7,40.5,31.3,24.1],"1":[204.9,40.5,31.1,24.1],"2":[358.1,40.5,31.3,24.1],"3":[511.5,40.5,28.4,24.1],"4":[658.0,40.5,31.6,24.1]},"D","Произведение двух цифр",[["Проверь возможные произведения","40 = 5 × 8, 36 = 4 × 9, 20 = 4 × 5, а 12 = 3 × 4. Все множители в этих равенствах могут быть цифрами."],["Рассмотри число 13","У 13 есть только множители 1 и 13. Число 13 само не цифра, поэтому такое произведение невозможно."]],""],[862,187,"В 3 часа ночи в замке появилось Привидение. Часы на башне замка, которые до этого показывали правильное время, пошли с обычной скоростью, но в другую сторону. Привидение исчезло с рассветом, в 4 часа 45 минут. Какое время в этот момент показывали часы?",{"0":[53.7,121.6,31.3,24.1],"1":[318.2,121.6,31.1,24.1],"2":[584.7,121.6,31.3,24.1],"3":[53.7,155.6,28.4,24.1],"4":[318.2,155.6,31.6,24.1]},"B","Часы пошли назад",[["Найди прошедшее время","Между 3:00 и 4:45 прошло 1 час 45 минут."],["Отсчитай столько же назад","От 3:00 отсчитай час назад до 2:00 и ещё 45 минут до 1:15. Часы показывали 1 час 15 минут."]],""],[862,153,"В танцевальной студии занимались 25 мальчиков и 19 девочек. Каждую неделю в группу приходят два новых мальчика и три новых девочки. Через сколько недель мальчиков и девочек в этой студии станет поровну?",{"0":[53.7,121.7,31.3,24.1],"1":[204.9,121.7,31.1,24.1],"2":[358.1,121.7,31.3,24.1],"3":[511.5,121.7,28.4,24.1],"4":[658.0,121.7,31.6,24.1]},"A","Мальчики и девочки в студии",[["Посчитай начальную разницу","Вначале мальчиков больше на 25 − 19 = 6 человек."],["Учти приход новых ребят","За неделю приходят 2 мальчика и 3 девочки. Девочки каждую неделю сокращают разницу на одного человека. Через 6 недель мальчиков и девочек станет поровну."]],""],[862,72,"У скольких трехзначных чисел сумма цифр равна 2?",{"0":[53.7,40.6,31.3,24.1],"1":[204.9,40.6,31.1,24.1],"2":[358.1,40.6,31.3,24.1],"3":[511.5,40.6,28.4,24.1],"4":[658.0,40.6,31.6,24.1]},"D","Трёхзначные числа с суммой цифр 2",[["Выбери цифру сотен","Первая цифра может быть только 1 или 2. Если взять 2, двум другим цифрам остаётся сумма 0. Получается 200."],["Проверь случай с единицей","Если первая цифра 1, две другие дают сумму 1. Это 1 и 0 в любом порядке. Получаются 110 и 101. Всего 3 числа."]],""],[862,194,"На картинке справа изменили цвет каждой клеточки: белый – на красный, и наоборот. Что получилось?",{"0":[79.8,163.1,31.3,24.1],"1":[218.0,163.1,31.1,24.1],"2":[358.1,163.1,31.3,24.1],"3":[504.4,163.1,28.4,24.1],"4":[644.7,163.1,31.6,24.1]},"D","Белые и красные клетки",[["Перекрась верхнюю половину","В новом первом ряду будут закрашены клетки 1, 2 и 4, во втором — 3 и 4. Считай слева направо."],["Перекрась нижнюю половину","В третьем ряду будут закрашены клетки 1 и 4, а в четвёртом — 1, 2 и 3. Все четыре ряда совпадают с рисунком Г."]],""],[862,167,"В комнате сидят несколько кошек и собак. Кошачьих лап в комнате вдвое больше, чем собачьих носов. Тогда кошек в комнате",{"0":[53.7,67.6,31.3,24.1],"1":[451.4,67.6,31.1,24.1],"2":[53.7,101.7,31.3,24.1],"3":[451.4,101.7,28.4,24.1],"4":[53.7,135.8,31.6,24.1]},"C","Кошачьи лапы и собачьи носы",[["Свяжи лапы с носами","У одной кошки четыре лапы. Если кошачьих лап вдвое больше, чем собачьих носов, на каждые четыре лапы приходится два носа."],["Вернись к животным","У каждой собаки один нос, значит, на одну кошку приходится две собаки. Кошек вдвое меньше."]],""],[840,270,"Город разделен улицами на квадратные кварталы. Машина выезжает из точки М и на каждом перекрестке поворачивает налево или направо. Проехав один квартал, машина повернула направо, потом три раза налево, а потом еще два раза направо. На каком из рисунков изображен маршрут машины?",{"0":[53.7,154.0,31.3,24.1],"1":[215.6,154.0,31.1,24.1],"2":[377.7,154.0,31.3,24.1],"3":[511.5,154.0,28.4,24.1],"4":[671.0,154.0,31.6,24.1]},"E","Маршрут машины",[["Прочитай повороты по порядку","Если первый квартал машина едет вверх от М, дальше поворот направо ведёт вправо. Три левых поворота затем ведут вверх, влево и вниз. Машина объезжает квадрат и возвращается на первый перекрёсток."],["Дорисуй последние два отрезка","Теперь машина смотрит вниз. Два правых поворота ведут сначала влево, затем вверх. Квадрат справа и эти два отрезка слева есть на рисунке Д."]],""],[840,153,"Белки Алли, Элли и Салли нашли вместе семь орехов. Каждая из них нашла хотя бы по одному ореху, и у всех оказалось разное число орехов. Алли нашла орехов меньше всех, а Элли – больше всех. Сколько орехов нашла Элли?",{"0":[53.7,121.7,31.3,24.1],"1":[165.0,121.7,31.1,24.1],"2":[278.2,121.7,31.3,24.1],"3":[391.5,121.7,28.4,24.1],"4":[491.4,121.7,31.6,24.1]},"A","Орехи трёх белок",[["Начни с трёх разных чисел","Три наименьших разных положительных числа — 1, 2 и 3. В сумме это 6 орехов."],["Добавь седьмой орех","Если добавить его к 1 или 2, две белки получат одинаковое число орехов. Добавь к 3. Тогда белки нашли 1, 2 и 4 ореха, а у Элли больше всех — 4."]],""],[840,153,"Аня и Петя живут на набережной. Слева от дома Ани на набережной находится 47 домов, а справа – 23 дома. От дома Пети слева и справа по набережной находится одинаковое число домов. Сколько домов расположено между домами Ани и Пети?",{"0":[53.7,121.6,31.3,24.1],"1":[204.9,121.6,31.1,24.1],"2":[358.1,121.6,31.3,24.1],"3":[511.5,121.6,28.4,24.1],"4":[658.0,121.6,31.6,24.1]},"B","Дома на набережной",[["Найди номера домов в ряду","Всего домов 47 + 1 + 23 = 71. Дом Ани 48-й слева. Петин дом посередине ряда, поэтому перед ним 35 домов, а он сам 36-й."],["Посчитай дома между ними","Разница номеров 48 − 36 = 12. Между домами 12 − 1 = 11 домов."]],""],[840,187,"Из палочек можно выкладывать цифры как на рисунке. Какова сумма цифр самого большого числа, которое удастся выложить, использовав ровно 15 палочек?",{"0":[53.7,121.6,31.3,24.1],"1":[204.9,121.6,31.1,24.1],"2":[358.1,121.6,31.3,24.1],"3":[53.7,155.6,28.4,24.1],"4":[205.0,155.6,31.6,24.1]},"D","Самое большое число из палочек",[["Найди максимум цифр","На любую изображённую цифру уходит не меньше 3 палочек. Из 15 палочек получается не больше 5 цифр. Пятизначное число больше любого числа с меньшим числом цифр."],["Выбери самые большие цифры","Для пяти цифр каждая должна состоять ровно из трёх палочек. Так выложены 1 и 7. Самое большое число — 77 777, сумма его цифр равна 5 × 7 = 35."]],""],[840,153,"Букет состоит из 4 цветков: красного, голубого, желтого и белого. Пчела Майя садится на каждый цветок в букете только один раз. Она начинает с красного цветка и не перелетает с желтого сразу на белый. Сколькими способами Майя может облететь все цветы?",{"0":[53.7,121.6,31.3,24.1],"1":[204.9,121.6,31.1,24.1],"2":[358.1,121.6,31.3,24.1],"3":[511.5,121.6,28.4,24.1],"4":[658.0,121.6,31.6,24.1]},"B","Маршруты пчелы Майи",[["Посчитай все порядки после красного","Три оставшихся цветка можно посетить 3 × 2 × 1 = 6 способами."],["Убери два запрещённых порядка","Если жёлтый должен сразу вести на белый, эту пару можно поставить перед голубым или после него. Такие два порядка запрещены. Значит, допустимых маршрутов 6 − 2 = 4."]],""],[840,192,"Будем называть шестизначное число счастливым, если у него сумма цифр, стоящих на нечетных местах, равна сумме цифр, стоящих на четных местах. В каком случае можно заполнить пустые места цифрами так, чтобы получилось счастливое число?",{"0":[53.7,121.7,31.3,24.1],"1":[304.9,121.7,31.1,24.1],"2":[558.0,121.7,31.3,24.1],"3":[53.7,160.4,28.4,24.1],"4":[304.9,160.4,31.6,24.1]},"D","Счастливое шестизначное число",[["Сравни границы сумм","Каждый пропуск можно заполнить цифрой от 0 до 9. В А нечётная сумма не меньше 14, чётная не больше 11. В Б эти границы 21 и 20. В В нечётная сумма равна 12, чётная не больше 11. В Д нечётная сумма равна 4, чётная не меньше 8."],["Заполни цифры в Г","В Г сумма на чётных местах равна 2 + 9 + 8 = 19. На нечётных уже есть 1. Чтобы получить 19, в оба пропуска надо поставить по 9. Получается 129 998."]],""],[862,210,"Какую фигуру нельзя составить из двух костяшек домино, изображенных справа?",{"0":[79.9,179.3,31.3,24.1],"1":[205.0,179.3,31.1,24.1],"2":[325.0,179.3,31.3,24.1],"3":[438.2,179.3,28.4,24.1],"4":[558.0,179.3,31.6,24.1]},"E","Костяшки домино",[["Проверь направления точек","У исходных костяшек диагонали из двух и трёх точек идут из верхнего левого угла в нижний правый. Поворот на пол-оборота сохраняет эту диагональ. Если положить костяшку горизонтально, диагональ пойдёт в другую сторону."],["Разбей квадраты на костяшки","Квадраты А и Б собираются из двух вертикальных костяшек, а В и Г — из двух горизонтальных. В Д диагонали у костяшек разные, значит, одна должна лежать вертикально, а другая горизонтально. Так квадрат из двух костяшек не собрать."]],""],[862,153,"Дикарь Пятница написал в строчку несколько различных чисел, не превосходящих 10. Робинзон Крузо заметил, что в любой паре соседних чисел одно из них делится на другое без остатка. Какое наибольшее количество чисел мог выписать Пятница?",{"0":[53.7,121.7,31.3,24.1],"1":[204.9,121.7,31.1,24.1],"2":[358.1,121.7,31.3,24.1],"3":[511.5,121.7,28.4,24.1],"4":[658.0,121.7,31.6,24.1]},"D","Цепочка делящихся чисел",[["Составь цепочку из девяти","Подходит ряд 4, 8, 1, 5, 10, 2, 6, 3, 9. В каждой соседней паре одно число делится на другое."],["Попробуй включить все десять","Число 7 может стоять лишь с краю, рядом с 1. Если 1 поставим между 7 и одним из чисел 4 или 8, то и 5, и 9 придётся поставить с краю. Ведь для них, кроме занятой 1, подходит только один сосед — 10 или 3 соответственно. Трёх краёв у ряда нет."],["Проверь числа 4 и 8","Теперь ни 4, ни 8 не могут соседствовать с 1. Второй край должен занять 5 или 9, поскольку они оба не могут оказаться рядом с 1. Значит, 4 и 8 стоят внутри и каждое должно соседствовать с другим из этой пары и с 2. Получится замкнутое кольцо 2–4–8–2, а в одном ряду без повторов это невозможно."]],""],[862,126,"В доме между любыми двумя комнатами не более одной двери, и из каждой комнаты не более одной двери ведет в сад. Всего в доме 12 дверей. Какое наименьшее число комнат может быть в этом доме?",{"0":[53.7,94.7,31.3,24.1],"1":[204.9,94.7,31.1,24.1],"2":[358.1,94.7,31.3,24.1],"3":[511.5,94.7,28.4,24.1],"4":[658.0,94.7,31.6,24.1]},"C","Комнаты и двери",[["Посчитай двери для четырёх комнат","При четырёх комнатах каждая из них может быть соединена с тремя другими. Считаем 4 × 3 ÷ 2 = 6 дверей между комнатами, потому что у каждой двери два конца. Ещё до четырёх дверей могут вести в сад. Всего не больше 10 дверей."],["Проверь пять комнат","Между пятью комнатами можно сделать 5 × 4 ÷ 2 = 10 дверей. Добавь две двери в сад из разных комнат, получишь 12. Наименьшее число комнат — 5."]],""],[862,152,"В таблицу 3×3 вписывают цифры так, что все 6 сумм, полученных при сложении цифр из каждой строки и каждого столбца, оказываются разными. Чему равна самая маленькая сумма всех цифр в таблице с таким свойством?",{"0":[53.7,121.7,31.3,24.1],"1":[204.9,121.7,31.1,24.1],"2":[358.1,121.7,31.3,24.1],"3":[511.5,121.7,28.4,24.1],"4":[658.0,121.7,31.6,24.1]},"B","Шесть разных сумм",[["Оцени общую сумму снизу","Три суммы строк вместе дают сумму всех клеток. Три суммы столбцов дают её ещё раз. Шесть разных неотрицательных сумм в сумме дают не меньше 0 + 1 + 2 + 3 + 4 + 5 = 15. Значит, сумма клеток не меньше 8."],["Заполни таблицу на сумму 8","Запиши в строках числа (0, 0, 0), (0, 0, 2) и (1, 3, 2). Суммы строк — 0, 2, 6, а столбцов — 1, 3, 4. Они все разные, а сумма всех клеток действительно 8."]],""],[862,126,"В равенстве K + A + N + G + A + R + O + O = 56 разные буквы обозначают разные цифры, а одинаковые буквы – одинаковые цифры. Наименьшее возможное значение суммы K + A + N равно",{"0":[53.7,94.6,31.3,24.1],"1":[204.9,94.6,31.1,24.1],"2":[358.2,94.6,31.3,24.1],"3":[511.5,94.6,28.4,24.1],"4":[658.0,94.6,31.6,24.1]},"D","Цифры в слове KANGAROO",[["Отдели искомую сумму","Из 56 выдели сумму K + A + N. Остаётся A + G + R + O + O. Здесь четыре разные цифры, причём O учитывается дважды."],["Найди предел для остатка","Наибольший остаток дают 9 на месте повторённой цифры и цифры 8, 7, 6 на остальных местах. Это 2 × 9 + 8 + 7 + 6 = 39. Искомая сумма не меньше 56 − 39 = 17."],["Проверь значение 17","Возьми K = 4, A = 8, N = 5, G = 6, R = 7, O = 9. Все цифры разные, исходная сумма равна 56, а 4 + 8 + 5 = 17."]],""],[862,189,"На рисунке изображены три одинаковых кубика. На гранях кубиков нарисованы цифры: 0, 1, 3, 4, 5, 9. Чему равна сумма чисел на нижних гранях этих кубиков?",{"0":[53.7,158.1,31.3,24.1],"1":[204.9,158.1,31.1,24.1],"2":[358.1,158.1,31.3,24.1],"3":[511.5,158.1,28.4,24.1],"4":[658.0,158.1,31.6,24.1]},"A","Нижние грани кубиков",[["Найди противоположную грань для 4","По первому и второму рисункам у грани 4 есть четыре соседа: 3, 1, 0 и 9. Остаётся цифра 5, она на противоположной грани."],["Найди противоположную грань для 1","По первому и третьему рисункам у грани 1 есть соседи 4, 3, 5 и 9. Значит, цифра 0 стоит напротив 1."],["Сложи нижние грани","Сверху видны 4, 0 и 5. Значит, снизу 5, 1 и 4. Их сумма равна 10."]],""]]],[2010,"3–4 классы",[[841,152,"Что можно получить из слова К Е Н Г У Р У, если стереть неко­ торые буквы?",{"0":[55.0,75.1,31.3,31.3],"1":[314.8,75.1,31.1,31.3],"2":[578.0,75.1,31.3,31.3],"3":[55.0,115.1,28.4,31.3],"4":[314.8,115.1,31.6,31.3]},"D","Буквы на своих местах",[["Запиши слово","Подпиши под клетками буквы К, Е, Н, Г, У, Р, У по порядку."],["Проверь места букв","Стирание оставляет пустые клетки, но не передвигает буквы. К в первой, Е во второй и Р в шестой клетке правильно стоят только в варианте Г."]],""],[841,133,"",{},"E","Чей шаг длиннее",[["Сравни шаги","Все ребята прошли одну и ту же дорожку. Чем длиннее шаг, тем меньше шагов нужно."],["Найди самое малое число","Меньше всех шагов сделала Таня — 12. Значит, у неё самый длинный шаг."]],""],[841,76,"",{},"C","Цифра под кружком",[["Убери по кружку","Справа четыре одинаковых кружка. Убери по одному кружку из обеих частей равенства."],["Раздели поровну","Осталось 12 = кружок + кружок + кружок. Каждый кружок равен 4."]],""],[841,311,"Лабиринт устроен так, что кот может добраться до молока, а мышка — до сыра, но они не могут встретить­ ся. Какая часть лабиринта закрыта квадратиком?",{"0":[55.0,259.9,31.3,31.3],"1":[208.3,259.9,31.1,31.3],"2":[361.5,259.9,31.3,31.3],"3":[514.7,259.9,28.4,31.3],"4":[667.9,259.9,31.6,31.3]},"E","Две дорожки",[["Направь кота и мышку","Коту нужно свернуть с дороги слева вверх к молоку. Мышке нужно с дороги справа повернуть вниз, чтобы выйти к сыру."],["Раздели пути","В варианте Д одна дуга соединяет левый и верхний выходы, а другая — правый и нижний. Эти дуги не пересекаются."]],""],[841,136,"",{},"C","Башмаки стоножки",[["Посчитай новые башмаки","В каждой паре по два башмака. Новой обуви хватило на 16 × 2 = 32 ножки."],["Отними лишние ножки","Из 100 ножек убери 32 в новых башмаках и 14 босых. В старых башмаках было 54 ножки."]],""],[841,162,"",{},"A","Отражение шестёрки",[["Отрази цифру справа","В вертикальном зеркале левая и правая стороны цифры меняются местами."],["Отрази её вниз","Горизонтальное зеркало меняет местами верх и низ. Два отражения дают поворот на пол-оборота. Из 6 получается 9."]],""],[862,105,"",{},"B","Середина урока",[["Раздели время пополам","Половина 40 минут — 20 минут."],["Прибавь к началу","Через 15 минут после 11:45 будет 12:00. Ещё через 5 минут будет 12:05."]],""],[862,133,"",{},"D","Ноябрь без солнца",[["Посчитай все часы","В ноябре 30 суток, в каждых по 24 часа. Всего 30 × 24 = 720 часов."],["Вычти солнечные часы","Солнце светило 13 часов. Значит, без солнца прошло 720 − 13 = 707 часов."]],""],[862,105,"",{},"C","Числа с пятёркой",[["Выбери первую цифру","Цифра сотен не может быть нулём. Она может быть любой от 1 до 7."],["Восстанови последнюю цифру","Для каждой первой цифры последняя определяется однозначно: дополняет её до 7. Получаются 156, 255, 354, 453, 552, 651 и 750, всего 7 чисел."]],""],[862,161,"",{},"E","Набор машинок",[["Сложи цены","Если покупать три машинки отдельно, они обойдутся в 15 + 21 + 28 = 64 рубля."],["Сравни с набором","Набор стоит 56 рублей. Экономия составит 64 − 56 = 8 рублей."]],""],[862,105,"",{},"C","Лапы и лапки",[["Сосчитай лапки насекомых и пауков","У двух мух 2 × 6 = 12 лапок, у трёх пауков 3 × 8 = 24. Всего 36 лапок."],["Убери лапы попугаев","У десяти попугаев 20 лап. Осталось 36 − 20 = 16 лап, по четыре на каждое животное. Подходят четыре собаки."]],""],[862,191,"",{},"A","Девочки из 3 «а»",[["Начни с Кати","Оля и Аня обе учатся отдельно от Кати. Классов только два, поэтому Аня и Оля учатся вместе."],["Найди класс из двух девочек","Лена учится отдельно от Оли, а Ира — отдельно от Ани. Значит, Катя, Ира и Лена в 3 «б», а Аня и Оля в 3 «а»."]],""],[862,174,"",{},"C","Вес звёздочки",[["Иди по правой ветке","Верхняя планка делит 128 г пополам. На правой ветке 64 г. На каждой следующей уравновешенной планке опять дели вес надвое."],["Дойди до звёздочки","Правая часть следующей планки весит 32 г. На пару звезда и шар приходится 16 г. Значит, на звезду приходится 8 г."]],""],[862,133,"",{},"B","Этаж Клары",[["Найди половину пути","Между этажами Карла и Клары 12 этажей. Половина пути — подъём на 6 этажей."],["Закончи подъём","В середине пути Карл был на 8-м этаже. Ему осталось подняться на 6 этажей. Клара живёт на 14-м."]],""],[841,143,"",{},"D","Секунды за неделю",[["Начни с часа","В минуте 60 секунд, а в часе 60 минут. Значит, в часе 60 × 60 секунд."],["Перейди к неделе","Умножение на 24 даёт число секунд в сутках, а умножение ещё на 7 — число секунд в неделе."]],""],[841,181,"На рисунке справа изображена керамическая плитка. Какую картинку нельзя составить из четырех таких плиток?",{"0":[55.1,115.1,31.3,31.3],"1":[208.3,115.1,31.1,31.3],"2":[361.5,115.1,31.3,31.3],"3":[514.7,115.1,28.4,31.3],"4":[667.9,115.1,31.6,31.3]},"E","Поворот плиток",[["Смотри на нос и глаз","У исходной плитки нос смотрит влево, а глаз находится выше носа. Если повернуть плитку на пол-оборота, нос будет смотреть вправо, а глаз окажется ниже."],["Проверь верхнюю левую плитку варианта Д","У этой плитки нос смотрит вправо, но глаз расположен выше носа. Такой рисунок получается при отражении исходной плитки в зеркале. Одним поворотом его получить нельзя."]],""],[841,104,"",{},"C","Возраст Малыша",[["Вернись на два года назад","Сейчас Тоше 13 лет, а два года назад ему было 11. Малышу тогда было 15 − 11 = 4 года."],["Отсчитай до девяти","Сейчас Малышу 4 + 2 = 6 лет. Девять ему исполнится через 3 года."]],""],[841,77,"",{},"D","Миллионная часть тонны",[["Вспомни, сколько в тонне килограммов","Тонна — это 1000 килограммов."],["Переведи в граммы","В каждом килограмме 1000 граммов, значит, в тонне миллион граммов. Миллионная часть тонны равна одному грамму."]],""],[841,138,"",{},"B","Ребус с тремя буквами",[["Угадай сотни","Даже 222 + 9 меньше 260. Даже 444 − 99 больше 260. Значит, А = 3 и первое число — 333."],["Восстанови остальные цифры","Из 333 нужно вычесть 73. Число из двух одинаковых цифр, которое можно уменьшить одной цифрой до 73, — это 77. Тогда В = 7, С = 4 и 3 + 7 + 4 = 14."]],""],[841,221,"",{},"B","Равные суммы строк",[["Сравни числа в столбцах","Во второй строке четыре числа на 10 больше своих соседей сверху, а два на 10 меньше."],["Уравняй строки","Без звёздочек вторая строка больше на 4 × 10 − 2 × 10 = 20. Значит, первое вписанное число должно быть на 20 больше второго."]],""],[841,224,"",{},"D","Кусок клетчатой бумаги",[["Найди четыре нужные клетки","У каждого жирного отрезка в кусок должна попасть клетка с одной стороны. Чтобы уложиться в 7 клеток, нужен прямоугольник в 4 клетки шириной и 4 высотой: большее поле требует хотя бы 8 клеток для соединения рядов и столбцов."],["Проверь семь клеток","Для связного куска из 7 клеток было бы ровно шесть соединений, по одному через каждую линию между его четырьмя рядами и четырьмя столбцами. Но между средними столбцами нужен переход и в верхнем ряду, и ниже него: отмеченные края требуют клеток по обе стороны в каждой из этих двух частей."],["Собери восемь","Если считать сверху и слева, возьми в ряду 2 клетки 3 и 4, в ряду 3 — клетки со 2-й по 5-ю, а в рядах 4 и 5 — по клетке 5. Получается 8 соединённых клеток и все четыре отмеченных края."]],""],[862,366,"1 2 3 4 5 22. Катя выписала все числа от 1 до 1000 «змей­ кой» в таблицу с пятью столбцами (см. рисунок). 10 9 8 7 6 Ее брат стер некоторые числа. Как могут вы­ 11 12 13 14 15 глядеть две соседние строки из получившейся 20 19 18 17 16 таблицы? 742 542 139",{"0":[55.0,211.1,31.3,31.3],"1":[314.8,211.1,31.1,31.3],"2":[574.6,211.1,31.3,31.3],"3":[55.0,304.4,28.4,31.3],"4":[314.8,304.4,31.6,31.3]},"E","Числовая змейка",[["Восстанови верхнюю строку","Если 271 стоит в первом столбце, строка идёт по возрастанию: 271, 272, 273, 274, 275."],["Прочитай нижнюю строку","Следующая строка идёт в другую сторону: 280, 279, 278, 277, 276. Число 277 на четвёртом месте, как в варианте Д."]],""],[862,136,"",{},"B","Шесть игровых дней",[["Поймай стык месяцев","Пусть четверг — 29-е число месяца с 31 днём. Тогда 29, 30, 31, 1, 2 и 3 подходят: чётные даты приходятся на пятницу и понедельник."],["Проверь семь дней","В любых семи днях подряд есть хотя бы три чётные даты, даже если на стыке месяцев идут два нечётных числа подряд. Понедельник и пятница разрешают только два чётных дня."]],""],[862,173,"",{},"D","Треугольники на сетке",[["Считай по длине стороны","Возьми сторону самого маленького треугольника за единицу. С горизонтальным основанием внизу получится 13 треугольников со стороной 1, 8 со стороной 2, 4 со стороной 3 и один со стороной 4."],["Посчитай перевёрнутые","Рисунок симметричен. Столько же треугольников имеют горизонтальное основание вверху. Всего 2 × (13 + 8 + 4 + 1) = 52."]],""],[862,221,"",{},"B","Книги в библиотеке",[["Сравни крайние догадки","Числа 1995 и 2015 отличаются на 20. Действительное число между ними: иначе ошибка одного из ребят была бы не меньше 20. Только ошибки 12 и 8 в сумме дают 20."],["Проверь оба числа","Возможны 2003 и 2007. При 2007 у Гены была бы ошибка 3, которой нет в списке. При 2003 самая маленькая ошибка у Бори: 2003 − 1998 = 5."]],""],[862,193,"",{},"B","Четверо едят торт",[["Представь одновременную работу","За время, отведённое каждому, остальные трое могли бы съесть половину торта. Так было для четырёх отрезков времени, значит, во всех таких тройках вместе получилось бы два торта."],["Добавь съеденный торт","Те, кто действительно ел в эти четыре отрезка, съели ещё один торт. Значит, если бы все четверо ели одновременно всё это время, они съели бы три торта, а на один ушло бы в три раза меньше времени."]],""]]],[2011,"3–4 классы",[[828,157,"",{},"B","Последняя буква",[["Посчитай буквы","В слове КЕНГУРУ семь букв. Первую Вася пишет в среду."],["Дойди до седьмой","За средой идут четверг, пятница, суббота, воскресенье, понедельник и вторник. Последняя буква приходится на вторник."]],""],[828,186,"",{},"C","Равновесие камней",[["Сложи камни на каждой чаше","Слева 26 + 8 + 12 = 46 кг. Справа 20 + 17 = 37 кг."],["Найди недостающий вес","Чтобы гири уравновесились, справа нужен камень массой 46 − 37 = 9 кг."]],""],[828,187,"",{},"E","До отправления поезда",[["Сложи два отрезка","От пробуждения до настоящего момента прошло полтора часа. От настоящего момента до поезда ещё три с половиной часа."],["Сосчитай всё время","Полтора часа и три с половиной часа вместе дают 5 часов."]],""],[828,75,"",{},"B","Три произведения",[["Начни с умножения","Первое произведение равно 0, второе равно 220, третье равно 201."],["Закончи вычисление","Получается 0 + 220 − 201 = 19."]],""],[828,123,"",{},"C","Семь монет",[["Проверь пределы","Семь пятирублёвых монет дают 35 рублей, а семь десятирублёвых — 70."],["Заменяй по одной монете","Каждая замена пятирублёвой монеты на десятирублёвую добавляет 5 рублей. Из предложенных сумм подходит 45: это пять монет по 5 и две по 10."]],""],[828,134,"",{},"E","Клетки после сгиба",[["Сопоставь клетки","После сгиба клетка остаётся в своём ряду и попадает на то же расстояние от жирной линии с другой стороны."],["Проверь букву Д","Клетки А, Б, В и Г совпадают с закрашенными. Д находится в нижнем ряду во втором столбце от сгиба. Слева соответствующая клетка белая."]],""],[847,139,"",{},"B","Обход клякс",[["Посчитай минимальное число шагов","По прямым линиям сетки между А и В четыре шага вправо и четыре вниз. Если сделать только восемь шагов, придётся идти вправо и вниз, но оба эти направления у А перекрыты кляксой."],["Построй обход","От А иди на одну клетку влево, на две вниз и на две вправо, затем на одну вниз, на две вправо, на одну вниз и ещё на одну вправо. Длина пути равна 10."]],""],[847,183,"",{},"D","Кусочки торта",[["Разрежь оба торта","Один торт разделили на четыре части, каждую ещё на три кусочка. На двух тортах получилось 2 × 4 × 3 = 24 кусочка."],["Убери лишние кусочки","Вася съел один и ещё два остались. Гости получили 24 − 1 − 2 = 21 кусочек, по одному каждый. Гостей был 21."]],""],[847,125,"",{},"B","Карточка Маши",[["Отбери фигуры по форме","Из карточек круглой или треугольной формы подходят Б и Г."],["Проверь цвет","Круглая карточка Г белая. Треугольная Б серая, так что Маша говорила о ней."]],""],[847,164,"",{},"B","Одинаковые цифры на часах",[["Проверь часы","Четыре одинаковые цифры требуют, чтобы первые две цифры, обозначающие часы, совпадали. Между 07 и 23 это возможно только в 11 и 22 часов."],["Проверь минуты","Совпадение всех цифр получится два раза: в 11:11 и в 22:22."]],""],[847,153,"",{},"C","Площадь фигур",[["Считай целые клетки и половинки","По сетке можно посчитать площадь каждой фигуры. Две половинки клетки вдоль наклонных границ образуют целую клетку."],["Сравни площади","От А до Д получаются площади 10, 11, 12, 9 и 9 клеток. Больше всех фигура В: её середина занимает четыре клетки, а четыре угла добавляют ещё по две клетки."]],""],[847,125,"",{},"A","Вода в двух сосудах",[["Сравни части","Если в чайнике одна часть воды, то в кувшине пять таких частей. Четыре лишние части в кувшине — это 8 стаканов."],["Сложи объёмы","Одна часть равна 8 : 4 = 2 стаканам. Всего шесть частей, то есть 12 стаканов."]],""],[847,221,"",{},"C","Мышкин путь за сыром",[["Отмечай развилки","Закрой ветки, заканчивающиеся тупиком. На каждой оставшейся развилке попробуй все пути к выходу, зачёркивая клетки уже пройденного пути, чтобы никуда не возвращаться."],["Сравни длины","Если считать входную клетку и клетку выхода, возможны 17, 19, 21, 23, 25, 27, 29, 31, 33, 35 или 37 клеток. При подсчёте отмечай каждую длину, когда дойдёшь до выхода."],["Повтори самый длинный маршрут","Начни с верхней левой клетки: ↓ →→→ ↓↓ ← ↑ ← ↓ ← ↓↓ → ↓ → ↑↑ →→→ ↑↑ ← ↑↑ →→ ↓↓↓↓↓ ← ↓ →. На пути 36 переходов и 37 клеток с сыром."]],""],[828,183,"",{},"E","Баллы за викторину",[["Представь все правильные ответы","При десяти верных ответах Миша получил бы 10 + 10 = 20 баллов."],["Замени верные ответы ошибками","Каждая ошибка уменьшает итог на 2: вместо прибавления одного балла его вычитают. До 14 не хватает 6 баллов, значит, ошибок было 6 : 2 = 3."]],""],[828,206,"",{},"D","Разрезание на треугольной сетке",[["Выдели середину","Всего в большой фигуре 18 маленьких треугольников. В середине, там, где встречаются три шестиугольника, шесть треугольников образуют ещё один шестиугольник."],["Проверь деталь Г","Деталь Г состоит из шести треугольников, поэтому таких деталей понадобилось бы три. Приложи её к фигуре, поворачивая и переворачивая: всю деталь можно уложить внутри, только захватив не меньше трёх треугольников центрального шестиугольника."],["Сравни с серединой","Трём деталям Г нужно хотя бы 9 треугольников в середине, а там есть всего 6. Поэтому Г не подходит."]],""],[828,171,"",{},"A","Карточки 9, 8 и 9",[["Найди место для восьмёрки","Карточка с восьмёркой может стоять первой, второй или третьей. При перевороте восьмёрка остаётся восьмёркой."],["Выбери цифры на двух других местах","Каждую девятку можно оставить девяткой или перевернуть в шестёрку. Для двух мест есть четыре сочетания: 99, 96, 69 или 66. Всего 3 × 4 = 12 чисел."]],""],[828,181,"",{},"D","Кто сколько выбросил",[["Начни с Ани","Анино число делится на 2 и на 3, поэтому это 6. Тогда у Бори 3, у Вики 2."],["Раздай оставшиеся числа","Из 1, 4 и 5 только 4 в четыре раза больше 1. У Гриши 4, у Димы 1, у Егора 5."]],""],[828,180,"",{},"C","Кубики внутри изгороди",[["Сосчитай сторону ограды","Из 36 кубиков четыре угловых. Оставшиеся 32 распределяются поровну между четырьмя сторонами, по 8 между углами."],["Заполни середину","От одного угла до другого вместе с углами 10 кубиков. Внутри остаётся квадрат 8 на 8, для него нужны 64 кубика."]],""],[828,128,"",{},"C","Шумные и кусачие щенки",[["Сложи два подсчёта","Шумных щенков 9, кусачих 8. При сложении выходит 17, хотя в комнате только 12 щенков."],["Убери повторный подсчёт","Все 12 щенков посчитаны хотя бы раз. Тех, кто одновременно шумный и кусачий, посчитали дважды. Таких 17 − 12 = 5."]],""],[828,125,"",{},"B","Цифры по убыванию",[["Собери наибольшее число","Возьми три наибольшие разные цифры в порядке убывания: 9, 8, 7. Получится 987."],["Собери наименьшее число","Три наименьшие разные цифры — 0, 1 и 2. По убыванию они дают 210. Разность 987 − 210 = 777."]],""],[847,153,"",{},"E","Сумма в серых кружках",[["Сложи числа по сторонам","Четыре стороны дают 4 × 13 = 52. При этом углы засчитываются дважды, а серые кружки — по одному разу."],["Найди сумму углов и середины","Все числа от 1 до 8 дают 36. Разница 52 − 36 = 16 — это сумма углов, которые посчитали ещё раз. На серых кружках сумма равна 36 − 16 = 20."]],""],[847,133,"",{},"C","Месяц с пятью выходными",[["Найди начало и конец месяца","После четырёх недель остаётся самое большее три дня. Среди них должны быть и суббота, и воскресенье. Если их три, пятница или понедельник тоже повторились бы пять раз. Значит, лишних дней два, и месяц начался в субботу, а закончился в воскресенье."],["Посмотри на следующий месяц","После такого 30-дневного месяца идёт 31-дневный, начинающийся с понедельника. После четырёх недель остаются понедельник, вторник и среда. Вторников в нём будет пять."]],""],[847,255,"",{},"D","Столбик из кубиков",[["Найди пару скрытых граней","Верхняя и нижняя грани среднего кубика противоположны и в сумме дают 7. К ним приклеены такие же числа на соседних кубиках. Эта пара чисел не может появиться спереди ни на одном кубике."],["Проверь видимые тройки","Пары противоположных граней — 1 и 6, 2 и 5, 3 и 4. Только в тройке 1, 2, 5 есть свободная пара: 3 и 4. Ей и можно склеить столбик, повернув кубики нужными гранями вперёд."]],""],[847,208,"",{},"B","Коты обедают",[["Найди скорость каждого","Тоша съел 12 рыбок за 3 минуты, то есть 4 рыбки в минуту. Малыш ест по 2, а Яша — по одной рыбке в минуту."],["Посчитай, когда поели старшие","За первые 3 минуты Малыш съел 6 рыбок. Оставшиеся 6 они с Тошей съели вместе за минуту. Так прошло 4 минуты."],["Дождись Яши","Яше нужно 6 минут, чтобы съесть свои 6 рыбок. Старшие коты ждали его 6 − 4 = 2 минуты."]],""],[847,127,"",{},"D","Буква К в ребусе",[["Начни с двух последних столбцов","В единицах и десятках из разных цифр вычитают одну и ту же цифру О, а в итоге получается по 1. Без займа из десятков цифры G и N были бы одинаковыми. Значит, в единицах был заём: О = 9, G = 0. Тогда в десятках N = 1, с новым займом из сотен."],["Реши два старших столбца","В сотнях А − R − 1 должно дать ноль. Новый заём потребовал бы A = 0, R = 9, но эти цифры уже заняты. Поэтому А на 1 больше R. В тысячах К на 2 больше А, то есть на 3 больше R."],["Перебери значения","Для R подходят 2, 3, 4 и 5: тогда К равно 5, 6, 7 или 8. При R = 6 цифра К была бы 9, а большие R дают больше 9. Всего четыре значения."]],""],[847,125,"",{},"A","Вставка цифры в 2011",[["Посчитай места для вставки","Перед первой цифрой можно вставить одну из девяти цифр от 1 до 9. В четырёх других местах можно вставить любую цифру. Это 9 + 4 × 10 = 49 способов."],["Убери повторы","Добавленную 2 можно ставить до или после имеющейся 2, и выйдет одно и то же число. Так же с 0. Добавленная 1 рядом с двумя единицами даёт одно число тремя способами. Лишних способов 1 + 1 + 2 = 4, остаётся 45 чисел."]],""]]],[2012,"3–4 классы",[[834,129,"Саша рисует на плакате слова УРА КЕНГУРУ. Одинаковые буквы он рисует одним цветом, а разные буквы — разными цветами. Сколько различных цветов ему понадобится?",{"0":[51.8,95.6,30.8,25.8],"1":[201.8,95.6,30.8,25.8],"2":[351.8,95.6,30.8,25.8],"3":[501.3,95.6,28.0,25.8],"4":[651.3,95.6,34.2,25.8]},"B","Цвета букв на плакате",[["Выпиши разные буквы","В слове КЕНГУРУ есть К, Е, Н, Г, У и Р. Последняя У повторяется, поэтому цветов для этого слова нужно шесть."],["Добавь буквы из слова УРА","У и Р уже есть в списке. Добавится только А, и цветов станет семь."]],""],[834,131,"Один будильник спешит на 25 минут и показывает 7 часов 50 минут. Какое время показывает другой будильник, который отстает на 15 минут?",{"0":[51.8,68.5,30.8,25.8],"1":[301.6,68.5,30.8,25.8],"2":[551.5,68.5,30.8,25.8],"3":[51.8,97.9,28.0,25.8],"4":[301.6,97.9,31.4,25.8]},"A","Два будильника",[["Найди настоящее время","Первый будильник спешит на 25 минут. Когда он показывает 7:50, на самом деле 7:25."],["Узнай показание второго","Второй отстаёт на 15 минут. Он показывает 7:25 − 15 минут = 7:10."]],""],[834,163,"Только на одной из этих пяти картинок площадь закрашенной части не равна площади белой части. На какой?",{"0":[51.8,100.7,30.8,25.8],"1":[201.8,100.7,30.8,25.8],"2":[351.8,100.7,30.8,25.8],"3":[501.3,100.7,28.0,25.8],"4":[651.3,100.7,31.4,25.8]},"E","Площади белого и серого",[["Найди две закрашенные четверти","На рисунке Д серыми сделаны два из четырёх равных маленьких квадратов. Они уже занимают ровно половину большого квадрата."],["Прибавь круги","В двух белых квадратах закрашено ещё по кружку. Поэтому на рисунке Д серого больше половины. У других картинок перестановкой равных треугольников и кружков можно совместить белые и серые части."]],""],[834,102,"Три воздушных шарика стоят на 12 рублей больше, чем один шарик. Сколько стоит один шарик?",{"0":[51.8,68.5,30.8,25.8],"1":[201.8,68.5,30.8,25.8],"2":[351.8,68.5,30.8,25.8],"3":[501.3,68.5,28.0,25.8],"4":[651.3,68.5,31.4,25.8]},"B","Цена одного шарика",[["Вычти один шарик","Три шарика дороже одного на 12 рублей. Эта разница — цена двух шариков."],["Раздели стоимость","Один шарик стоит 12 : 2 = 6 рублей."]],""],[834,153,"На каком из рисунков клеточки A2, B1 и C3 закрашены?",{"0":[51.8,88.8,30.8,25.8],"1":[201.8,88.8,30.8,25.8],"2":[351.8,88.8,30.8,25.8],"3":[501.3,88.8,28.0,25.8],"4":[651.3,88.8,31.4,25.8]},"C","Адреса закрашенных клеток",[["Прочитай обозначения","Буква обозначает столбец, а цифра — ряд. А2 находится в первом столбце второго ряда, В1 — во втором столбце первого, С3 — в третьем столбце третьего."],["Проверь три клетки вместе","Только у сетки В одновременно закрашены все три нужные клетки."]],""],[834,128,"В школе для зверей учатся 3 котенка, 4 утенка, 2 гусенка и несколько щенков. Когда учитель пересчитал лапы всех своих учеников, получилось 44. Сколько щенков учится в школе?",{"0":[51.8,95.0,30.8,25.8],"1":[201.8,95.0,30.8,25.8],"2":[351.8,95.0,30.8,25.8],"3":[501.3,95.0,28.0,25.8],"4":[651.3,95.0,31.4,25.8]},"B","Щенки в звериной школе",[["Посчитай лапы остальных зверей","У трёх котят 12 лап, у четырёх утят и двух гусят ещё 6 × 2 = 12 лап. Вместе 24 лапы."],["Найди число щенков","Из 44 лап щенкам принадлежат 20. У каждого по 4 лапы, значит, щенков 5."]],""],[834,134,"",{"0":[51.8,41.5,30.8,25.8],"1":[351.8,41.5,30.8,25.8],"2":[51.8,70.8,30.8,25.8],"3":[352.4,70.8,28.0,25.8],"4":[51.8,100.7,31.4,25.8]},"C","Семь или шесть",[["Разберись с дюжиной","Дюжиной называют 12 штук. Полдюжины — это 12 : 2 = 6 штук."],["Сверь с другими вариантами","В неделе семь дней, в слове КЕНГУРУ семь букв, у радуги семь цветов. Номер этой задачи тоже 7. Отличается полдюжины."]],""],[855,162,"Плитки двух видов были выложены на стене в шахматном порядке. Несколько плиток упали со стены (см. рисунок). Сколько полосатых плиток упало?",{"0":[51.8,122.7,30.8,25.8],"1":[144.9,122.7,30.8,25.8],"2":[237.9,122.7,30.8,25.8],"3":[331.5,122.7,28.0,25.8],"4":[424.6,122.7,31.4,25.8]},"C","Упавшие полосатые плитки",[["Восстанови порядок","Клетки чередуются, как на шахматной доске. Во втором ряду пусты столбцы 4–7, и полосатыми должны быть 5-й и 7-й."],["Проверь остальные ряды","В третьем ряду полосатыми были пустые клетки 4 и 6, в четвёртом — 3, 5 и 7. Всего упало 2 + 2 + 3 = 7 полосатых плиток."]],""],[855,129,"Петя задумал число, прибавил к нему 3, сумму умножил на 50, снова прибавил 3, умножил результат на 4 и получил 2012. Какое число задумал Петя?",{"0":[51.8,95.6,30.8,25.8],"1":[201.3,95.6,30.8,25.8],"2":[351.3,95.6,30.8,25.8],"3":[501.3,95.6,28.0,25.8],"4":[651.3,95.6,31.4,25.8]},"D","Петино задуманное число",[["Отмени два последних действия","Вместо умножения на 4 раздели 2012 на 4 и получи 503. Вместо прибавления 3 вычти 3, останется 500."],["Дойди до начала","Раздели 500 на 50, получится 10. Вычти ещё 3. Петя задумал 7."]],""],[855,129,"В феврале 2012 года в зоопарке родился маленький кенгуру. Сегодня, 15 марта, ему исполняется 20 дней. В какой день он родился?",{"0":[51.8,68.5,30.8,25.8],"1":[301.6,68.5,30.8,25.8],"2":[551.5,68.5,30.8,25.8],"3":[51.8,95.6,28.0,25.8],"4":[301.6,95.6,31.4,25.8]},"D","День рождения кенгуру",[["Отступи до конца февраля","От 15 марта до 29 февраля проходит 15 дней. День 29 февраля был в 2012 году, потому что это високосный год."],["Отсчитай ещё пять дней","Чтобы вернуться на 20 дней, от 29 февраля отступи ещё на пять дней. Кенгуру родился 24 февраля."]],""],[855,183,"На лист бумаги Вася наклеил один за другим 5 одинаковых квадратов. Видимые части этих квадратов на рисунке помечены буквами. В каком порядке Вася наклеивал квадраты?",{"0":[51.8,122.1,30.8,25.8],"1":[301.6,122.1,30.8,25.8],"2":[551.5,122.1,30.8,25.8],"3":[51.8,149.2,28.0,25.8],"4":[301.6,149.2,31.4,25.8]},"E","Как наклеили квадраты",[["Сними верхний квадрат","Квадрат А виден целиком, поэтому был наклеен последним. Под ним видна нижняя полоска квадрата Д, значит, Д наклеили раньше А."],["Проследи остальные слои","Мысленно восстанови полные квадраты. Под Д проходит В, под В — Б, под Б — Г. Если читать от первого квадрата до последнего, получаем Г, Б, В, Д, А."]],""],[855,129,"Блоха прыгает по длинной лестнице. Она может прыгать или на 3 ступеньки вверх, или на 4 ступеньки вниз. За какое наименьшее число прыжков она может перебраться с земли на 22-ю ступеньку?",{"0":[51.8,95.0,30.8,25.8],"1":[201.3,95.0,30.8,25.8],"2":[351.3,95.0,30.8,25.8],"3":[501.3,95.0,28.0,25.8],"4":[651.3,95.0,31.4,25.8]},"D","Прыжки блохи",[["Сначала считай подъёмы","Семь прыжков вверх дают только 21 ступеньку. Восемь дали бы 24 ступеньки, девять — 27. Лишние 2 или 5 ступенек нельзя убрать прыжками по 4 вниз."],["Найди первый подходящий подъём","Десять прыжков вверх дают 30 ступенек. Два прыжка вниз убирают ровно 8 ступенек, и блоха оказывается на 22-й. Всего 12 прыжков. Если сделать больше десяти подъёмов, спусков понадобится как минимум три."]],""],[855,220,"Федя выложил правильную цепочку из семи доминошек (число точек в соседних квадратиках двух разных доминошек всегда одинаково). На всех доминошках вместе было 33 точки. Потом Федя забрал две доминошки из полученной цепочки (см. рисунок). Сколько точек было в квадратике, в котором стоит знак вопроса?",{"0":[51.8,183.6,30.8,25.8],"1":[131.3,183.6,30.8,25.8],"2":[211.4,183.6,30.8,25.8],"3":[291.5,183.6,28.0,25.8],"4":[371.6,183.6,31.4,25.8]},"C","Пропавшие доминошки",[["Посчитай оставшиеся точки","На видимых доминошках по порядку 3, 5, 8, 5 и 1 точка. Всего 22. На двух пропавших доминошках было 33 − 22 = 11 точек."],["Заполни соседние половинки","В крайней левой пустой половинке повторяется 1 с ближайшей костяшки. В крайней правой повторяется 2. На двух средних половинках поровну точек, а вместе 11 − 1 − 2 = 8. Значит, под вопросом 4 точки."]],""],[855,129,"За год до рождения Кати ее родителям вместе было 40 лет. Сколько сейчас лет Кате, если через 2 года ей и ее родителям вместе будет 90 лет?",{"0":[51.8,95.6,30.8,25.8],"1":[201.3,95.6,30.8,25.8],"2":[351.3,95.6,30.8,25.8],"3":[501.3,95.6,28.0,25.8],"4":[651.3,95.6,31.4,25.8]},"B","Возраст Кати",[["Дойди до рождения","За год до рождения Кати родителям вместе было 40 лет. К её рождению каждый стал старше на год, и сумма выросла до 42 лет."],["Посчитай семейные годы","С рождения Кати сумма возрастов растёт на 3 каждый год. До суммы 90 пройдёт (90 − 42) : 3 = 16 лет. Это будет через два года, так что сейчас Кате 14."]],""],[834,156,"Четвероклассница Маша и ее брат первоклассник Миша решали задачи конкурса «Кенгуру» для 3–4 классов. В результате оказалось, что Миша получил не 0 баллов, а Маша — не 100 баллов. На какое наибольшее число баллов Маша могла обогнать Мишу?",{"0":[51.8,122.7,30.8,25.8],"1":[201.8,122.7,30.8,25.8],"2":[351.8,122.7,30.8,25.8],"3":[501.3,122.7,28.0,25.8],"4":[651.3,122.7,31.4,25.8]},"B","Разница в баллах",[["Найди лучший результат Маши","За все задачи дают 100 баллов. Самая дешёвая задача стоит 3 балла, поэтому лучший результат ниже 100 — это 97."],["Найди наименьший результат Миши","Если Миша решил ровно одну трёхбалльную задачу, у него 3 балла. Самая большая разница — 97 − 3 = 94."]],""],[834,334,"У правильно идущих «странных» часов перепутаны стрелки (часовая, минутная и секундная). В 12 : 55 : 30 стрелки располагались так, как показано на рисунке справа. Что покажут эти часы в 20 часов 12 минут?",{"0":[105.4,300.9,30.8,25.8],"1":[258.2,300.9,30.8,25.8],"2":[411.6,300.9,30.8,25.8],"3":[561.7,300.9,28.0,25.8],"4":[711.7,300.9,31.4,25.8]},"A","Перепутанные стрелки",[["Определи, за что отвечает каждая стрелка","В 12:55:30 часовая стрелка почти дошла до 1, минутная направлена на 11, секундная на 6. На картинке у 1 длинная, у 11 короткая, у 6 средняя стрелка."],["Поставь их на 20:12:00","Длинная часовая немного дальше 8, короткая минутная немного дальше 2, средняя секундная у 12. Это картинка А."]],""],[834,155,"На рыбалку отправились пятеро мужчин из одной семьи: дедушка, 2 его сына и 2 внука. Их зовут: Борис Григорьевич, Григорий Викторович, Андрей Дмитриевич, Виктор Борисович, и Дмитрий Григорьевич. Как в детстве звали дедушку?",{"0":[51.8,122.1,30.8,25.8],"1":[224.4,122.1,30.8,25.8],"2":[373.3,122.1,30.8,25.8],"3":[501.3,122.1,28.0,25.8],"4":[651.3,122.1,31.4,25.8]},"D","Дедушка и внуки",[["Собери три поколения","Андрей Дмитриевич — сын Дмитрия. Дмитрий Григорьевич — сын Григория. Получается цепочка дедушка Григорий, сын Дмитрий, внук Андрей."],["Найди ещё сына и внука","Борис Григорьевич — второй сын Григория. Виктор Борисович — сын Бориса. В детстве дедушку Григория звали Гришей."]],""],[834,208,"Параллелепипед состоит из четырех частей. Каждая часть состоит из 4 кубиков одинакового цвета (см. рисунок). Какую форму имеет белая часть?",{"0":[51.8,146.8,30.8,25.8],"1":[188.3,146.8,30.8,25.8],"2":[358.0,146.8,30.8,25.8],"3":[511.5,146.8,28.0,25.8],"4":[650.2,146.8,31.4,25.8]},"E","Белая часть из кубиков",[["Найди видимые белые кубики","В верхнем дальнем ряду белые кубики находятся на втором и третьем местах слева. Остальные два белых кубика скрыты в нижнем дальнем ряду."],["Определи место тёмного кубика","У правой тёмной детали уже видны три кубика. Её четвёртый кубик примыкает к ней слева в нижнем дальнем ряду, под правым белым. Значит, скрытые белые стоят на первом и втором местах слева."],["Сопоставь ступеньку с рисунком","Верхняя пара сдвинута на один кубик вправо относительно нижней. Такая белая деталь показана в варианте Д."]],""],[834,156,"В футболе команда получает за победу 3 очка, за ничью — 1 очко, а за поражение — 0 очков. Команда сыграла 38 матчей и получила 80 очков. Какое наибольшее число раз эта команда могла проиграть?",{"0":[51.8,122.7,30.8,25.8],"1":[201.8,122.7,30.8,25.8],"2":[351.8,122.7,30.8,25.8],"3":[501.3,122.7,28.0,25.8],"4":[651.3,122.7,31.4,25.8]},"C","Футбольные поражения",[["Набери побольше очков за победы","Больше 26 побед быть не может: 27 побед дали бы уже 81 очко. С 26 победами набирается 78 очков, и нужны ещё две ничьи."],["Найди максимум поражений","При замене одной победы понадобятся три ничьи, чтобы вернуть её три очка. Тогда побед и ничьих вместе станет больше, а поражений меньше. При 26 победах и двух ничьих поражений 38 − 26 − 2 = 10."]],""],[834,134,"К пятизначному числу, сумма цифр которого равна 2, прибавили двузначное число. Получилось снова пятизначное число, сумма цифр которого равна 2. Какое число получилось?",{"0":[51.8,100.1,30.8,25.8],"1":[201.8,100.1,30.8,25.8],"2":[351.8,100.1,30.8,25.8],"3":[501.3,100.1,28.0,25.8],"4":[651.3,100.1,31.4,25.8]},"C","Два числа с суммой цифр 2",[["Выпиши пятизначные числа","Первая цифра ненулевая. Если это 2, остальные цифры нули. Если это 1, ещё одна единица стоит в одном из следующих разрядов. Список: 10001, 10010, 10100, 11000, 20000."],["Найди двузначную разность","Первые два числа отличаются на 9, следующие — на 90, потом на 900 и на 9000. Разность между первым и третьим уже 99, она тоже двузначная. В обоих случаях большее число — 10100."]],""],[855,210,"Недалеко от Венеции расположены три острова: Мурано, Бурано и Торчелло. Посетить Торчелло можно только побывав по дороге и на Мурано, и на Бурано. Каждый из 15 туристов посетил хотя бы один остров. При этом 5 человек посетили Торчелло, 13 человек побывали на Мурано и 9 человек — на Бурано. Сколько туристов посетили ровно два острова?",{"0":[51.8,176.8,30.8,25.8],"1":[201.3,176.8,30.8,25.8],"2":[351.3,176.8,30.8,25.8],"3":[501.3,176.8,28.0,25.8],"4":[651.3,176.8,31.4,25.8]},"A","Туристы на островах",[["Сосчитай тех, кто побывал на двух главных островах","Все 15 туристов побывали на Мурано или Бурано, поскольку на Торчелло нельзя попасть в обход обоих. Если сложить 13 и 9, туристов, побывавших на обоих островах, посчитали два раза."],["Убери тех, кто побывал на всех трёх","На обоих главных островах были 13 + 9 − 15 = 7 туристов. Из них пять побывали ещё и на Торчелло. Ровно два острова посетили 7 − 5 = 2 туриста."]],""],[855,223,"Бумажный кубик разрезали и развернули. Какие из фигур 1–5 могли получиться?",{"0":[51.8,162.2,30.8,25.8],"1":[301.6,162.2,30.8,25.8],"2":[551.5,162.2,30.8,25.8],"3":[51.8,189.2,28.0,25.8],"4":[301.6,189.2,31.4,25.8]},"C","Развёртки бумажного кубика",[["Замкни полоску","Четыре квадрата образуют боковые стенки. Два треугольника сверху должны закрыть верх, а два снизу — дно. На каждой стороне они должны стать двумя половинками квадрата."],["Проверь прямые углы","У половинок одного квадрата прямые углы лежат в противоположных вершинах. У развёртки 3 нижние треугольники получают прямые углы в одной вершине: там соединяются края первого и четвёртого квадратов. В остальных развёртках углы попарно противоположны. Подходят 1, 2, 4 и 5."]],""],[855,128,"Никита выбрал два трехзначных числа, у которых совпадают суммы цифр. От большего числа он отнял меньшее. Какое самое большое число мог получить Никита?",{"0":[51.8,95.0,30.8,25.8],"1":[201.3,95.0,30.8,25.8],"2":[351.3,95.0,30.8,25.8],"3":[501.3,95.0,28.0,25.8],"4":[651.3,95.0,31.4,25.8]},"B","Самая большая разность",[["Сравни сотни","Чтобы получить разность больше 801, цифры сотен должны отличаться хотя бы на 8. При разнице в 7 сотен даже прибавка 99 даст не больше 799. Разница в 8 сотен возможна только между 9 и 1."],["Уравняй суммы цифр","Тогда у меньшего числа сумма десятков и единиц на 8 больше. В единицах разница не больше 9, поэтому у меньшего числа десятков может быть не более чем на один меньше. Наибольшая разность получается при одном лишнем десятке и девяти недостающих единицах у большего числа: 800 + 10 − 9 = 801."],["Подбери пример","910 − 109 = 801, и суммы цифр обоих чисел равны 10."]],""],[855,210,"В полдень из столицы в город А вышли скороход и торговец. Одновременно по той же дороге навстречу им из А вышел отряд стражников. Через час стражники встретили скорохода, еще через 2 часа они встретили торговца, а еще через 3 часа стражники прибыли в столицу. Во сколько раз быстрее торговца идет скороход?",{"0":[51.8,176.2,30.8,25.8],"1":[164.6,176.2,30.8,25.8],"2":[278.0,176.2,30.8,25.8],"3":[391.3,176.2,28.0,25.8],"4":[501.3,176.2,31.4,25.8]},"D","Скороход, торговец и стражники",[["Восстанови путь стражников","От города А до столицы стражники шли 1 + 2 + 3 = 6 часов. Через час до столицы оставалось пять их часовых отрезков, а через три часа — три."],["Сравни пути за час","Скороход прошёл пять таких отрезков за час. Торговец прошёл три таких отрезка за три часа, то есть один за час. Скороход идёт в пять раз быстрее."]],""],[855,177,"",{},"D","Квадраты на толстых линиях",[["Отметь возможные края","Если считать в мелких клетках от левого края, вертикальные толстые линии проходят на отметках 0, 1, 2, 4, 6, 7 и 8. Те же отметки сверху вниз у горизонтальных линий. Квадрату нужны две пары краёв с одинаковым расстоянием между ними."],["Считай по длине стороны","Для длин 1, 2, 3, 4, 5, 6, 7 и 8 число пар линий равно 4, 4, 2, 3, 2, 3, 2 и 1. Для каждой длины можно независимо выбрать горизонтальную и вертикальную пары. Получается 16 + 16 + 4 + 9 + 4 + 9 + 4 + 1 = 63 квадрата."]],""],[855,153,"В равенстве КЕН = ГУ × РУ разными буквами обозначены разные ненулевые цифры, а одинаковыми буквами — одинаковые цифры. Найдите Е, если известно, что число КЕН — самое маленькое из возможных.",{"0":[51.8,120.4,30.8,25.8],"1":[201.3,120.4,30.8,25.8],"2":[351.3,120.4,30.8,25.8],"3":[501.3,120.4,28.0,25.8],"4":[651.3,120.4,31.4,25.8]},"B","Наименьшее КЕН",[["Найди удачное произведение","17 × 27 = 459. Шесть цифр 1, 2, 7, 4, 5 и 9 различны и ненулевые. Проверь, может ли произведение быть меньше 459."],["Перебери цифру единиц множителей","Обе единицы равны У. При У = 1, 5 или 6 той же цифрой оканчивается произведение, что запрещено. При У от 7 до 9 даже самые маленькие разные множители дают не меньше 17 × 27 = 459."],["Проверь оставшиеся произведения","Для У = 2, 3 или 4 меньше 459 дают только 12 × 32 = 384, 13 × 23 = 299 и 14 × 24 = 336. У каждого есть повтор цифры среди разных букв. Поэтому минимум 459, а Е = 5."]],""]]],[2013,"3–4 классы",[[834,103,"Какую из букв слова КЕНГА можно написать, не отрывая карандаша от бумаги и не проходя по одной линии дважды?",{},"D","Буква одним росчерком",[["Найди угол","У буквы Г два отрезка, и они соединены в одном углу."],["Проведи линию","Начни со свободного конца одного отрезка, пройди через угол и закончи на другом конце."]],""],[834,103,"В равенстве 4 ● + 5 ● = 104 символом ● заменена одна и та же цифра. Какая?",{"0":[51.8,69.1,31.6,26.5],"1":[178.1,69.1,31.6,26.5],"2":[294.9,69.1,31.6,26.5],"3":[411.6,69.1,28.8,26.5],"4":[528.4,69.1,31.6,26.5]},"E","Одинаковые цифры",[["Отдели десятки","Числа начинаются с 4 и с 5, поэтому их десятки дают 40 + 50 = 90."],["Найди единицы","До 104 не хватает 14. Две одинаковые цифры дают 14, значит, каждая равна 7."]],""],[834,177,"",{},"C","Поиск квадрата",[["Рассмотри рисунок","Круги видны на мордочке, треугольники — у ушей и лап, а шестиугольник образует контур головы."],["Сравни прямоугольники","Прямоугольные детали вытянуты в высоту. Фигуры с четырьмя равными сторонами и прямыми углами здесь нет."]],""],[834,103,"Миша измерил длины пяти палочек и записал результаты этих измерений. Какой из результатов А–Д самый большой?",{"0":[51.8,68.5,31.6,26.5],"1":[228.3,68.5,31.6,26.5],"2":[411.6,68.5,31.6,26.5],"3":[561.7,68.5,28.8,26.5],"4":[677.8,68.5,31.6,26.5]},"A","Длины палочек",[["Переведи в миллиметры","В дециметре 100 мм, а в сантиметре 10 мм. Поэтому 3 дм 2 см — это 320 мм."],["Сравни","Другие длины равны 37, 35, 30 и 302 мм. Больше всего 320 мм."]],""],[834,238,"Пятеро мальчиков обсуждали свойства числа 325. Андрей: «Это трехзначное число». Боря: «Все цифры этого числа различны». Витя: «Сумма его цифр равна 10». Гриша: «Цифра единиц равна 5». Даня: «Все его цифры нечетны». Кто из мальчиков ошибся?",{"0":[51.8,203.9,31.6,26.5],"1":[201.8,203.9,31.6,26.5],"2":[351.8,203.9,31.6,26.5],"3":[501.3,203.9,28.8,26.5],"4":[651.3,203.9,31.6,26.5]},"E","Цифры числа 325",[["Проверь число","Цифры 3, 2 и 5 различны, их сумма равна 10, а последняя цифра — 5."],["Проверь чётность","Цифра 2 чётная. Значит, ошибся Даня."]],""],[834,102,"У Пети было 36 конфет. Он раздал все конфеты гостям поровну. Сколько гостей у него могло быть?",{"0":[51.8,68.5,31.6,26.5],"1":[201.8,68.5,31.6,26.5],"2":[351.8,68.5,31.6,26.5],"3":[501.3,68.5,28.8,26.5],"4":[651.3,68.5,31.6,26.5]},"B","Конфеты поровну",[["Что означает «поровну»?","Число конфет должно делиться на количество гостей без остатка."],["Проверь варианты","36 = 6 × 6. Значит, гостей могло быть шестеро, и каждый получил бы по 6 конфет."]],""],[834,236,"Прямоугольное зеркало разбилось. Какой кусочек выпал?",{"0":[51.8,91.1,31.6,26.5],"1":[261.6,91.1,31.6,26.5],"2":[478.2,91.1,31.6,26.5],"3":[51.8,202.8,28.8,26.5],"4":[261.6,202.8,31.6,26.5]},"B","Осколок зеркала",[["Найди внешние края","В пустом месте зеркала надо восстановить кусочек нижнего края и кусочек левого края. Они образуют прямой угол."],["Сопоставь контур","От концов этих краёв две наклонные линии сходятся в точке, где сошлись трещины. Так устроен осколок Б."]],""],[855,157,"Когда Буратино врет, его нос удлиняется на 6 см. Когда он говорит правду, его нос становится короче на 2 см. Утром длина его носа была 9 см. За день он три раза соврал и два раза сказал правду. Какой длины стал нос у Буратино к вечеру?",{"0":[51.8,123.2,31.6,26.5],"1":[201.8,123.2,31.6,26.5],"2":[351.8,123.2,31.6,26.5],"3":[501.3,123.2,28.8,26.5],"4":[651.3,123.2,31.6,26.5]},"D","Нос Буратино",[["Посчитай прибавку","Три раза по 6 см дают прибавку 18 см."],["Учти правду","Два раза по 2 см означают, что надо вычесть 4 см. К вечеру длина стала 9 + 18 − 4 = 23 см."]],""],[855,272,"Аня зашла в парк и пошла по аллее в направлении, указанном стрелочкой. На каждом перекрестке она поворачивала направо или налево. Сначала Аня повернула направо, затем налево, потом опять налево, затем направо, потом еще раз направо и дошла до следующего перекрестка. В каком месте оказалась Аня?",{"0":[51.8,234.3,31.6,26.5],"1":[156.1,234.3,31.6,26.5],"2":[261.0,234.3,31.6,26.5],"3":[365.9,234.3,28.8,26.5],"4":[471.4,234.3,31.6,26.5]},"D","Путь по аллеям",[["Следи за направлением","От входа Аня идёт вверх. После первых трёх поворотов она идёт вправо, вверх и влево."],["Дойди до перекрёстка","Теперь два правых поворота ведут вверх и вправо. Следующий перекрёсток — Г."]],""],[855,129,"В этом году конкурс «Кенгуру» проводится в России в двадцатый раз. Федин папа участвовал в самом первом конкурсе, когда учился в десятом классе. Сколько лет ему может быть сейчас?",{"0":[51.8,95.6,31.6,26.5],"1":[201.8,95.6,31.6,26.5],"2":[351.8,95.6,31.6,26.5],"3":[501.3,95.6,28.8,26.5],"4":[651.3,95.6,31.6,26.5]},"C","Первый конкурс",[["Сколько прошло лет?","От первого конкурса до двадцатого прошло 19 лет."],["Проверь возраст","37 − 19 = 18. В 18 лет можно учиться в десятом классе. У остальных вариантов возраст в год первого конкурса слишком мал или слишком велик."]],""],[855,75,"Сколько чисел между 20 и 30 делятся на свою последнюю цифру?",{"0":[51.8,41.5,31.6,26.5],"1":[201.8,41.5,31.6,26.5],"2":[351.8,41.5,31.6,26.5],"3":[501.3,41.5,28.8,26.5],"4":[651.3,41.5,31.6,26.5]},"C","Деление на последнюю цифру",[["Убери единицы","Число между 20 и 30 состоит из 20 и последней цифры. Последняя цифра делится сама на себя, поэтому достаточно проверить, делится ли на неё 20."],["Посчитай делители","Из цифр от 1 до 9 подходят 1, 2, 4 и 5. Получаются четыре числа: 21, 22, 24 и 25."]],""],[855,129,"22 марта Наташа сказала: «Позавчера оставалась неделя до моего дня рождения». Когда она будет вспоминать, что неделю назад был ее день рождения?",{"0":[51.8,95.6,31.6,26.5],"1":[201.8,95.6,31.6,26.5],"2":[351.8,95.6,31.6,26.5],"3":[501.3,95.6,28.8,26.5],"4":[651.3,95.6,31.6,26.5]},"D","День рождения Наташи",[["Отсчитай до праздника","Позавчера от 22 марта — 20 марта. Ещё семь дней — 27 марта, день рождения Наташи."],["Отсчитай после праздника","До 31 марта остаётся четыре дня, а ещё три приходятся на апрель. Значит, через неделю будет 3 апреля."]],""],[855,156,"Саша хочет закрасить несколько квадратиков на рисунке так, чтобы среди них никакие два не имели общей стороны. Какое наибольшее число квадратиков сможет закрасить Саша?",{"0":[51.8,122.7,31.6,26.5],"1":[201.8,122.7,31.6,26.5],"2":[351.8,122.7,31.6,26.5],"3":[501.3,122.7,28.8,26.5],"4":[651.3,122.7,31.6,26.5]},"B","Квадратики без соседей",[["Ограничь число","В горизонтальном ряду шесть клеток. Разбей их на три соседние пары. В каждой паре можно закрасить максимум одну клетку, а вне ряда есть ещё четыре клетки."],["Построй пример","Закрась все четыре клетки над и под рядом. В ряду можно взять первую, третью и шестую клетки слева. Получится 7."]],""],[855,140,"В марте кот Тоша проспал ровно 2 недели. Сколько часов он бодрствовал в этом месяце?",{"0":[51.8,70.2,31.6,26.5],"1":[311.8,70.2,31.6,26.5],"2":[578.0,70.2,31.6,26.5],"3":[51.8,105.8,28.8,26.5],"4":[311.8,105.8,31.6,26.5]},"E","Сон кота Тоши",[["Посчитай дни","В марте 31 день, из них кот спал 2 × 7 = 14 дней. Значит, он бодрствовал 31 − 14 = 17 суток."],["Переведи в часы","В сутках 24 часа. Подходит запись (31 − 7 × 2) × 24."]],""],[834,184,"Одноклассники Тони, Бетти, Кэтти и Энди родились в один год. Их дни рождения: 20 февраля, 12 апреля, 12 мая и 25 мая. Дни рождения Бетти и Энди в одном месяце, а дни рождения Энди и Кэтти приходятся на одно число. Кто из детей самый старший?",{"0":[51.8,123.2,31.6,26.5],"1":[201.8,123.2,31.6,26.5],"2":[351.8,123.2,31.6,26.5],"3":[501.3,123.2,28.8,26.5],"4":[51.8,149.7,31.6,26.5]},"A","Кто родился раньше?",[["Найди майские дни","Только в мае есть два дня рождения. Значит, Бетти и Энди родились в мае."],["Определи оставшиеся даты","У Энди тот же номер дня, что у Кэтти, значит, это 12 мая и 12 апреля. Тони родился 20 февраля и старше всех."]],""],[834,156,"В квадратной коробке в два слоя уложены одинаковые квадратные шоколадки. Кирилл съел все 20 шоколадок, которые лежали в верхнем слое вдоль стенок коробки. Сколько шоколадок было в этой коробке сначала?",{"0":[51.8,122.7,31.6,26.5],"1":[201.8,122.7,31.6,26.5],"2":[351.8,122.7,31.6,26.5],"3":[501.3,122.7,28.8,26.5],"4":[651.3,122.7,31.6,26.5]},"D","Шоколадки в два слоя",[["Посчитай стороны","Краевые шоколадки можно разложить на четыре одинаковые группы, по одной на каждую стенку. В каждую группу включи только один угол. Получится 20 : 4 = 5."],["Восстанови коробку","Вдоль каждой стенки 6 шоколадок, если считать оба угла. В двух слоях было 2 × 6 × 6 = 72 шоколадки."]],""],[834,130,"Отцу сейчас 33 года, а его трем сыновьям 5, 6 и 10 лет. Через сколько лет трем сыновьям вместе будет столько же лет, сколько будет отцу?",{"0":[51.8,95.6,31.6,26.5],"1":[201.8,95.6,31.6,26.5],"2":[351.8,95.6,31.6,26.5],"3":[501.3,95.6,28.8,26.5],"4":[651.3,95.6,31.6,26.5]},"B","Отец и сыновья",[["Найди разницу","Сыновьям вместе 5 + 6 + 10 = 21 год, а отцу 33 года. Разница — 12 лет."],["Проследи, как она меняется","За год общий возраст сыновей увеличивается на 3 года, а возраст отца — на 1. Разница уменьшается на 2 года за год и исчезнет через 6 лет."]],""],[834,247,"У Кати есть 6 деталей, изображенных на рисунке. Из пяти деталей она сложила 2 фигуры: прямоугольник, одна из сторон которого равна 6, и квадрат. Какая деталь оказалась лишней?",{"0":[51.8,174.0,31.6,26.5],"1":[268.4,174.0,31.6,26.5],"2":[444.9,174.0,31.6,26.5],"3":[651.3,174.0,28.8,26.5],"4":[51.8,212.3,31.6,26.5]},"A","Квадрат и прямоугольник",[["Собери квадрат","Две детали по две клетки положи одна над другой. Получится квадрат 2 × 2."],["Собери прямоугольник","Из двух уголков по три клетки можно сложить блок 2 × 3. Приложи к нему блок из шести клеток. Получится прямоугольник 2 × 6, а полоска из четырёх клеток останется."]],""],[834,130,"Мама купила трем своим детям 17 маленьких пирожных. Миша съел в два раза больше пирожных, чем Маша, а Даша съела больше Маши, но меньше Миши. Сколько пирожных съела Даша?",{"0":[51.8,95.6,31.6,26.5],"1":[165.2,95.6,31.6,26.5],"2":[278.0,95.6,31.6,26.5],"3":[391.3,95.6,28.8,26.5],"4":[501.3,95.6,31.6,26.5]},"B","Семнадцать пирожных",[["Выбери число для Маши","Если Маша съела не больше 3, то Миша съел не больше 6 и Даша — не больше 5. До 17 не хватит. Если Маша съела хотя бы 5, Миша съел не меньше 10, а Даша — хотя бы 6. Это уже больше 17."],["Проверь остаток","Маша съела 4 пирожных, а Миша — 8. Даше осталось 17 − 4 − 8 = 5, что подходит по условию."]],""],[834,124,"Сколько треугольников на рисунке?",{"0":[51.8,79.3,31.6,26.5],"1":[165.2,79.3,31.6,26.5],"2":[278.0,79.3,31.6,26.5],"3":[391.3,79.3,28.8,26.5],"4":[501.3,79.3,31.6,26.5]},"E","Треугольники на рисунке",[["Считай с горизонтальным основанием","У верхней перекладины 4 треугольника, у средней — 5, а у нижней стороны, включая её половины, — 3."],["Добавь наклонные","У перекрещённых линий есть по одному боковому треугольнику слева и справа. Ещё два треугольника идут от верхней вершины вдоль одной из перекрещённых линий. Всего 4 + 5 + 3 + 2 + 2 = 16."]],""],[834,156,"Из детей, которые пришли в гости к Наде, больше половины были мальчики. Больше трети мальчиков звали Федя. Всего среди гостей было три Феди. Какое наибольшее количество детей могло быть в гостях у Нади?",{"0":[51.8,122.7,31.6,26.5],"1":[201.8,122.7,31.6,26.5],"2":[351.8,122.7,31.6,26.5],"3":[501.3,122.7,28.8,26.5],"4":[651.3,122.7,31.6,26.5]},"D","Гости Нади",[["Ограничь число мальчиков","Три Феди — больше трети мальчиков. При 9 мальчиках 3 было бы ровно третью, значит, мальчиков не больше 8."],["Проверь максимум","Чтобы мальчики были в большинстве, при 8 мальчиках девочек может быть максимум 7. Всего тогда 15 детей."]],""],[855,294,"У Васи есть 7 доминошек, которые изображены на рисунке. Он хочет выложить их в линию, следуя обычным правилам игры в домино (в соседних квадратах двух соседних доминошек должно быть одинаковое количество точек). Какое наибольшее количество доминошек может быть в такой линии?",{"0":[51.8,260.3,31.6,26.5],"1":[201.8,260.3,31.6,26.5],"2":[351.8,260.3,31.6,26.5],"3":[501.3,260.3,28.8,26.5],"4":[651.3,260.3,31.6,26.5]},"C","Цепочка домино",[["Посчитай половинки","У каждого числа от 1 до 6 нечётное число половинок. Внутри цепочки половинки с одинаковыми числами идут парами, поэтому нечётных чисел может быть максимум два — на концах."],["Проверь шесть костяшек","Если убрать одну костяшку, нечётными останутся четыре числа. Значит, из шести и из семи костяшек цепочки нет."],["Построй цепочку","Пять костяшек соединяются так: 6–2, 2–1, 1–3, 3–4, 4–5."]],""],[855,130,"50 мальчиков и 36 девочек встали в круг, держась за руки. Ровно у 26 мальчиков соседка справа — девочка. У скольких мальчиков соседка слева — девочка?",{"0":[53.5,95.6,31.6,26.5],"1":[204.6,95.6,31.6,26.5],"2":[358.0,95.6,31.6,26.5],"3":[501.3,95.6,28.8,26.5],"4":[651.3,95.6,31.6,26.5]},"D","Соседи в кругу",[["Разбей круг на группы","Иди по кругу в одном направлении. Каждый переход от мальчика к девочке начинает новую группу девочек."],["Сравни переходы","В конце каждой такой группы снова стоит мальчик. Поэтому переходов между мальчиками и девочками в каждую сторону поровну — по 26."]],""],[855,136,"Крошка Ру умеет писать только две цифры: 1 и 7. Он хочет написать несколько чисел, сумма которых равна 2013. Какое наименьшее количество чисел ему придется написать?",{"0":[51.8,102.4,31.6,26.5],"1":[201.8,102.4,31.6,26.5],"2":[351.8,102.4,31.6,26.5],"3":[501.3,102.4,28.8,26.5],"4":[651.3,102.4,31.6,26.5]},"B","Числа из единиц и семёрок",[["Докажи, что двух мало","Число 2013 нельзя записать одними цифрами 1 и 7. Любое разрешённое число нечётное, а сумма двух нечётных чётная."],["Сложи три числа","1771 + 171 + 71 = 2013. Все три числа подходят."]],""],[855,292,"Из большого покрашенного куба Катя вырезала 4 маленьких кубика. Затем она сделала отпечатки всех покрашенных граней новой фигуры. Сколько из следующих пяти картинок у нее получилось?",{"0":[51.8,258.0,31.6,26.5],"1":[201.8,258.0,31.6,26.5],"2":[351.8,258.0,31.6,26.5],"3":[501.3,258.0,28.8,26.5],"4":[651.3,258.0,31.6,26.5]},"D","Отпечатки куба",[["Смотри только на наружные грани","Белые стенки выемок не окрашены. Для отпечатка каждой грани начни с квадрата 3 × 3 и убери клетки вырезанных кубиков."],["Сравни видимые грани","На правой грани вырезано три угла. Она даёт второй отпечаток. На левой грани вырезаны два противоположных угла. Она даёт третий отпечаток."],["Проверь другие стороны","На нижней грани вырезаны два угла вдоль одного края. Это первый отпечаток. На одной из задних граней вырезан только один угол. Это четвёртый отпечаток. Для креста понадобилось бы убрать все четыре угла одной грани, а такой грани нет."]],""],[855,163,"Какое наименьшее количество карточек с цифрами (по одной цифре на каждой) надо иметь, чтобы можно было выложить любые четыре различных числа от 1 до 300 одновременно? (Карточки с цифрой 6 можно использовать и для обозначения цифры 9.)",{"0":[51.8,129.4,31.6,26.5],"1":[201.8,129.4,31.6,26.5],"2":[351.8,129.4,31.6,26.5],"3":[501.3,129.4,28.8,26.5],"4":[651.3,129.4,31.6,26.5]},"B","Карточки с цифрами",[["Ищи самые трудные четвёрки","Для каждой цифры выбери четыре числа, в которых она встречается чаще всего. Например, 100, 200, 300 и 10 требуют 7 нулей, а 111 и три числа с двумя единицами требуют 9 единиц."],["Сложи запасы","Для 1 и 2 нужно по 9 карточек. Для 6 и 9 хватит 8 общих, например для 66, 69, 96, 99. Для 0, 3, 4, 5, 7 и 8 нужно по 7. Всего 9 + 9 + 8 + 6 × 7 = 68."]],""]]],[2014,"3–4 классы",[[834,130,"Боря выложил из одинаковых палочек слово КЕНГУРУ. Сколько букв сложены из 5 палочек?",{},"B","Слово из палочек",[["Считай по буквам","Буква К состоит из четырёх палочек, Г и обе буквы У — из трёх каждая."],["Найди пятёрки","По пять палочек понадобилось для Е, Н и Р. Таких букв три."]],""],[834,125,"Как в математике называется число, которое вычитают?",{"0":[51.8,37.5,31.6,26.5],"1":[328.2,37.5,31.6,26.5],"2":[51.8,64.0,31.6,26.5],"3":[328.2,64.0,28.8,26.5],"4":[51.8,91.1,31.6,26.5]},"E","Название числа",[["Возьми пример","В записи 9 − 4 = 5 число 4 вычитают из 9."],["Назови число","Число 4 называется вычитаемым. 9 — уменьшаемое, 5 — разность."]],""],[834,236,"(В) вычитываемое (Г) вычитающееся (Д) вычитаемое 3. Как выглядит центральная часть звезды, изображенной на рисунке справа?",{},"D","Середина звезды",[["Посчитай лучи","Мысленно обведи маленький круг с тем же центром. Каждый луч звезды пересечёт этот круг."],["Найди рисунок","У звезды девять лучей. Столько же светлых лучей в варианте Г."]],""],[834,71,"Во сколько раз 10 метров больше 1 мм?",{"0":[51.8,36.9,31.6,26.5],"1":[201.8,36.9,31.6,26.5],"2":[351.8,36.9,31.6,26.5],"3":[501.3,36.9,28.8,26.5],"4":[651.3,36.9,31.6,26.5]},"B","Метры и миллиметры",[["Переведи один метр","В метре 100 сантиметров, а в каждом сантиметре 10 миллиметров. Значит, 1 м = 1000 мм."],["Переведи десять метров","В 10 м ровно 10 000 миллиметров. Это в 10 000 раз больше 1 мм."]],""],[834,184,"Аня хочет вставить цифру 3 в число 2014 так, чтобы получившееся пятизначное число было как можно меньше. Где она должна написать цифру 3?",{"0":[51.8,95.6,31.6,26.5],"1":[351.8,95.6,31.6,26.5],"2":[51.8,122.7,31.6,26.5],"3":[351.8,122.7,28.8,26.5],"4":[51.8,149.7,31.6,26.5]},"D","Куда вставить тройку?",[["Сохрани начало","Цифра 3 больше 2, 0 и 1, поэтому при вставке перед любой из этих цифр число станет больше, чем при вставке после них."],["Сравни два окончания","Цифра 3 меньше 4. Число 20134 меньше 20143, поэтому тройку лучше поставить между 1 и 4."]],""],[834,177,"Андрей написал правильный пример, а его младший брат заклеил бумажными кружочками все знаки действий. Получилось: 1 m 6 m 1 m 2 m 4 = 6. В каком порядке могли стоять знаки в этом примере?",{"0":[51.8,143.5,31.6,26.5],"1":[201.8,143.5,31.6,26.5],"2":[351.8,143.5,31.6,26.5],"3":[501.3,143.5,28.8,26.5],"4":[651.3,143.5,31.6,26.5]},"C","Знаки в примере",[["Сложи все числа","Если везде поставить плюс, получится 1 + 6 + 1 + 2 + 4 = 14."],["Измени последний знак","Когда +4 заменяем на −4, сумма уменьшается на 8. Получается 1 + 6 + 1 + 2 − 4 = 6."]],""],[842,135,"Паша бросает дротики в мишень, изображенную справа. Сколько очков он не мог набрать за два броска?",{"0":[51.8,100.9,31.6,26.5],"1":[161.8,100.9,31.6,26.5],"2":[278.0,100.9,31.6,26.5],"3":[394.7,100.9,28.8,26.5],"4":[511.4,100.9,31.6,26.5]},"C","Два броска",[["Посмотри на очки","За один бросок дают 30, 50 или 70 очков. Это 3, 5 или 7 десятков, то есть нечётное число десятков."],["Сложи десятки","Сумма двух нечётных чисел чётная. 90 — это 9 десятков, поэтому набрать 90 за два броска нельзя."]],""],[842,98,"Никита выписал числа от 1 до 31. На сколько больше он написал единиц, чем троек?",{"0":[51.8,64.0,31.6,26.5],"1":[201.8,64.0,31.6,26.5],"2":[351.8,64.0,31.6,26.5],"3":[501.3,64.0,28.8,26.5],"4":[651.3,64.0,31.6,26.5]},"B","Единицы и тройки",[["Посчитай единицы","В числах от 10 до 19 есть 10 единиц в разряде десятков. Ещё четыре единицы стоят в конце чисел 1, 11, 21 и 31. Всего 14."],["Посчитай тройки","Тройки стоят на конце чисел 3, 13 и 23, а ещё в начале чисел 30 и 31. Всего 5. Разница 14 − 5 = 9."]],""],[842,167,"Прямоугольник согнули пополам по жирной линии. Какая цифра оказалось не закрытой закрашенным квадратиком?",{"0":[51.8,93.9,31.6,26.5],"1":[201.8,93.9,31.6,26.5],"2":[351.8,93.9,31.6,26.5],"3":[51.8,125.5,28.8,26.5],"4":[201.8,125.5,31.6,26.5]},"C","Сгиб по линии",[["Отрази квадратики","При сгибе один столбец накладывается на тот же столбец. Самый близкий к сгибу нижний ряд накроет ближайший верхний ряд, следующий — следующий и так далее."],["Проверь цифру 6","Цифра 6 стоит во втором ряду над сгибом. В том же столбце второго ряда под сгибом клетка белая, поэтому цифра останется видна."]],""],[842,127,"Адам собрал меньше орехов, чем Мартин, но больше, чем Сьюзен. Дана собрала больше, чем Мартин, и меньше, чем Люси. Кто из них собрал больше всего орехов?",{"0":[51.8,93.3,31.6,26.5],"1":[201.8,93.3,31.6,26.5],"2":[351.8,93.3,31.6,26.5],"3":[501.3,93.3,28.8,26.5],"4":[651.3,93.3,31.6,26.5]},"A","Кто собрал больше орехов?",[["Построй цепочку","Сьюзен собрала меньше Адама, а Адам — меньше Мартина."],["Продолжи сравнение","Мартин собрал меньше Даны, а Дана — меньше Люси. Значит, больше всех собрала Люси."]],""],[842,125,"На планете Кенгуру один год состоит из 20 месяцев, а каждый месяц — из 6 недель. Четверть года у кенгурят каникулы. Сколько недель продолжаются каникулы?",{"0":[51.8,91.1,31.6,26.5],"1":[201.8,91.1,31.6,26.5],"2":[351.8,91.1,31.6,26.5],"3":[501.3,91.1,28.8,26.5],"4":[651.3,91.1,31.6,26.5]},"E","Каникулы на планете Кенгуру",[["Возьми четверть","Четверть от 20 месяцев — это 20 : 4 = 5 месяцев."],["Посчитай недели","В каждом месяце 6 недель, так что каникулы длятся 5 × 6 = 30 недель."]],""],[842,126,"Семеро детей сидят за круглым столом. Никакие два мальчика не сидят рядом, и никакие три девочки не сидят подряд. Сколько девочек за столом?",{"0":[51.8,91.7,31.6,26.5],"1":[201.8,91.7,31.6,26.5],"2":[351.8,91.7,31.6,26.5],"3":[501.3,91.7,28.8,26.5],"4":[651.3,91.7,31.6,26.5]},"C","Дети за круглым столом",[["Отдели мальчиков","Между соседними по кругу мальчиками должна сидеть хотя бы одна девочка. Поэтому мальчиков не больше трёх."],["Посмотри на промежутки","В каждом промежутке помещается максимум две девочки. Если мальчиков не больше двух, за столом всего не больше шести детей. Значит, мальчиков трое, а девочек четверо."]],""],[842,152,"Алиса заметила, что два месяца подряд 20-е число приходилось на четверг. Какой день недели будет 20-го числа в следующем за ними месяце?",{"0":[51.8,91.1,31.6,26.5],"1":[311.8,91.1,31.6,26.5],"2":[578.0,91.1,31.6,26.5],"3":[51.8,117.6,28.8,26.5],"4":[311.8,117.6,31.6,26.5]},"E","Три числа в календаре",[["Найди длину первого месяца","Между двумя четвергами прошло целое число недель. Среди обычных длин месяца только 28 дней делятся на 7, поэтому первым месяцем был февраль."],["Передвинься на три дня","За вторым 20-м числом идёт месяц длиной 31 день — март. Это четыре недели и три дня, поэтому 20 апреля будет в воскресенье."]],""],[842,100,"На рисунке справа AC = 12, BD = 15, CE = 11 и AB = DE. Чему равна длина CD?",{"0":[51.8,65.7,31.6,26.5],"1":[201.8,65.7,31.6,26.5],"2":[351.8,65.7,31.6,26.5],"3":[501.3,65.7,28.8,26.5],"4":[651.3,65.7,31.6,26.5]},"A","Отрезок CD",[["Сравни соседние части","AC на 1 длиннее CE, а AB и DE равны. Значит, если отнять эти равные отрезки, BC окажется на 1 длиннее CD."],["Раздели длину BD","BC и CD вместе дают 15. Если убрать лишнюю единицу из BC, две равные части дадут 14. Длина CD равна 7."]],""],[834,234,"Квадрат разрезан на четыре части, как показано на рисунке. Какую фигуру нельзя составить из этих частей?",{"0":[51.8,102.9,31.6,26.5],"1":[211.4,102.9,31.6,26.5],"2":[371.6,102.9,31.6,26.5],"3":[511.4,102.9,28.8,26.5],"4":[701.0,102.9,31.6,26.5]},"D","Четыре части квадрата",[["Найди детали","Получились прямоугольник 4 × 2, один большой треугольник и два маленьких треугольника."],["Проверь возможные фигуры","В А прямоугольник ложится поперёк середины, а большой треугольник даёт остриё снизу. В Б и Д положи прямоугольник вдоль нижнего края слева, а большой треугольник — на верхний выступ справа. В В прямоугольник ложится вдоль середины нижнего края, а большой треугольник — на верхний выступ слева."],["Посмотри на Г","В этих четырёх укладках остаются ровно два места для маленьких треугольников. В Г, если положить прямоугольник в среднюю полосу, остаются четыре отдельных маленьких треугольника. Подходит ответ Г."]],""],[834,155,"Вася взял в школу 18 конфет. Три конфеты он съел по дороге. Каждый раз, когда Вася съедал конфету в школе, он угощал конфетой Машу или Дашу, причем три раза он угостил сразу обеих девочек. Все конфеты были съедены. Сколько конфет съел Вася?",{"0":[51.8,120.4,31.6,26.5],"1":[201.8,120.4,31.6,26.5],"2":[351.8,120.4,31.6,26.5],"3":[501.3,120.4,28.8,26.5],"4":[651.3,120.4,31.6,26.5]},"C","Васины конфеты",[["Посчитай школьные конфеты","После дороги осталось 18 − 3 = 15 конфет. В школе на каждую Васину конфету пришлась одна конфета для девочки, а ещё в трёх случаях — вторая."],["Раздели на пары","Если отложить три дополнительные конфеты, останется 12 конфет в парах. В школе Вася съел 6, по дороге — 3, всего 9."]],""],[834,155,"В ребусе одинаковые буквы обозначают одинаковые цифры, а разные буквы — разные цифры. Известно, что цифры 0, 8 и 9 не использованы. Какая еще цифра не использована?",{"0":[51.8,121.0,31.6,26.5],"1":[178.1,121.0,31.6,26.5],"2":[311.8,121.0,31.6,26.5],"3":[444.9,121.0,28.8,26.5],"4":[578.0,121.0,31.6,26.5]},"B","Буквенный ребус",[["Начни с сотен","При сложении двух двузначных чисел сотня может быть только 1. Значит, У = 1. Тогда Е + Г = 11 и переносит одну десятку."],["Проверь пары","Из цифр 2–7 сумма 11 получается только у пар 4 и 7 или 5 и 6. Среди оставшихся цифр наибольшая сумма К + Н тоже 11. А чтобы в ответе вышло 1Р1, нужна сумма К + Н + 1 хотя бы 12, так как Р уже не может быть 0 или 1."],["Найди лишнюю цифру","В обоих случаях используются пары 4 и 7, 5 и 6, а Р = 2. Из цифр 1–7 не понадобилась 3."]],""],[834,155,"Летом дети ездили на велосипедах с дачи на озеро. От дачи до озера 3 км. Игорь проезжал весь путь за 10 минут, Маша ехала в 2 раза дольше, а Аня ехала быстрее Маши, но медленнее Игоря. Какая скорость могла быть у Ани?",{"0":[51.8,121.0,31.6,26.5],"1":[201.8,121.0,31.6,26.5],"2":[351.8,121.0,31.6,26.5],"3":[501.3,121.0,28.8,26.5],"4":[651.3,121.0,31.6,26.5]},"C","Скорость до озера",[["Найди две скорости","За час Игорь проехал бы 6 отрезков по 3 км, то есть 18 км. Маша ехала вдвое дольше, поэтому её скорость 9 км/ч."],["Выбери между ними","Скорость Ани больше 9 и меньше 18 км/ч. Из предложенных подходит 12 км/ч."]],""],[834,220,"После того, как в 7 : 00 прозвенел будильник, Вася стукнул по нему кулаком, и минутная стрелка стала двигаться в 12 раз быстрее, чем надо. Что покажет этот будильник в 7 : 55?",{"0":[51.8,186.4,31.6,26.5],"1":[201.8,186.4,31.0,26.5],"2":[351.8,186.4,31.6,26.5],"3":[501.3,186.4,28.2,26.5],"4":[644.6,186.4,31.6,26.5]},"E","Сломанный будильник",[["Проверь минутную стрелку","За 55 минут она проходит 55 × 12 = 660 минутных делений, то есть ровно 11 кругов. Стрелка снова у цифры 12."],["Посмотри на часовую","Обычная часовая стрелка показывает почти 8, ведь наступило 7:55. Обе стрелки так стоят на рисунке Д."]],""],[834,155,"У малыша Феди есть 10 красных кубиков, 15 синих и 30 зеленых. Он хочет построить из них башню так, чтобы любые два соседних кубика имели разный цвет. Сколько кубиков будет в самой высокой башне, которую сможет построить Федя?",{},"D","Башня из кубиков",[["Сделай разделители","Красных и синих кубиков вместе 25. Если выложить их в ряд, между ними 24 места, и ещё два места есть по краям."],["Заполни зелёными","Поставь по одному зелёному кубику в каждое из 26 мест. Больше 26 нельзя, иначе зелёные окажутся рядом. Всего получится 51 кубик."]],""],[842,130,"Братец Кролик за день съедает или 9 морковок, или 2 кочана капусты, или 1 кочан капусты и 4 морковки. За неделю он съел 30 морковок. Сколько кочанов капусты он съел за эту неделю?",{"0":[51.8,96.2,31.6,26.5],"1":[161.8,96.2,31.6,26.5],"2":[278.0,96.2,31.6,26.5],"3":[394.7,96.2,28.8,26.5],"4":[501.3,96.2,31.6,26.5]},"B","Меню Братца Кролика",[["Посчитай морковные дни","Пробуем брать по 9 морковок ноль, один, два или три дня. Только после двух таких дней остаток 30 − 18 = 12 делится на 4. Это ещё три дня по 4 морковки."],["Посчитай капусту","За смешанные дни съедено 3 кочана. Оставшиеся два дня были только капустными: ещё 4 кочана. Всего 7."]],""],[842,171,"Какое наименьшее число клеток надо закрасить, чтобы в любом квадратике 2 × 2 на рисунке была хотя бы одна закрашенная клетка?",{"0":[51.8,136.3,31.6,26.5],"1":[161.8,136.3,31.6,26.5],"2":[278.0,136.3,31.6,26.5],"3":[394.7,136.3,28.8,26.5],"4":[501.3,136.3,31.6,26.5]},"D","Клетки для закраски",[["Найди нижнюю границу","На рисунке можно выделить четыре квадрата 2 × 2 вокруг центра так, чтобы они не пересекались. Они идут по кругу: сверху, справа, снизу и слева. В каждом надо закрасить хотя бы одну клетку."],["Закрась четыре клетки","Возьми четыре клетки, которые касаются центральной уголками. В каждом квадрате 2 × 2 найдётся одна из них. Значит, четырёх хватает."]],""],[842,210,"Фрекен Бок поставила на стол 15 тарелок с булочками. На первой тарелке лежит одна булочка, на второй — две, на третьей — три, и так далее. Иногда в окно влетает Карлсон, выбирает несколько тарелок и съедает с каждой из них одинаковое количество булочек. За какое наименьшее число визитов Карлсон сможет съесть все булочки?",{"0":[51.8,176.8,31.6,26.5],"1":[161.8,176.8,31.6,26.5],"2":[278.0,176.8,31.6,26.5],"3":[394.7,176.8,28.8,26.5],"4":[501.3,176.8,31.6,26.5]},"B","Визиты Карлсона",[["Проверь, хватит ли трёх","За три визита каждую тарелку можно выбрать или пропустить три раза. Получится только 7 непустых наборов визитов, то есть максимум 7 разных количеств булочек."],["Разложи числа на суммы","За четыре визита Карлсон может съедать с выбранных тарелок по 1, 2, 4 или 8 булочек. Из этих чисел можно сложить любое число от 1 до 15, например 13 = 8 + 4 + 1. Значит, четырёх визитов хватает."]],""],[842,169,"Какой кубик получится из данной развертки?",{"0":[51.8,132.2,31.6,26.5],"1":[174.7,132.2,31.6,26.5],"2":[294.9,132.2,31.6,26.5],"3":[411.6,132.2,28.8,26.5],"4":[521.6,132.2,31.6,26.5]},"E","Кубик со стрелками",[["Сложи пояс","Четыре клетки в одной строке станут поясом кубика. Стрелка на первой клетке направлена ко второй. Стрелка на отдельной нижней грани направлена к четвёртой клетке пояса."],["Сравни направления","Вторая и четвёртая грани пояса противоположны. Поэтому стрелки смотрят в противоположные стороны. Если повернуть кубик, как в вариантах, правильная картинка — Д."]],""],[842,129,"Назовем трехзначное число удивительным, если оно делится на 3, а первая и последняя цифры у него одинаковы. Чему равна наименьшая разность между двумя удивительными числами?",{"0":[51.8,95.6,31.6,26.5],"1":[201.8,95.6,31.6,26.5],"2":[351.8,95.6,31.6,26.5],"3":[501.3,95.6,28.8,26.5],"4":[651.3,95.6,31.6,26.5]},"C","Удивительные числа",[["Сравни соседние записи","Если первая цифра у обоих чисел одна и та же, разность — число десятков, кратное 3, то есть хотя бы 30. Если первые цифры различны, самая маленькая возможная разность получается на границе сотен и равна хотя бы 11."],["Проверь разность","На границе соседних сотен разность кончается на 1. Число 11 не делится на 3, а 21 делится. Пара 282 и 303 даёт ровно 21."]],""],[842,207,"На рисунке изображен план дома Кенги. Любые две соседние комнаты соединены дверью. Кенга хочет пройти из комнаты А в комнату В, не проходя ни через какую комнату более одного раза. Сколькими способами Кенга сможет это сделать?",{"0":[51.8,172.9,31.6,26.5],"1":[161.8,172.9,31.6,26.5],"2":[278.0,172.9,31.6,26.5],"3":[394.7,172.9,28.8,26.5],"4":[501.3,172.9,31.6,26.5]},"D","Дороги в доме Кенги",[["Найди общую комнату","Два квадрата по 3 × 3 комнаты соединяются через одну общую угловую комнату. Сначала посчитай пути из угла в противоположный угол в одном квадрате."],["Разбей пути по длине","Без повторов можно пройти за 4, 6 или 8 переходов. Если первый шаг вправо, остаются 3 кратчайших пути, 2 пути с одним обходом и 1 путь змейкой. С первым шагом вниз столько же. Всего 12."],["Соедини пути","Для каждого из 12 путей к общей комнате можно выбрать любой из 12 путей от неё к выходу. Получается 12 × 12 = 144."]],""]]],[2015,"3–4 классы",[[841,160,"Незнайка писал слово КЕНГУРУ. У него получилось: Сколько букв он написал неправильно?",{},"D","Перевёрнутые буквы",[["Сверь с образцом","Сравни буквы по одной со словом КЕНГУРУ. К, Н и первая У стоят правильно."],["Отметь ошибки","Буквы Е, Г, Р и последняя У повёрнуты или отражены. Всего четыре ошибки."]],""],[841,70,"Чему равна сумма двадцати сотен и пятнадцати?",{},"C","Двадцать сотен",[["Переведи сотни","Одна сотня — 100, а двадцать сотен — 20 × 100 = 2000."],["Прибавь пятнадцать","2000 + 15 = 2015."]],""],[841,229,"Индеец Белый Орёл живет в вигваме, на котором треугольников и квадратиков нарисовано поровну. На каком из рисунков изображён его вигвам?",{},"E","Вигвам Белого Орла",[["Раздели узоры","При подсчёте бери только нарисованные треугольники и квадратики. Дверь и контур вигвама в счёт не идут."],["Сравни числа","На вигваме Д три треугольника и три квадратика. Их поровну."]],""],[841,183,"",{"0":[51.8,35.3,31.4,26.3],"1":[51.8,63.5,31.1,26.3],"2":[51.8,91.7,31.4,26.3],"3":[51.7,119.9,28.4,26.3],"4":[51.7,149.4,31.7,26.3]},"C","Дюжина и сутки",[["Найди три раза по четыре","Это задача 4, а 3 × 4 = 12. Дюжина, число месяцев и число подвигов Геракла тоже равны 12."],["Проверь сутки","В сутках 24 часа. Значит, подходит вариант В."]],""],[841,242,"(В) число часов в сутках (Г) утроенный номер этой задачи (Д) число подвигов Геракла 5. На рисунке изображён пруд и несколько лягушек. Сколько из этих лягушек сидят в пруду?",{},"B","Лягушки в пруду",[["Проследи берег","Веди пальцем по линии берега. У пруда есть узкие изгибы, поэтому две лягушки рядом на рисунке могут оказаться по разные стороны линии."],["Отметь сидящих в воде","В воде сидят верхняя левая лягушка, две лягушки в изгибах ближе к середине, одна на верхнем краю правого изгиба и две внизу. Всего их шесть."]],""],[841,97,"В числе 2015 четыре цифры. Произведение двух бóльших цифр поделили на сумму двух меньших. Что получилось?",{"0":[51.8,63.6,31.4,26.3],"1":[201.8,63.6,31.1,26.3],"2":[351.7,63.6,31.4,26.3],"3":[501.6,63.6,28.4,26.3],"4":[651.5,63.6,31.7,26.3]},"D","Цифры числа 2015",[["Выбери пары","Две бо́льшие цифры — 5 и 2, их произведение равно 10."],["Посчитай результат","Две меньшие цифры — 0 и 1, их сумма равна 1. Теперь 10 : 1 = 10."]],""],[848,234,"Петя катается на велосипеде по дорожкам, изображённым на рисунке. Он стартует из точки О в направлении, указанном стрелкой. На первом перекрёстке Петя поворачивает направо, на втором — налево, потом опять направо, потом опять налево, и так далее. В какой точке он не может оказаться?",{"0":[51.7,199.4,31.4,26.3],"1":[161.6,199.4,31.1,26.3],"2":[278.3,199.4,31.4,26.3],"3":[395.0,199.4,28.4,26.3],"4":[511.5,199.4,31.7,26.3]},"A","Велосипедный маршрут",[["Пройди первые повороты","Из О Петя едет к Г. Правый поворот ведёт его через В к Б, а левый в точке Б — обратно к Г по верхней стороне квадрата."],["Замкни маршрут","В Г Петя поворачивает направо к Д, а в Д — налево через О. Он возвращается в исходную точку в том же направлении и дальше повторяет путь. В точку А он не заезжает."]],""],[848,149,"Аня отметила на прямой линии 5 красных точек. В каждый промежуток между красными точками она поставила синюю точку, а потом в каждый промежуток между красной и синей точками — зелёную точку. Сколько всего точек получилось?",{"0":[51.7,115.1,31.4,26.3],"1":[201.7,115.1,31.1,26.3],"2":[351.6,115.1,31.4,26.3],"3":[501.5,115.1,28.4,26.3],"4":[651.3,115.1,31.7,26.3]},"C","Разноцветные точки",[["Найди синие точки","Между пятью последовательными красными точками четыре промежутка. В каждом появится одна синяя точка."],["Добавь зелёные","Каждая синяя делит один исходный промежуток на два. Значит, зелёных точек 8, а всего 5 + 4 + 8 = 17."]],""],[848,149,"Аня, Боря, Вася, Гриша и Дима написали на доске числа 1, 3, 4, 6 и 8, каждый по одному числу. Васино число оказалось в 2 раза больше, чем Димино, а Борино — на 2 больше, чем Гришино. Какое число написала Аня?",{},"B","Кто написал шестёрку?",[["Проверь удвоение","Дима и Вася могли написать 3 и 6 или 4 и 8 соответственно. Если убрать 3 и 6, среди 1, 4 и 8 нет двух чисел с разностью 2."],["Раздай остальные числа","Значит, у Димы 4, а у Васи 8. Гриша написал 1, а Боря 3. Ане досталось оставшееся число 6."]],""],[848,68,"",{"0":[51.7,34.1,31.4,26.3],"1":[201.7,34.1,31.1,26.3],"2":[351.6,34.1,31.4,26.3],"3":[501.5,34.1,28.4,26.3],"4":[651.3,34.1,31.7,26.3]},"C","Тысяча дециметров",[["Вспомни единицу","В одном метре 10 дециметров."],["Раздели на десять","В 1000 дециметрах ровно 1000 : 10 = 100 метров."]],""],[848,124,"С первого января 2015 года малыш Федя начал вести дневник. Он уверен, что в каждом месяце ровно 30 дней. Какую дату он напишет в своем дневнике 19 марта 2015 года в день конкурса «Кенгуру»?",{"0":[51.7,90.4,31.4,26.3],"1":[201.7,90.4,31.1,26.3],"2":[351.6,90.4,31.4,26.3],"3":[501.4,90.4,28.4,26.3],"4":[651.3,90.4,31.7,26.3]},"B","Дневник Феди",[["Сравни два начала марта","В календаре январь и февраль 2015 года вместе занимают 31 + 28 = 59 дней. У Феди они занимают 30 + 30 = 60 дней."],["Передвинь дату","Федин март начинается на день позднее. Поэтому в день 19 марта по календарю он напишет 18 марта."]],""],[848,177,"Маша хочет разрезать по сторонам клеточек прямоугольник 4×3 так, чтобы из полученных частей можно было сложить фигурку, изображённую справа. На какое наименьшее число частей придётся разрезать прямоугольник?",{"0":[51.7,143.7,31.4,26.3],"1":[161.7,143.7,31.1,26.3],"2":[278.3,143.7,31.4,26.3],"3":[395.0,143.7,28.4,26.3],"4":[501.5,143.7,31.7,26.3]},"B","Разрезаем прямоугольник",[["Подбери три детали","У фигурки отдели верхний уголок из трёх клеток и полоску из трёх клеток под ним слева. Останется деталь из шести клеток. Для таких деталей в прямоугольнике отложи три правые клетки верхнего ряда для полоски, а в правом нижнем углу отрежь уголок из трёх клеток."],["Почему двух мало?","Верхняя клетка и обе нижние ножки отстоят на пять рядов, поэтому при двух деталях окажутся в разных частях. Крайняя левая клетка соседствует с одной-единственной клеткой. Через ту же клетку верхушка соединяется с остальной фигурой, поэтому левый выступ тоже относится к верхней части. Правый выступ тогда должен быть у нижней части, иначе верхняя часть растянется на пять столбцов."],["Проверь нижнюю деталь","Она занимает четыре столбца и три ряда, как весь прямоугольник. В ней есть выемка между ножками и пустое место под правым выступом. Эти пустые места разделены клетками детали, поэтому закрыть оба одной связной частью нельзя."]],""],[848,151,"Вася наклеил на лист бумаги одну за другой 5 круглых наклеек с цифрами. В каком порядке он не мог их наклеивать?",{"0":[51.7,90.4,31.4,26.3],"1":[268.3,90.4,31.1,26.3],"2":[501.5,90.4,31.4,26.3],"3":[51.7,117.5,28.4,26.3],"4":[268.3,117.5,31.6,26.3]},"C","Порядок наклеек",[["Проверь перекрытие","Если наклейка закрывает часть соседней, её приклеили позже. Посмотри на границу наклеек 1 и 2."],["Проверь вариант В","Наклейка 1 лежит поверх наклейки 2, значит, наклейка 2 была раньше. В порядке 3, 5, 1, 2, 4 они стоят наоборот."]],""],[841,208,"Друзья выясняли, какой сегодня день недели. Витя сказал: «Вчера было воскресенье». Сема сказал: «Завтра будет суббота». Петя сказал: «Позавчера была пятница». Саша сказал: «Послезавтра будет среда». Двое из них ошиблись. Какой сегодня день недели?",{"0":[51.7,173.9,31.4,26.3],"1":[255.0,173.9,31.1,26.3],"2":[404.9,173.9,31.4,26.3],"3":[528.2,173.9,28.4,26.3],"4":[664.7,173.9,31.7,26.3]},"A","День недели",[["Переведи высказывания","Если вчера было воскресенье, сегодня понедельник. Если завтра суббота, сегодня пятница. Если позавчера была пятница, сегодня воскресенье."],["Найди совпадение","Если послезавтра среда, сегодня понедельник. Только понедельник назвали двое — Витя и Саша."]],""],[841,102,"Какой из результатов самый маленький?",{"0":[51.7,36.4,30.4,26.3],"1":[294.9,36.4,30.1,26.3],"2":[528.2,36.4,30.4,26.3],"3":[51.7,68.1,27.4,26.3],"4":[294.9,68.1,30.6,26.3]},"E","Наименьшее частное",[["Сравни делимые","Все выражения делят на 9. Значит, достаточно найти самую маленькую разность в скобках."],["Вычти","100 − 10 = 90 — меньше 100 − 1 и всех разностей, начинающихся с 1000. Подходит вариант Д."]],""],[841,176,"Наташа рассматривает в лупу разные части рисунка на школьной доске. Какое из изображений А–Д она не сможет увидеть?",{"0":[51.7,134.8,31.4,26.3],"1":[161.6,134.8,31.1,26.3],"2":[271.6,134.8,31.4,26.3],"3":[381.6,134.8,28.4,26.3],"4":[488.1,134.8,31.7,26.3]},"E","Вид через лупу",[["Найди нужное соединение","В варианте Д вертикальная линия идёт вверх от горизонтальной перекладины, а вниз от неё не продолжается. При этом горизонтальная линия тянется и влево, и вправо."],["Проверь рисунок","Вертикальные стороны большого квадрата идут и вверх, и вниз. Короткий вертикальный отрезок внутри него тоже пересекает среднюю линию насквозь. Вид Д нигде не получается."]],""],[841,98,"Разность двух чисел на 3 меньше уменьшаемого и на 4 больше вычитаемого. Чему она равна?",{"0":[51.7,63.5,31.4,26.3],"1":[201.7,63.5,31.1,26.3],"2":[351.6,63.5,31.4,26.3],"3":[501.5,63.5,28.4,26.3],"4":[651.3,63.5,31.7,26.3]},"A","Уменьшаемое и вычитаемое",[["Восстанови вычитаемое","Разность на 3 меньше уменьшаемого. Значит, из уменьшаемого вычли 3."],["Найди разность","Она на 4 больше вычитаемого, поэтому равна 3 + 4 = 7."]],""],[841,181,"Фигуру, изображённую на рис. 1, Вася разрезал на одинаковые треугольники, изображённые на рис. 2. Сколько треугольников у него получилось?",{"0":[51.7,117.5,31.4,26.3],"1":[201.7,117.5,31.1,26.3],"2":[351.6,117.5,31.4,26.3],"3":[51.7,146.9,28.4,26.3],"4":[201.7,146.9,31.7,26.3]},"D","Разрезание на треугольники",[["Раздели середину","В середине фигуры три квадрата размером 2 × 2. Если провести обе диагонали в каждом, получится по четыре треугольника с рисунка 2."],["Посчитай выступы","Выступ слева делится на два таких треугольника, выступ справа уже имеет нужную форму. Всего 3 × 4 + 2 + 1 = 15."]],""],[841,181,"Стрелочки на рисунке указывают на результаты действий с числами. Числа 1, 2, 3, 4, 5, 6 и 7 надо разместить по одному в квадратиках так, чтобы все результаты были правильными. Какое число попадёт в заштрихованный квадратик?",{"0":[51.7,146.8,31.4,26.3],"1":[161.7,146.8,31.1,26.3],"2":[278.2,146.8,31.4,26.3],"3":[395.0,146.8,28.4,26.3],"4":[501.4,146.8,31.7,26.3]},"A","Числа в квадратиках",[["Начни с умножения","Единица множителем быть не может: результат повторил бы другой множитель. Из разных чисел больше 1 только 2 × 3 даёт результат не больше 7. Значит, слева в сумме стоит 6."],["Посмотри на сумму","Чтобы прибавить к 6 число и получить не больше 7, надо прибавить 1. В заштрихованном квадратике поэтому стоит 1. Это согласуется с вычитанием 5 − 4."]],""],[841,134,"Фигура на рисунке состоит из одинаковых квадратов со стороной 1 см. Чему равен её периметр?",{"0":[51.7,65.7,31.4,26.3],"1":[201.7,65.7,31.1,26.3],"2":[351.6,65.7,31.4,26.3],"3":[501.4,65.7,28.4,26.3],"4":[51.6,97.4,31.7,26.3]},"D","Периметр ступенчатой фигуры",[["Сосчитай горизонтальные края","Нижний край равен 3 см. Выше фигура сужается, и все горизонтальные ступеньки сверху вместе дают те же 3 см."],["Сосчитай вертикальные края","Слева край поднимается на три ряда, справа спускается на три ряда. Это ещё 6 см. Периметр 3 + 3 + 6 = 12 см."]],""],[848,179,"Маша заполняет горшочек крупой. Он будет полным, если в него насыпать 6 чайных ложек, 3 десертных и 1 столовую ложку крупы или 2 чайные ложки, 1 десертную и 3 столовые ложки той же крупы. У Маши есть только столовые ложки. Сколько таких ложек крупы ей придется насыпать?",{"0":[51.7,144.7,31.4,26.3],"1":[201.7,144.7,31.1,26.3],"2":[351.6,144.7,31.4,26.3],"3":[501.5,144.7,28.4,26.3],"4":[651.5,144.7,31.7,26.3]},"A","Три вида ложек",[["Сократи общую часть","Оба набора наполняют один горшочек. Убери из обоих по 2 чайные, 1 десертной и 1 столовой ложке. Останутся 4 чайные и 2 десертные с одной стороны и 2 столовые с другой."],["Замени маленькие ложки","Значит, 2 чайные и 1 десертная вместе равны 1 столовой. Во втором наборе к ним добавили ещё 3 столовые ложки, всего 4."]],""],[848,241,"У длинной верёвки связали концы и разложили получившуюся петлю на столе. Часть этой петли закрыта (смотри рисунок). Как может выглядеть закрытая часть?",{"0":[51.7,145.5,31.4,26.3],"1":[245.0,145.5,31.1,26.3],"2":[445.0,145.5,31.4,26.3],"3":[51.7,207.3,28.4,26.3],"4":[245.0,207.3,31.7,26.3]},"C","Одна петля верёвки",[["Пронумеруй концы","Над краем прямоугольника видно шесть концов. Если считать слева, открытые дуги соединяют 1 с 4, 2 с 6 и 3 с 5."],["Проследи всю петлю","В варианте В скрытые дуги соединяют 1 с 2, 3 с 6 и 4 с 5. Тогда путь 1 → 4 → 5 → 3 → 6 → 2 → 1 проходит через все шесть концов одной петли."]],""],[848,124,"В гостях у бабушки Женя и Лена ели мороженое ежедневно: каждая по 2 или 3 стаканчика. Всего Женя съела 25 стаканчиков, а Лена — 19. Сколько дней они гостили у бабушки?",{"0":[51.8,90.5,31.4,26.3],"1":[201.8,90.5,31.1,26.3],"2":[351.7,90.5,31.4,26.3],"3":[501.6,90.5,28.4,26.3],"4":[651.5,90.5,31.7,26.3]},"B","Мороженое у бабушки",[["Проверь Женю","За 8 дней даже по три стаканчика в день Женя съела бы только 24. Её 25 стаканчиков требуют хотя бы 9 дней."],["Проверь Лену","За 10 дней даже по два стаканчика в день Лена съела бы 20. Значит, её 19 стаканчиков требуют не больше 9 дней. Вместе получается ровно 9. За девять дней Женя могла съесть по три стаканчика семь раз и по два ещё два раза, а Лена — только один раз три и восемь раз по два."]],""],[848,125,"В числовом ребусе буквами O, D, E, V, N обозначены разные цифры. Сколько различных цифр может обозначать буква V?",{"0":[51.7,90.5,31.4,26.3],"1":[161.7,90.5,31.1,26.3],"2":[278.3,90.5,31.4,26.3],"3":[395.0,90.5,28.4,26.3],"4":[501.5,90.5,31.7,26.3]},"B","Ребус ODD + ODD",[["Найди сотни и тысячи","Сумма двух трёхзначных чисел не больше 1998. Значит, первая цифра E равна 1, и в разряде десятков тоже стоит 1."],["Найди последние цифры","В десятках 2 × D вместе с переносом должно оканчиваться на 1. Поэтому перенос из единиц равен 1, D = 5, а N = 0."],["Проверь разряд сотен","Если O равно 6, 7, 8 или 9, то 2 × O + 1 даёт 13, 15, 17 или 19. Цифры V = 5 и V = 9 повторили бы уже поставленные цифры. Подходят только V = 3 и V = 7."]],""],[848,152,"Дима, Федя, Надя и Катя пошли в лес за грибами. Известно, что Дима нашел грибов меньше, чем Федя, мальчики нашли грибов столько же, сколько девочки, а Дима и Надя нашли грибов больше, чем Федя и Катя. Кто нашел больше всех грибов?",{"0":[51.8,117.6,31.4,26.3],"1":[165.2,117.6,31.1,26.3],"2":[278.3,117.6,31.4,26.3],"3":[388.3,117.6,28.4,26.3],"4":[491.5,117.6,31.7,26.3]},"D","Кто нашёл больше грибов?",[["Сравни пары","Дима и Надя нашли больше половины всех грибов, ведь у них вместе больше, чем у Феди и Кати. Дима и Федя вместе нашли ровно половину."],["Проверь остальных","Если из обоих количеств убрать грибы Димы, видно, что Надя обошла Федю, а значит, и Диму. При этом по условию девочки вместе собрали столько же, сколько мальчики: чтобы Надя нашла больше Феди, Катя должна была найти меньше Димы."]],""],[848,125,"Никита выписывает подряд целые числа 1, 2, 3,…, но он не любит цифру 7 и пропускает все числа, которые её содержат. Он выписал 777 чисел. Какое число он написал последним?",{"0":[51.8,90.5,31.4,26.3],"1":[201.8,90.5,31.1,26.3],"2":[351.7,90.5,31.4,26.3],"3":[501.5,90.5,28.4,26.3],"4":[651.4,90.5,31.7,26.3]},"C","Числа без семёрки",[["Посчитай до 999","В каждой из трёх позиций есть 9 разрешённых цифр. Получается 9 × 9 × 9 = 729 записей, включая 000. Положительных чисел 728."],["Дойди до нужной записи","Осталось 777 − 728 = 49 чисел. С 1000 по 1049 в каждом десятке пропускаем одно число с 7, поэтому выписываем 45. Ещё четыре числа — 1050, 1051, 1052 и 1053."]],""]]],[2016,"3–4 классы",[[840,250,"Кенга посмотрела на себя в зеркало. Что она увидела?",{"0":[85.1,83.5,31.4,31.3],"1":[204.9,83.5,31.1,31.3],"2":[328.3,83.5,31.4,31.3],"3":[444.9,83.5,28.4,31.3],"4":[561.4,83.5,31.7,31.3]},"E","Кенга в зеркале",[["Поменяй стороны","Хвост Кенги справа, поэтому в зеркале он окажется слева."],["Проверь уши","Ухо, которое стояло прямо справа, в отражении стоит прямо слева. Обе приметы совпадают на рисунке Д."]],""],[840,129,"Крошке Ру 17 марта исполняется 7 недель и 3 дня. Когда ему исполнится 9 недель?",{"0":[51.8,63.6,31.4,31.3],"1":[278.4,63.6,31.1,31.3],"2":[495.0,63.6,31.4,31.3],"3":[51.8,92.9,28.4,31.3],"4":[278.4,92.9,31.7,31.3]},"D","Девять недель",[["Посчитай недостающие дни","От 7 недель и 3 дней до 8 недель остаётся 4 дня. До 9 недель нужна ещё неделя."],["Прибавь к дате","Всего надо подождать 4 + 7 = 11 дней. Через 11 дней после 17 марта будет 28 марта."]],""],[840,155,"Какое число должно стоять в закрашенном квадратике?",{"0":[51.8,89.4,31.4,31.3],"1":[201.8,89.4,31.1,31.3],"2":[351.7,89.4,31.4,31.3],"3":[51.8,118.9,28.4,31.3],"4":[201.8,118.9,31.7,31.3]},"C","Числа по стрелкам",[["Заполни белые клетки","Слева получаем 20 + 16 = 36, справа — 20 − 16 = 4."],["Выполни последнее действие","Между белыми клетками стоит плюс. В серой клетке будет 36 + 4 = 40."]],""],[840,162,"Дима с папой пришли в цирк и ищут свои места с номерами 86 и 87. По какой стрелке им надо идти?",{"0":[51.7,74.4,31.4,31.3],"1":[201.7,74.4,31.2,31.3],"2":[351.6,74.4,31.4,31.3],"3":[51.7,113.2,28.4,31.3],"4":[201.7,113.2,31.7,31.3]},"E","Места в цирке",[["Найди подходящий ряд","На указателе числа 86 и 87 попадают в одну группу: от 81 до 100."],["Прочитай стрелку","Рядом с группой 81–100 стрелка направлена вверх и влево."]],""],[840,128,"Когда Саша зашифровала цифры буквами, оказалось, что 65832 = КЕНГА. Какое из следующих зашифрованных чисел самое маленькое?",{"0":[51.7,92.3,31.4,31.3],"1":[155.0,92.3,31.1,31.3],"2":[255.0,92.3,31.4,31.3],"3":[351.6,92.3,28.5,31.3],"4":[445.0,92.3,31.7,31.3]},"A","Буквы вместо цифр",[["Расшифруй буквы","В записи 65832 = КЕНГА буква К значит 6, Е — 5, Н — 8, Г — 3, а А — 2."],["Сравни десятки","Получаются 23, 56, 85, 62 и 32. У числа 23 меньше всего десятков."]],""],[840,185,"Часть квадрата скрыта за шторкой. Какую форму имеет скрытая часть?",{},"B","Квадрат за шторкой",[["Продолжи стороны","Продли две наклонные стороны квадрата под шторкой. Соедини их оставшейся стороной квадрата."],["Посчитай углы","У скрытой части два угла на краю шторки и два угла самого квадрата. Это четырёхугольник."]],""],[848,75,"Четвертое число в третьем десятке — это",{"0":[51.7,38.7,31.4,31.3],"1":[201.7,38.7,31.2,31.3],"2":[351.7,38.7,31.4,31.3],"3":[501.5,38.7,28.5,31.3],"4":[651.4,38.7,31.7,31.3]},"D","Третий десяток",[["Найди начало десятка","Первый десяток идёт от 1 до 10, второй — от 11 до 20. Третий начинается с 21."],["Отсчитай до четвёртого","Числа идут так: 21, 22, 23, 24. Четвёртое — 24."]],""],[848,217,"Фигуры на рисунке — это круги, треугольники и квадраты. Что верно?",{"0":[51.7,63.7,31.4,31.3],"1":[51.7,93.0,31.1,31.3],"2":[51.7,122.4,31.4,31.3],"3":[51.7,151.9,28.4,31.3],"4":[51.7,181.2,31.7,31.3]},"E","Круги и треугольники",[["Разложи фигуры по видам","На рисунке три круга, три квадрата и четыре треугольника. Поворот фигуры не меняет её форму."],["Сравни количества","Три меньше четырёх, поэтому кругов меньше, чем треугольников."]],""],[848,78,"Значок весит 3 г. Сколько весит тысяча таких значков?",{"0":[51.6,41.3,31.4,31.3],"1":[161.7,41.3,31.1,31.3],"2":[278.3,41.3,31.4,31.3],"3":[395.0,41.3,28.4,31.3],"4":[501.4,41.3,31.7,31.3]},"C","Тысяча значков",[["Умножь массу","Тысяча значков по 3 грамма весит 3 × 1000 = 3000 граммов."],["Переведи в килограммы","В 1 килограмме 1000 граммов. Значит, 3000 граммов — это 3 килограмма."]],""],[848,182,"Среди этих четырех карточек есть две одинаковые. Какие?",{"0":[51.6,145.3,31.4,31.3],"1":[201.7,145.3,31.1,31.3],"2":[351.6,145.3,31.4,31.3],"3":[501.5,145.3,28.4,31.3],"4":[651.4,145.3,31.7,31.3]},"A","Одинаковые карточки",[["Поверни первую карточку","При повороте на пол-оборота левая точка оказывается справа, а верхняя — снизу."],["Приложи к рисунку","Справа и снизу стоят точки на карточке 4. Поэтому совпадают 1 и 4."]],""],[848,102,"Во дворе гуляют несколько собак. У этих собак лап на 18 больше, чем носов. Сколько собак во дворе?",{"0":[51.7,65.8,31.4,31.3],"1":[161.7,65.8,31.1,31.3],"2":[278.3,65.8,31.4,31.3],"3":[395.1,65.8,28.4,31.3],"4":[501.6,65.8,31.7,31.3]},"C","Лапы и носы",[["Возьми одну собаку","У каждой собаки 4 лапы и 1 нос. Значит, одна собака добавляет к разнице 3."],["Подели общую разницу","На всех собак приходится разница 18. Получаем 18 ÷ 3 = 6 собак."]],""],[848,257,"",{},"D","Два переворота",[["Переверни через левый край","Левая и правая части меняются местами. Чёрная четверть оказывается справа внизу."],["Переверни через верхний край","Низ и верх меняются местами. Полукруг теперь сверху, а чёрная четверть — справа."]],""],[848,129,"Сумма двух чисел равна 170. Первое число оканчивается цифрой 5, а если эту цифру стереть, то получится второе число. Чему равна разность этих чисел?",{"0":[51.7,92.9,31.4,31.3],"1":[201.7,92.9,31.2,31.3],"2":[351.6,92.9,31.4,31.3],"3":[501.5,92.9,28.4,31.3],"4":[651.4,92.9,31.7,31.3]},"D","Число с приписанной пятёркой",[["Вырази первое число","Когда к меньшему числу справа приписывают 5, оно становится в 10 раз больше, а затем к нему прибавляется 5."],["Найди оба числа","От 170 отними 5. Останется 165 — это 11 меньших чисел. Меньшее число 15, большее 155, разность 155 − 15 = 140."]],""],[840,132,"Улитке нужно было проползти 12 метров. Утром до обеда она проползла 12 дм, а после обеда устала и проползла только 12 см. Какое расстояние ей осталось проползти?",{"0":[51.7,95.3,31.4,31.3],"1":[201.8,95.3,31.1,31.3],"2":[351.7,95.3,31.4,31.3],"3":[501.5,95.3,28.4,31.3],"4":[651.4,95.3,31.7,31.3]},"B","Путь улитки",[["Переведи всё в сантиметры","В 12 м содержится 1200 см, а в 12 дм — 120 см."],["Вычти пройденное","Улитка проползла 120 + 12 = 132 см. Осталось 1200 − 132 = 1068 см."]],""],[840,105,"Когда число увеличили на 3, его последняя цифра уменьшилась. На сколько?",{"0":[51.8,68.3,31.4,31.3],"1":[161.8,68.3,31.1,31.3],"2":[278.4,68.3,31.4,31.3],"3":[395.1,68.3,28.4,31.3],"4":[501.5,68.3,31.7,31.3]},"A","Последняя цифра",[["Найди случаи переноса","При добавлении 3 последняя цифра уменьшается только с переходом через десяток: это происходит с цифрами 7, 8 и 9."],["Посмотри, на сколько стало меньше","Получаются 0, 1 и 2. Последняя цифра меняется на 3 − 10, то есть уменьшается на 7."]],""],[840,132,"В некотором году тринадцатое января было вторником. Каким числом в том же месяце был первый понедельник после первого вторника?",{"0":[51.8,95.3,31.4,31.3],"1":[161.8,95.3,31.1,31.3],"2":[278.4,95.3,31.4,31.3],"3":[395.0,95.3,28.5,31.3],"4":[501.5,95.3,31.7,31.3]},"C","Январский понедельник",[["Вернись на неделю","Если 13 января — вторник, то и 6 января — вторник. Предыдущий вторник был ещё в декабре."],["Дойди до понедельника","Понедельник наступит через шесть дней после 6 января. Это 12 января."]],""],[840,187,"Крошка Ру хочет пройти из комнаты А в комнату В (см. рисунок). Через какое наименьшее количество дверей ему придется пройти?",{"0":[51.7,148.4,31.4,31.3],"1":[161.7,148.4,31.1,31.3],"2":[278.3,148.4,31.4,31.3],"3":[395.0,148.4,28.4,31.3],"4":[501.5,148.4,31.7,31.3]},"B","Четыре двери",[["Отметь ближайшие комнаты","Начни в А и помечай комнаты по числу дверей до них. При отметках 1, 2 и 3 до комнаты В ещё не добраться."],["Пройди короткий маршрут","Из А выйди налево, затем два раза вверх и снова налево. Всего на этом пути четыре двери."]],""],[840,129,"Самое маленькое из двузначных чисел с двузначной суммой цифр сложили с самым большим из двузначных чисел с однозначной суммой цифр. Что получилось?",{"0":[51.7,92.7,31.4,31.3],"1":[201.7,92.7,31.1,31.3],"2":[351.6,92.7,31.4,31.3],"3":[501.5,92.7,28.4,31.3],"4":[651.3,92.7,31.7,31.3]},"D","Две суммы цифр",[["Найди первое число","У чисел от 10 до 18 сумма цифр меньше 10. У числа 19 она уже равна 1 + 9 = 10."],["Найди второе и сложи","Самое большое подходящее число — 90. Дальше идут числа с суммой цифр не меньше 10. Получаем 19 + 90 = 109."]],""],[840,243,"На рисунке изображено пять стопок картонных карточек. В каждой стопке три карточки: треугольная, круглая и квадратная. В скольких стопках треугольная карточка лежит выше квадратной?",{"0":[51.6,206.4,31.4,31.3],"1":[201.7,206.4,31.1,31.3],"2":[351.5,206.4,31.4,31.3],"3":[501.5,206.4,28.4,31.3],"4":[644.7,206.4,31.7,31.3]},"C","Карточки в стопках",[["Смотри на границы","В месте пересечения контур верхней карточки закрывает часть контура нижней. Сравнивай только квадрат и треугольник."],["Проверь пять стопок","Треугольник выше квадрата в первой, четвёртой и пятой стопках. Всего три стопки."]],""],[840,133,"Каждую звездочку в примере 2 * 2 * 2 можно заменить на один из знаков арифметического действия. Какой результат нельзя получить?",{"0":[51.6,65.7,31.4,31.3],"1":[201.6,65.7,31.1,31.3],"2":[344.9,65.7,31.4,31.3],"3":[501.4,65.7,28.4,31.3],"4":[51.7,97.5,31.7,31.3]},"E","Знаки вместо звёздочек",[["Получи 1 и 2","Сначала выполни деление 2 ÷ 2 = 1. Если вычесть эту единицу из 2, тоже получится 1."],["Проверь четыре результата","1 = 2 − 2 ÷ 2, 2 = 2 + 2 − 2, 3 = 2 + 2 ÷ 2, 6 = 2 + 2 + 2. Получаются все четыре результата."]],""],[848,126,"Электронные часы показывают часы и минуты. Например, в 6 часов утра они показывают 06 : 00, а в 6 часов вечера — 18 : 00. Сколько минут за сутки на табло часов будут видны ровно три нуля?",{"0":[51.7,89.6,31.4,31.3],"1":[201.7,89.6,31.1,31.3],"2":[351.6,89.6,31.4,31.3],"3":[501.4,89.6,28.5,31.3],"4":[651.4,89.6,31.7,31.3]},"B","Три нуля на часах",[["Начни с полуночи","С 00:00 до 00:59 в часах уже два нуля. В минутах нужен ровно один: 01–09 или 10, 20, 30, 40, 50. Таких моментов 14."],["Добавь остальные часы","У часов 01–09, 10 и 20 по одному нулю. Для них подходят только минуты 00. Получаем ещё 11 моментов, всего 25."]],""],[848,129,"Пять различных точек А, В, С, D и Е расположены на прямой так, что АВ = 6, АD = 2, АЕ = 2, СЕ = 4. Какие две точки крайние?",{"0":[51.8,64.2,31.4,31.3],"1":[201.8,64.2,31.1,31.3],"2":[351.7,64.2,31.4,31.3],"3":[491.5,64.2,28.5,31.3],"4":[51.8,92.3,31.7,31.3]},"A","Крайние точки",[["Размести А, D и Е","Е и D находятся по разные стороны от A на расстоянии 2. Пусть Е справа. В четырёх шагах от Е слева уже стоит D, поэтому С на 6 шагов правее А."],["Размести В","Точка В тоже в 6 шагах от А. Справа это место занято С, поэтому В стоит слева. Крайние точки — В и С."]],""],[848,178,"Аня хочет вписать числа в пустые кружочки так, чтобы на всех сторонах пятиугольника суммы трех чисел были одинаковы. Какое число она должна вписать в закрашенный кружочек?",{"0":[51.7,142.1,31.4,31.3],"1":[161.7,142.1,31.1,31.3],"2":[278.3,142.1,31.4,31.3],"3":[394.9,142.1,28.5,31.3],"4":[501.5,142.1,31.7,31.3]},"C","Суммы на пятиугольнике",[["Убери общий кружок","У двух левых сторон общий пустой кружок. После его вычитания остаётся 7 + 3 = 1 + нижний левый кружок. Значит, в нём 9."],["Сравни оставшиеся стороны","Пусть верхний левый кружок равен x, нижний правый — y. Из x + 1 + 9 = 9 + 6 + y получаем x = y + 5. Поэтому на правой стороне серый кружок равен 5 + 1 + 9 − 2 = 13."]],""],[848,235,"Большой куб 4 × 4 × 4 сложен из 64 маленьких кубиков, один из которых красный, а остальные — белые (см. рисунок). По взмаху волшебной палочки каждый белый кубик, имеющий общую грань с красным кубиком, тоже становится красным. Сколько будет красных кубиков после трех взмахов волшебной палочки?",{"0":[51.8,198.7,31.4,31.3],"1":[201.8,198.7,31.1,31.3],"2":[351.7,198.7,31.4,31.3],"3":[501.6,198.7,28.4,31.3],"4":[651.5,198.7,31.7,31.3]},"B","Красные кубики",[["Измерь путь до кубика","За взмах цвет переходит только через общую грань. В верхнем слое покрасятся кубики не дальше трёх шагов, во втором — двух, в третьем — одного, в нижнем — только кубик под исходным."],["Сложи результаты по слоям","По рисунку в верхнем слое получается 15 кубиков, во втором — 11, в третьем — 5 и в нижнем — 1. Всего 15 + 11 + 5 + 1 = 32."]],""],[848,126,"Два трехзначных числа составлены из шести различных цифр так, что первая цифра второго числа вдвое больше, чем последняя цифра первого числа. Какова наименьшая возможная сумма таких чисел?",{"0":[51.7,90.6,31.4,31.3],"1":[201.7,90.6,31.1,31.3],"2":[351.6,90.6,31.4,31.3],"3":[501.4,90.6,28.4,31.3],"4":[651.3,90.6,31.7,31.3]},"D","Наименьшая сумма",[["Проверь маленькие цифры","Если первое число оканчивается на 1, второе начинается с 2, а первое — не меньше чем с 3. Наименьшая сумма получается у 301 и 245: 546."],["Проверь 2 и большие цифры","Если первое число оканчивается на 2, второе начинается с 4. Берём сотни 1 и 4, десятки 0 и 3, оставшуюся единицу 5: 102 + 435 = 537. При последней цифре от 3 сотни уже дают не меньше 700."]],""],[848,235,"Четыре одинаковых игральных кубика (общее число точек на противоположных гранях равно 7) приложили друг к другу одинаковыми гранями и закрасили некоторые грани (см. рисунок). Какое самое маленькое число точек могло быть закрашено на трех верхних гранях?",{"0":[51.6,198.8,31.4,31.3],"1":[201.6,198.8,31.1,31.3],"2":[351.5,198.8,31.4,31.3],"3":[501.4,198.8,28.4,31.3],"4":[651.3,198.8,31.6,31.3]},"D","Верхние грани кубиков",[["Проверь три кубика в ряду","У левого кубика наверху 5, спереди 4. Слева и справа остаются 1 и 6, и у всего ряда такая же пара боковых граней. На среднем кубике можно поставить наверх 2. Если спереди на правом кубике стоит 5, его верхняя грань при таком повороте — 3."],["Добавь кубик сзади","Правый передний кубик соприкасается с задним гранью 2, противоположной 5. Поэтому задний можно повернуть вокруг этой грани и поставить сверху 1. Минимальная сумма 2 + 3 + 1 = 6."]],""]]],[2017,"3–4 классы",[[841,97,"",{},"E","Самая большая сумма",[["Посмотри на сотни","Только в примере 201 + 7 есть число с сотнями. Все остальные слагаемые меньше 100."],["Сравни результаты","В остальных примерах суммы равны 10, 19, 37 и 28. Число 208 больше каждого из них."]],""],[841,149,"",{},"B","Стрелки до озера",[["Проследи дорогу","Начни у дома и веди пальцем по линии к озеру. На каждом изгибе проверяй, куда показывает острие стрелки."],["Отметь стрелки навстречу","Считай только те стрелки, которые направлены обратно, к уже пройденной части дорожки. Таких стрелок четыре."]],""],[841,94,"",{},"C","Полтора и половина",[["Увеличь число","Полтора раза — это целое число и ещё его половина. Получается 100 + 50 = 150."],["Уменьши результат","Уменьшить вдвое значит поделить пополам. Получаем 150 ÷ 2 = 75."]],""],[841,232,"",{},"A","Те же бусы",[["Следуй по нитке","Начни с подходящей чёрной бусины и пройди всю петлю. По пути получатся чёрная, две белые, две чёрные и белая бусина."],["Сверь тот же порядок","На рисунке А бусины встречаются в таком же порядке. Изгибы нитки можно расправить, не меняя порядок бусин."]],""],[841,122,"",{},"B","Третье число",[["Сравни сотни","Сначала идут числа, начинающиеся с 2: 257 и 275. Потом идут числа, начинающиеся с 5."],["Сравни десятки","Из 527 и 572 раньше стоит 527. Оно третье в списке."]],""],[841,241,"",{},"E","Прозрачные квадраты",[["Совмести клеточки","Смотри, какие клетки у обоих крайних квадратов прозрачные. Если хотя бы один слой чёрный, он закроет фигурку."],["Найди общую прозрачную клетку","Оба слоя прозрачны в середине верхнего ряда. Там нарисован квадрат с крестом."]],""],[848,123,"",{},"D","Раскраска клеток",[["Посчитай клетки","В прямоугольнике 15 клеток: 4 чёрные и 11 белых."],["Закрась по одной","После трёх перекрашиваний будет 7 чёрных и 8 белых. После четвёртого станет 8 чёрных и 7 белых. Значит, нужно четыре."]],""],[848,122,"",{},"D","Треугольники в ряду",[["Разбей ряд на группы","Каждая группа из четырёх фигур содержит один треугольник. В 28 фигурах семь полных групп."],["Проверь конец ряда","Последняя неполная группа состоит из треугольника и круга. Добавь ещё один треугольник: всего восемь."]],""],[848,249,"",{},"A","Дом сзади",[["Проверь трубу","Спереди труба справа. Если обойти дом и посмотреть сзади, она будет слева."],["Найди дверь и два окна","С трубой слева подходящий дом имеет дверь внизу и два окна, одно из которых на крыше. Это рисунок А."]],""],[848,95,"",{},"C","Год без нуля",[["Найди первый подходящий год","В годах 20xx ноль стоит на втором месте. После 2099 года пропускаем 2100–2110, где тоже есть нули. Подходит 2111."],["Вычти текущий год","От 2111 отними 2017: получится 94 года."]],""],[848,122,"",{},"B","Упаковки шариков",[["Проверь три упаковки","Без упаковки на 25 в трёх упаковках не больше 30 шариков. С одной большой упаковкой не больше 45, с двумя — не больше 60, а с тремя получается 75."],["Собери ровно 70","Две большие упаковки дают 50 шариков, две по 10 добавляют ещё 20. Всего четыре упаковки."]],""],[848,222,"",{},"C","Дырки на листе",[["Сравни дырки парами","На развёрнутом листе верхние дырки отражаются в нижних относительно горизонтальной середины. Левые отражаются в правых относительно вертикальной."],["Сложи по двум серединам","Если сначала сложить лист пополам вертикально, а потом горизонтально, четыре дырки совпадут в одном месте. Так выглядят сгибы на рисунке В."]],""],[848,171,"",{},"B","Встреча черепах",[["Оцени путь крайних","Между A и C десять метров. Куда бы ни пришли крайние черепахи, вместе они пройдут не меньше десяти метров."],["Оставь среднюю на месте","При встрече в B крайние пройдут 8 м и 2 м, а средняя останется на месте. Сумма равна 10 м."]],""],[841,122,"",{},"D","Плюсы и умножение",[["Расставь два умножения","Выбирай два промежутка из четырёх для умножения, а в остальные ставь плюсы. При переборе выходят суммы 26, 16, 16, 26, 26 и 28."],["Покажи наибольшее","Самый большой результат даёт запись 1 + 6 + 3 × 1 × 7 = 28."]],""],[841,151,"",{},"C","Периметр полоски",[["Посчитай исходный периметр","У полоски длина 10 и ширина 1. Периметр равен 2 × (10 + 1) = 22."],["Найди новую длину","Удвоенный периметр равен 44, значит длина вместе с шириной равна 22. При ширине 1 длина станет 21. Надо приложить 11 клеток."]],""],[841,153,"",{},"B","Клетка в квадрате",[["Найди размер квадрата","Над клеткой четыре клетки, а под ней три. Считая саму клетку, получаем 4 + 1 + 3 = 8."],["Посчитай с правого края","Справа от шестой клетки из восьми стоят ещё две. Значит, сама клетка третья справа."]],""],[841,275,"",{},"E","Две вырезанные фигурки",[["Посмотри на фигурку Д","В ней пересекаются две полоски длиной в три клетки. Если одна полоска идёт по всей высоте прямоугольника, она проходит через среднюю строку."],["Проверь вторую фигурку","Горизонтальная полоска длины 3 обязательно захватывает оба средних столбца. Если обе фигурки обращены одинаково, их полоски пересекутся. При разных поворотах вертикальная полоска второй стоит в одном из средних столбцов и пересечёт горизонтальную полоску первой. Поэтому двух фигурок Д не вырезать."]],""],[841,125,"",{},"E","Загаданные числа",[["Найди пары Андрея и Бори","Разные положительные числа с суммой 4 — это 1 и 3. Из пар с суммой 7 после этого остаётся только 2 и 5."],["Подбери пару Вити","Для суммы 10 пары 1 и 9, 2 и 8, 3 и 7 запрещены, а две пятёрки одинаковы. Остаются 4 и 6."]],""],[841,157,"",{},"D","Наибольшая сумма в окошке",[["Начни сверху","Сдвигай рамку 2 × 2 по клеткам. Суммы в верхних трёх положениях: 8, 5 и 7. В средних: 13, 12 и 8."],["Проверь нижний ряд положений","Снизу выходят суммы 11, 14 и 9. Самая большая — 14, в нижнем среднем положении рамки."]],""],[841,218,"",{},"B","Повороты в парке",[["Сократи повороты","Три правых поворота уравновешивают три левых. Остаётся один поворот налево и один разворот, равный двум поворотам направо."],["Найди ворота","Разворот и поворот налево вместе дают направление одного поворота направо. Дима въехал вверх по рисунку и выехал вправо, через ворота Б."]],""],[848,148,"",{},"E","Миша и Саша в забеге",[["Разбей бегунов на группы","Если за Мишей одна группа, перед ним три такие же, плюс сам Миша. Без него число бегунов делится на 4."],["Проверь условие Саши","Без Саши число делится на 3: одна группа перед ней и две после. Значит, без одного бегуна число делится и на 4, и на 3. Среди вариантов подходит 25, потому что 24 делится на оба числа."]],""],[848,172,"",{},"B","Цветы под клетками",[["Начни с левой тройки","У неё ровно три серых соседа, поэтому во всех них по цветку. У двойки в третьей строке уже есть два из этих цветков, а значит, её остальные серые соседи пусты."],["Закончи по правой тройке и нижней единице","Правая тройка требует ещё цветок в правом верхнем углу. У двойки слева уже два цветка, поэтому соседние серые клетки третьей строки пусты. Нижняя единица указывает на цветок в левом нижнем углу. Всего пять цветков."]],""],[848,149,"",{},"C","Удивительные числа",[["Найди девятку в единицах","Если десятки не меняются, первые две цифры каждого числа повторяются дважды. Единственная девятка тогда была бы в паре единиц 8 и 9, а число единиц среди шести цифр получилось бы чётным."],["Проверь переход через десяток","Используй переход единиц с 9 на 0. Сотни должны быть 1, а десятки меняются с 0 на 1 или с 1 на 2. Подходят 109 и 119. При переходе через сотню уже было бы две девятки."]],""],[848,149,"",{},"D","Квадратики на кубе",[["Раздели поверхность на группы","У восьми вершин есть по три уголка, откуда можно закрасить по одному. На 12 рёбрах есть по паре средних клеток, и в каждой паре можно закрасить по одной."],["Учти центры граней","Покрашенный центр запрещает четыре соседние клетки. Если покрашены центры двух соседних граней, их общая пара вдоль ребра теряется. Можно добавить два противоположных центра; третий соседствует хотя бы с двумя выбранными, а у четырёх или более центров соседних пар уже не меньше, чем центров. Получается максимум 8 + 12 + 2 = 22."],["Уложи 22 квадратика","На двух противоположных гранях покрась по центру и четырём уголкам. На оставшихся четырёх гранях покрась по одной клетке из каждой пары у рёбер, выбирая клетки со стороны боковых граней."]],""],[848,302,"",{},"A","Карточки на нитке",[["Проследи нитку через отверстия","В стопке все карточки повёрнуты белой стороной в одном направлении. Следи, с какой стороны нитка входит в каждое отверстие при движении вдоль петли."],["Разложи в ряд","При такой раскладке нитка проходит через каждую карточку одинаково. Видимые стороны будут одного цвета, как на рисунке А, где все четыре карточки серые."]],""],[848,147,"",{},"D","Обгон автобусов",[["Отметь минуты","Пусть автобус перед машиной уехал в минуту 0. Машина выехала в минуту 2 и приехала в минуту 37."],["Проверь автобусы впереди","Тот, кто уехал в минуту −24, приехал в минуту 36, раньше машины. Автобусы из минут −21, −18, −15, −12, −9, −6, −3 и 0 приехали позже машины. Она обогнала восемь автобусов."]],""]]],[2018,"3–4 классы",[[841,126,"",{},"B","Цифры в дате конкурса",[["Выпиши цифры","Из даты 15.03.2018 получаются цифры 1, 5, 0, 3, 2, 0, 1 и 8."],["Убери повторения","Ноль и единица записаны по два раза. Остаются шесть разных цифр: 0, 1, 2, 3, 5 и 8."]],""],[841,161,"",{},"D","Пересечения линий",[["Выбери одну линию","Начни у левого конца пунктирной линии и веди по ней пальцем до конца, даже если она делает петлю."],["Отметь встречи","Ставь точку там, где пунктир проходит через сплошную линию. Отметки помогут не считать одно место дважды. Получится девять."]],""],[841,97,"",{},"C","Мартовский снегопад",[["Дойди до полуночи","С 16 часов 15 марта до полуночи прошло 8 часов."],["Добавь утро и день","От полуночи до 15 часов прошло ещё 15. Всего снег шёл 8 + 15 = 23 часа."]],""],[841,179,"",{},"E","Другая божья коровка",[["Посчитай точки на каждом крыле","Поворот меняет положение крыльев на листе, но число пятнышек на каждом остаётся прежним."],["Найди отличие","Мысленно поверни всех коровок головой в одну сторону. Тогда у четырёх коровок крылья с тремя и четырьмя пятнышками совпадут, а у коровки Д эти крылья поменяны местами."]],""],[841,157,"",{},"E","Две аллеи парка",[["Сделай первый шаг","Из O по одной аллее можно дойти до Б или до А."],["Проверь второй шаг","Через Б можно попасть в Г или А, через А — в В или Б. Для точки Д нужно пройти из O через Б и Г, это три аллеи."]],""],[841,181,"",{"0":[51.7,119.8,31.4,26.3],"1":[201.8,119.8,31.1,26.3],"2":[351.6,119.8,31.4,26.3],"3":[51.7,146.9,28.4,26.3],"4":[201.8,146.9,31.7,26.3]},"B","Кораблик из деталей",[["Собери надстройку","Верх кораблика — прямоугольник шириной 6 и высотой 2 клетки. Он составляется из трёх квадратов 2 × 2."],["Собери корпус","Возьми три трапеции, две широкой стороной вверх, среднюю широкой стороной вниз. Сверху получается 6 + 2 + 6 = 14 клеток, снизу 2 + 6 + 2 = 10. Всего нужны шесть деталей."]],""],[841,95,"",{},"D","Цифры вне числа",[["Вычеркни использованные цифры","В числе 2018 есть 2, 0, 1 и 8. Не используются 3, 4, 5, 6, 7 и 9."],["Сложи крайние","Из оставшихся цифр наименьшая — 3, а наибольшая — 9. Их сумма равна 12."]],""],[848,183,"",{"0":[51.7,122.1,31.4,26.3],"1":[201.7,122.1,31.1,26.3],"2":[351.6,122.1,31.4,26.3],"3":[51.7,149.2,28.4,26.3],"4":[201.7,149.2,31.7,26.3]},"C","Окрашенные грани",[["Найди скрытые грани","Краска не попадает только на грани, которыми кубики склеены. Ровно четыре окрашенные грани означают двух соседей."],["Проследи цепочку кубиков","У двух кубиков на концах конструкции лишь по одному соседу. Каждый из остальных восьми кубиков имеет ровно двух."]],""],[848,219,"",{"0":[51.7,140.2,31.4,26.3],"1":[201.7,140.2,31.1,26.3],"2":[351.6,140.2,31.4,26.3],"3":[51.7,167.3,28.4,26.3],"4":[201.7,167.2,31.7,26.3]},"E","Длина шурупов",[["Сравни скрытую и видимую части","Шурупы начинаются на разных высотах и частично закрыты серой деталью. Мысленно продолжи каждый стержень внутри детали."],["Совмести шляпки","Первый и пятый шурупы начинаются на одной высоте. Сквозь одинаковую толщину детали кончик первого выступает, а пятый не выступает. Пятый короче."]],""],[848,127,"",{"0":[51.7,92.8,31.4,26.3],"1":[201.7,92.8,31.1,26.3],"2":[351.6,92.8,31.4,26.3],"3":[501.5,92.8,28.4,26.3],"4":[651.3,92.8,31.7,26.3]},"C","Закрашенные цифры",[["Восстанови единицы","Чтобы после вычитания 6 получить в единицах 8, надо занять десяток: 14 − 6 = 8. В первом числе закрашена цифра 4."],["Восстанови десятки","После займа у первого числа остаётся 3 десятка. В разности один десяток, поэтому у вычитаемого два. Произведение 4 × 2 = 8."]],""],[848,176,"",{"0":[51.7,115.1,31.4,26.3],"1":[201.7,115.1,31.1,26.3],"2":[351.6,115.1,31.4,26.3],"3":[51.7,142.1,28.4,26.3],"4":[201.7,142.1,31.7,26.3]},"D","Стрелы в мишени",[["Найди цену попаданий","При первом выстреле все три стрелы попали во внешнее кольцо и дали 12 очков, по 4 за стрелу. Во второй раз две стрелы в кольце дают 8, значит попадание в центр даёт 15 − 8 = 7."],["Сложи три попадания в центр","В третий раз все три стрелы в центре. Значит, получилось 3 × 7 = 21 очко."]],""],[848,100,"",{"0":[51.7,65.7,31.4,26.3],"1":[245.0,65.7,31.1,26.3],"2":[384.9,65.7,31.4,26.3],"3":[524.7,65.7,28.4,26.3],"4":[668.0,65.7,31.7,26.3]},"C","Середина июня",[["Найди даты","В июне 30 дней. Середина первой половины — 8 июня, середина второй — 23 июня."],["Сравни дни недели","Между датами ровно 15 дней, то есть две недели и один день. За средой на следующий день идёт четверг."]],""],[848,188,"",{"0":[51.7,151.2,31.4,26.3],"1":[161.7,151.1,31.1,26.3],"2":[278.3,151.1,31.4,26.3],"3":[395.0,151.1,28.4,26.3],"4":[501.5,151.1,31.7,26.3]},"A","Наклейка в серой клетке",[["Найди недостающие фигурки","В четвёртой строке уже стоят пустой треугольник, звезда и круг. Не хватает чёрного треугольника и квадрата."],["Проверь третий столбец","В нём квадрат уже стоит сверху. Поэтому в пустую клетку третьего столбца вклей чёрный треугольник, а в серую клетку — квадрат."]],""],[848,124,"",{"0":[51.7,90.5,31.4,26.3],"1":[201.7,90.5,31.1,26.3],"2":[351.5,90.5,31.4,26.3],"3":[501.4,90.5,28.5,26.3],"4":[651.3,90.5,31.7,26.3]},"C","Аня и близнецы",[["Сравни возраст","Аня всегда на восемь лет старше каждого брата. Её возраст — это возраст одного близнеца и ещё восемь лет."],["Найди равенство","Чтобы получилось столько же, сколько дают два брата вместе, второй брат должен добавить ровно восемь лет. Тогда Ане будет 8 + 8 = 16 лет."]],""],[841,122,"",{"0":[51.7,88.4,30.8,26.3],"1":[161.7,88.4,30.7,26.3],"2":[278.3,88.4,30.8,26.3],"3":[395.0,88.4,27.9,26.3],"4":[501.5,88.4,31.1,26.3]},"B","Прямоугольник из квадратов",[["Найди стороны квадратов","Три квадрата по 1 см стоят рядом, поэтому квадрат над ними имеет сторону 3 см. Вместе с нижним рядом высота равна 4 см. Это сторона большого правого квадрата."],["Вычисли периметр","Длина прямоугольника 3 + 4 = 7 см, ширина 4 см. Периметр 2 × (7 + 4) = 22 см."]],""],[841,95,"",{"0":[51.7,60.5,31.4,26.3],"1":[201.7,60.5,31.1,26.3],"2":[351.6,60.5,31.4,26.3],"3":[501.5,60.5,28.4,26.3],"4":[651.4,60.5,31.7,26.3]},"D","Сумма двух чисел",[["Найди одно слагаемое","Если сумма на 6 больше одного слагаемого, второе слагаемое равно 6."],["Умножь на три","Сумма в три раза больше второго слагаемого. Получается 3 × 6 = 18."]],""],[841,198,"",{"0":[51.7,165.0,31.4,26.3],"1":[161.7,165.0,31.1,26.3],"2":[278.3,165.0,31.4,26.3],"3":[395.0,165.0,28.4,26.3],"4":[501.5,165.0,31.7,26.3]},"D","Дорога жука Жака",[["Отмечай возможные шаги","Из клетки 1 помечай соседей с большими числами, затем повторяй это для каждой отмеченной клетки. Из 1 можно сразу пойти к 3, 2 или 9."],["Проверь нижнюю строку","Отметка в нижней строке появляется только у числа 10. Один из путей туда: 1 → 3 → 5 → 6 → 7 → 8 → 9 → 10."]],""],[841,146,"",{"0":[51.7,112.2,31.4,26.3],"1":[178.4,112.2,31.1,26.3],"2":[378.3,112.2,31.4,26.3],"3":[578.2,112.2,28.4,26.3],"4":[694.7,112.2,31.7,26.3]},"D","Секундная стрелка",[["Считай по ходу часов","От верхней отметки до левой по ходу стрелки 45 секунд. От левой до нижней ещё 45, от нижней вверх — 30."],["Добавь полный круг","Две записи «вверх» сделаны в разные моменты, поэтому между ними проходит не меньше 60 секунд. Всего 45 + 45 + 30 + 60 = 180 секунд, то есть 3 минуты."]],""],[841,172,"",{"0":[51.7,112.4,31.4,26.3],"1":[145.0,112.4,31.1,26.3],"2":[245.0,112.4,31.4,26.3],"3":[344.9,112.4,28.4,26.3],"4":[51.7,138.6,31.7,26.3]},"C","Четыре гирьки",[["Прочитай вторые весы","Гирька C равна сумме B и D. Из четырёх масс это возможно только для 30 г = 10 г + 20 г или 40 г = 10 г + 30 г."],["Сравни первые весы","Если C весит 40 г, гирька A весит 20 г. Даже если B весит 30 г, чаши будут равны, а на рисунке A + B тяжелее. При C = 30 г подходят A = 40 г, B = 20 г и D = 10 г."]],""],[841,254,"",{"0":[51.7,193.7,31.4,26.3],"1":[195.1,193.7,31.1,26.3],"2":[378.2,193.7,31.4,26.3],"3":[544.8,193.7,28.4,26.3],"4":[51.7,220.0,31.7,26.3]},"A","Мячи четырёх друзей",[["Найди владельца красного мяча","Если дать красный мяч Пете, Коле или Мите, их фразы будут верны. Только фраза Васи с красным мячом окажется ложной, поэтому красный у Васи."],["Разложи другие цвета","У Мити мяч зелёный: он говорит правду, что у него нет жёлтого и синего. Петя не может взять синий, значит у него жёлтый. Коле остаётся синий."]],""],[841,149,"",{"0":[51.7,115.2,31.4,26.3],"1":[201.7,115.2,31.1,26.3],"2":[351.6,115.2,31.4,26.3],"3":[501.5,115.2,28.4,26.3],"4":[651.3,115.2,31.7,26.3]},"C","Котята и утята",[["Проверь, кто ушёл","Шесть лап — это один котёнок и один утёнок или три утёнка. В комнате было только два утёнка, поэтому ушёл один утёнок."],["Проверь, кто пришёл","Восемь лап со двора — это один котёнок и два утёнка. Четырёх утят во дворе не было, и котёнок был только один. В комнате стало 2 − 1 + 2 = 3 утёнка."]],""],[848,129,"",{"0":[51.7,95.2,31.4,26.3],"1":[201.7,95.2,31.1,26.3],"2":[351.6,95.2,31.4,26.3],"3":[501.5,95.2,28.4,26.3],"4":[651.4,95.2,31.7,26.3]},"B","Обмен цифр",[["Сравни разряды","Чтобы сумма выросла, большая из обмениваемых цифр должна переехать в более старший разряд. Обмены в одном разряде сумму не меняют."],["Найди такой обмен","Из двух чисел подходит только обмен 5 единиц и 2 десятков. Получаем 342 и 951, их сумма 1293."]],""],[848,267,"",{"0":[51.7,203.3,31.4,26.3],"1":[201.7,203.3,31.1,26.3],"2":[351.6,203.3,31.4,26.3],"3":[51.7,232.6,28.4,26.3],"4":[201.7,232.6,31.7,26.3]},"A","Дорожки у моста",[["Убери лишние участки","Сложи два пути через мост: от Пятачка к Винни-Пуху и от Совы к Кролику. Получилось 160 + 190 = 350 м."],["Вычти мост и правый берег","Путь Винни-Пух — Сова целиком на правом берегу и даёт 200 м. Ещё дважды посчитан мост по 10 м. На левом берегу остаётся 350 − 200 − 20 = 130 м."]],""],[848,286,"",{"0":[51.7,252.7,31.4,26.3],"1":[201.7,252.7,31.1,26.3],"2":[351.6,252.7,31.4,26.3],"3":[501.5,252.7,28.4,26.3],"4":[651.3,252.7,31.7,26.3]},"C","Цифры из спичек",[["Собери самое длинное число","На каждую цифру нужны хотя бы две спички. Из 17 спичек получится не больше восьми цифр. Восемь единиц требуют 16 спичек."],["Увеличь первую цифру","Осталась одна спичка. Заменив первую единицу на семёрку, которая состоит из трёх спичек, получим самое большое восьмизначное число."]],""],[848,189,"",{"0":[51.7,123.9,31.4,26.3],"1":[201.7,123.9,31.1,26.3],"2":[351.6,123.9,31.4,26.3],"3":[51.7,155.7,28.4,26.3],"4":[201.7,155.7,31.7,26.3]},"D","Ребус про кенгуру",[["Начни с краёв","Сумма 256 и трёхзначного числа не больше 1255. Поэтому Г = 1, а У = 0, ведь цифры 1 и 2 уже использованы. По единицам 6 + Н = 10, значит Н = 4."],["Доведи сложение до конца","В разряде сотен К = 8 без переноса или К = 7 с переносом. С переносом для Е остаются 8 и 9, но тогда в десятках вышли бы уже занятые 4 или 5. Без переноса Е = 3, Р = 9. Получаем 256 + 834 = 1090, и не использована цифра 7."]],""],[848,174,"",{"0":[51.7,94.9,31.4,26.3],"1":[201.7,94.9,31.1,26.3],"2":[351.6,94.9,31.4,26.3],"3":[51.7,126.6,28.4,26.3],"4":[201.7,126.6,31.7,26.3]},"D","Квадраты по жирным линиям",[["Считай ровные квадраты по размеру","Со стороной 1 клетка получается 4 квадрата, со стороной 2 — 9, со стороной 3 — 4, со стороной 4 — 5. Со стороной 5 нет ни одного, а со стороной 6 есть один."],["Добавь наклонный квадрат","Диагональные линии образуют один большой наклонный квадрат. Всего 4 + 9 + 4 + 5 + 1 + 1 = 24."]],""]]],[2019,"3–4 классы",[[841,123,"",{},"B","Возраст кенгурёнка",[["Отмечай одинаковое число","От 21 ноября до 21 декабря проходит один месяц. До 21 января — два месяца."],["Продолжи до марта","До 21 февраля проходит три месяца, до 21 марта — четыре."]],""],[841,232,"",{},"E","Третье место",[["Прочитай высоту пьедестала","Сравни уровни под ногами участников. Первое место у номера 6, на следующей ступеньке стоит номер 8."],["Найди следующую ступеньку","Третья по высоте ступенька находится справа. На ней стоит участник с номером 9."]],""],[841,141,"",{},"B","Число майя",[["Посчитай отрезки","На рисунке два отрезка, каждый обозначает 5. Вместе они дают 10."],["Добавь точки","Две точки дают ещё 2, поэтому записано число 12."]],""],[841,196,"",{},"C","Кусочек из квадрата",[["Ищи соседние клетки","Кусочек состоит из двух клеток с общей стороной. Его можно повернуть, но символы должны повернуться вместе с ним."],["Найди нужную пару","В третьей строке справа стоят трефа и перевёрнутое сердечко. Это пара из варианта В."]],""],[841,98,"",{},"A","День послезавтра",[["Определи сегодняшний день","Если вчера была суббота, то сегодня воскресенье."],["Отсчитай два дня","Завтра будет понедельник, послезавтра — вторник."]],""],[841,205,"",{},"D","Дорога к Пятачку",[["Проследи направления","От Винни-Пуха идти можно только туда, куда указывают стрелки. Попробуй ветки через А, Б и Д: они не приводят к Пятачку."],["Найди связную цепочку","По дорожке, которая поднимается к точке Г, можно затем пройти по стрелке к Пятачку. Поэтому пройти нужно через Г."]],""],[849,193,"",{},"C","Фигуры из четырёх клеток",[["Убирай по краю","Если убрать верхнюю клетку, получится зигзаг из четырёх клеток. Если убрать выступ справа, получится уголок с длинной стороной."],["Проверь остальные клетки","Убрав выступ слева внизу, получим букву Т после поворота. При удалении любой другой клетки фигура распадается. Получаются три фигуры из ряда."]],""],[849,66,"",{},"D","Наименьшее число",[["Сначала сравни длину","Три числа имеют по пять цифр: 50050, 50005 и 55000. Шестизначные числа больше всех трёх."],["Сравни слева направо","У 55000 больше тысяч, а у 50050 больше десятков, чем у 50005. Самое маленькое — 50005."]],""],[849,326,"",{},"E","Фигуры из спичек",[["Посчитай отдельные отрезки","В вариантах А, Б, В и Г по 10 спичек. Каждую длинную сторону считай по отдельным спичкам."],["Проверь крест","У каждого из четырёх выступов креста три наружные стороны по одной спичке. Всего нужно 4 × 3 = 12 спичек."]],""],[849,147,"",{},"E","День рождения в октябре",[["Запиши номер месяца","Октябрь — десятый месяц, значит последние две цифры даты — 10."],["Используй оставшиеся цифры","Для дня остались 2 и 9. В октябре есть 29-е число, а 92-го нет."]],""],[849,121,"",{},"D","Цифры по убыванию",[["Выбери две цифры после 4","После четвёрки подходят только 0, 1, 2 и 3. Выбранная пара записывается в одном порядке, сначала большая цифра."],["Составь список","Получаем 410, 420, 421, 430, 431 и 432. Всего шесть чисел."]],""],[849,266,"",{},"E","Окошки в обложке",[["Представь сгиб по корешку","При закрытии клетки обложки окажутся на таком же расстоянии от корешка, но с другой стороны."],["Приложи окошки","Узкое окошко откроет серый квадрат, а широкое — серый и чёрный круги."]],""],[841,116,"",{},"D","Рыбки в аквариуме",[["Найди сомиков и барбусов","Из 15 рыб 10 не сомики, значит сомиков 5. Из 15 рыб 9 не барбусы, значит барбусов 6."],["Посчитай оставшихся","Остальные рыбки — меченосцы. Их 15 − 5 − 6 = 4."]],""],[841,248,"",{},"A","Последняя половинка домино",[["Посчитай точки на половинках","Среди половинок единица встречается четыре раза, а каждое из чисел 2, 3, 4 и 5 — по два раза."],["Выдели крайние половинки","Внутри цепочки соседние половинки образуют пары одинаковых чисел. На первом краю остаётся единица, а всего единиц чётное число. Значит, на другом краю тоже единица."]],""],[841,120,"",{},"C","Два языка в классе",[["Сложи два списка","По списку китайского языка записано 5 человек, по списку японского — 6. При сложении получается 11 записей."],["Найди повторения","Учеников всего 8. Лишние 11 − 8 = 3 записи появились из-за тех, кто изучает оба языка. Их три."]],""],[841,160,"",{},"E","Кружок, звезда и сердце",[["Найди значение круга","Три одинаковых кружка дают 12, поэтому один кружок равен 4. Из первой строки звезда и сердце вместе дают 15 − 4 = 11."],["Сравни с третьей строкой","Там звезда и два сердца дают 16, поэтому дополнительное сердце равно 16 − 11 = 5. Звезда равна 11 − 5 = 6."]],""],[841,219,"",{},"E","У кого футбольный мяч",[["Сравни слова Алёши и Дани","Алёша говорит, что у него мяча нет, а Даня говорит, что мяч у Алёши. Из этих двоих один точно соврал."],["Проверь слова Бори","Все остальные сказали правду. Боря сказал, что мяч у него. Значит, Алёша тоже сказал правду, а соврал Даня."]],""],[841,91,"",{},"C","Наибольшее число после обмена",[["Поставь 9 впереди","Чтобы получить наибольшее число, постарайся поставить 9 в разряд сотен. Поменяв 2 и 9, получаем 9012. Из него лучше всего вычеркнуть 0, остаётся 912."],["Проверь другой способ","Можно поставить 9 второй, обменяв её с нулём, и стереть первую цифру. Из 2910 получится 910. Все варианты с меньшей цифрой впереди уступают 912."]],""],[841,168,"",{},"D","Гномики на весах",[["Прочитай наклон чаш","На первых весах один гномик легче гири в 7 кг. На вторых два гномика тяжелее гири в 11 кг."],["Найди целый вес","Один гномик весит больше 5 с половиной килограммов, но меньше 7 кг. Единственное целое число между ними — 6."]],""],[841,93,"",{},"B","Пятёрки в номерах страниц",[["Дойди до 50-й страницы","В номерах 5, 15, 25, 35 и 45 уже набралось пять пятёрок."],["Проверь страницы с пятью десятками","С 50-й по 56-ю страницу включительно в десятках ещё семь пятёрок, а в числе 55 есть пятёрка и в единицах. Всего ровно 13, а на странице 57 была бы лишняя пятёрка."]],""],[849,266,"",{},"A","Шнурок в дощечке",[["Переверни положение дырок","Если посмотреть с обратной стороны, левая и правая стороны меняются местами. Верхняя средняя дырка остаётся пустой."],["Проведи один непрерывный шнурок","На рисунке А после входа сверху слева шнурок проходит через центр, правый столбец, нижний ряд и среднюю левую дырку, а затем выходит из верхнего правого угла. На обеих сторонах вместе получается одна нить через все занятые дырки."]],""],[849,116,"",{},"A","Супердвузначные числа",[["Найди границы","Деление на 2 должно давать не меньше 10, поэтому исходное число не меньше 20. Удвоение должно давать не больше 99, поэтому исходное число не больше 49."],["Оставь чётные числа","Чтобы половина была целым двузначным числом, подходят 20, 22, 24 и так далее до 48. Всего 15 чисел."]],""],[849,168,"",{},"E","Кот в коридоре",[["Найди длину горизонтальных участков","Ширина вертикального участка 40 − 36 = 4 м. По середине нижний горизонтальный путь составляет 36 + 2 = 38 м, а верхний — 28 − 2 = 26 м."],["Найди подъём по середине","От отмеченных 20 м отними половину ширины нижней части, 4 м, и добавь половину ширины верхней, 3 м. Подъём равен 19 м, весь путь 38 + 19 + 26 = 83 м."]],""],[849,193,"",{},"C","Суммы на гранях куба",[["Соедини противоположные грани","Каждая пара противоположных граней вместе содержит все числа от 1 до 8. Их сумма 36."],["Дополни до 36","Граням с суммами 16, 18 и 22 противоположны грани с суммами 20, 18 и 14. Среди всех шести чисел наименьшее — 14."]],""],[849,167,"",{},"C","Кто сколько съел плюшек",[["Найди долю фрекен Бок","Пока фрекен Бок ест 7 плюшек, Малыш ест 2. Вместе 9. Если вдвоём они съели 27, фрекен Бок съела 3 × 7 = 21."],["Посчитай плюшки Карлсона","На каждые три плюшки фрекен Бок у Карлсона приходится пять. В 21 плюшке семь троек, поэтому Карлсон съел 7 × 5 = 35."]],""],[849,193,"",{},"C","Равные суммы в областях",[["Начни с левого нижнего угла","Сумма всей таблицы 75, каждой области — 25. Снизу слева три числа с двойкой могут дать не больше 11, два числа в строке выше — не больше 9, а число над ними — не больше 5. Чтобы получить 25, берём все три максимума. Снизу слева выходят 2, 4, 5, над ними — 4 и 5, выше — 5."],["Обратись к правой области","Её нижняя клетка не может быть 5: тогда во второй строке нужно набрать хотя бы 8, то есть поставить 5 в четвёртый столбец. В первой строке тоже нужна 5, но она уже стоит в каждом из трёх столбцов этой области. Значит, снизу стоит 4: меньше не хватит для суммы 25."],["Найди верхнее число","Теперь во второй строке нужны 4 и 5, при этом пятёрка стоит справа. Верхняя строка области содержит 3, 4 и 5. Справа уже есть 4 и 5, поэтому в угол впиши 3."]],""]]]];
